INSERT INTO public.personas (id, name, bio, birth_year, death_year) VALUES
  ('a0000000-0000-0000-0000-000000000009', 'Isaac Newton', 'English mathematician and physicist who formulated the laws of motion and universal gravitation; his Principia Mathematica is one of the most important scientific works ever written.', 1643, 1727),
  ('a0000000-0000-0000-0000-00000000000a', 'Galileo Galilei', 'Italian astronomer and physicist who championed heliocentrism and made foundational contributions to observational astronomy and the scientific method.', 1564, 1642),
  ('a0000000-0000-0000-0000-00000000000b', 'Charles Darwin', 'English naturalist who developed the theory of evolution by natural selection, published in On the Origin of Species in 1859, transforming biology forever.', 1809, 1882),
  ('a0000000-0000-0000-0000-00000000000c', 'Nikola Tesla', 'Serbian-American inventor and electrical engineer who developed alternating current electrical systems and made pioneering contributions to radio and electromagnetism.', 1856, 1943),
  ('a0000000-0000-0000-0000-00000000000d', 'Stephen Hawking', 'British theoretical physicist who made landmark contributions to cosmology and black hole physics while living for decades with motor neurone disease.', 1942, 2018),
  ('a0000000-0000-0000-0000-00000000000e', 'Richard Feynman', 'American theoretical physicist and Nobel laureate celebrated for his work in quantum electrodynamics and his extraordinary ability to communicate complex science.', 1918, 1988),
  ('a0000000-0000-0000-0000-00000000000f', 'Alan Turing', 'British mathematician and computer science pioneer who broke the Enigma cipher in WWII and laid the conceptual foundations of modern computing.', 1912, 1954),
  ('a0000000-0000-0000-0000-000000000010', 'Niels Bohr', 'Danish physicist who proposed the Bohr model of the atom and made foundational contributions to quantum mechanics, winning the Nobel Prize in 1922.', 1885, 1962),
  ('a0000000-0000-0000-0000-000000000011', 'Max Planck', 'German theoretical physicist who originated quantum theory by proposing that energy is emitted in discrete quanta, earning the 1918 Nobel Prize in Physics.', 1858, 1947),
  ('a0000000-0000-0000-0000-000000000012', 'Michael Faraday', 'English scientist who discovered electromagnetic induction and electrolysis, laying the groundwork for electric motors and generators despite having no formal education.', 1791, 1867),
  ('a0000000-0000-0000-0000-000000000013', 'Louis Pasteur', 'French chemist and microbiologist who developed germ theory, pasteurization, and vaccines for rabies and anthrax, saving countless lives.', 1822, 1895),
  ('a0000000-0000-0000-0000-000000000014', 'Ada Lovelace', 'English mathematician regarded as the first computer programmer for her notes on Babbage''s Analytical Engine, which included the first algorithm intended for a machine.', 1815, 1852),
  ('a0000000-0000-0000-0000-000000000015', 'Robert Oppenheimer', 'American theoretical physicist who directed the Manhattan Project, leading the team that built the first nuclear weapons; later opposed nuclear proliferation.', 1904, 1967),
  ('a0000000-0000-0000-0000-000000000016', 'John von Neumann', 'Hungarian-American mathematician who made major contributions to quantum mechanics, game theory, and computer architecture, including the stored-program concept.', 1903, 1957),
  ('a0000000-0000-0000-0000-000000000017', 'Emmy Noether', 'German mathematician who revolutionised abstract algebra and whose theorem linking symmetry and conservation laws is a cornerstone of modern theoretical physics.', 1882, 1935),
  ('a0000000-0000-0000-0000-000000000018', 'Srinivasa Ramanujan', 'Indian self-taught mathematical genius who made extraordinary contributions to number theory and infinite series, producing results that mathematicians are still proving today.', 1887, 1920),
  ('a0000000-0000-0000-0000-000000000019', 'Carl Sagan', 'American astronomer and science communicator who hosted Cosmos and co-wrote the Voyager Golden Record, inspiring generations to look at the universe with wonder.', 1934, 1996),
  ('a0000000-0000-0000-0000-00000000001a', 'Tim Berners-Lee', 'British computer scientist who invented the World Wide Web in 1989 while at CERN and continues to advocate for an open, neutral internet.', 1955, NULL),
  ('a0000000-0000-0000-0000-00000000001b', 'Linus Torvalds', 'Finnish-American software engineer who created the Linux kernel in 1991 and the Git version control system, foundational tools of modern computing.', 1969, NULL),
  ('a0000000-0000-0000-0000-00000000001c', 'Grace Hopper', 'American computer scientist and Navy admiral who invented the first compiler and championed machine-independent programming languages, coining the term "debugging".', 1906, 1992),
  ('a0000000-0000-0000-0000-00000000001d', 'Werner Heisenberg', 'German theoretical physicist who formulated the uncertainty principle and matrix mechanics, becoming a central figure in quantum mechanics and winning the 1932 Nobel Prize.', 1901, 1976),
  ('a0000000-0000-0000-0000-00000000001e', 'Erwin Schrödinger', 'Austrian physicist who formulated the Schrödinger equation central to quantum mechanics and devised his famous thought experiment about a cat in superposition.', 1887, 1961),
  ('a0000000-0000-0000-0000-00000000001f', 'Claude Shannon', 'American mathematician who founded information theory with his 1948 paper, defining the bit and proving fundamental limits on data compression and transmission.', 1916, 2001),
  ('a0000000-0000-0000-0000-000000000020', 'Alexander Fleming', 'Scottish bacteriologist who discovered penicillin in 1928, accidentally observing mould killing bacteria and launching the antibiotic era that transformed medicine.', 1881, 1955),
  ('a0000000-0000-0000-0000-000000000021', 'Francis Crick', 'British molecular biologist who co-discovered the double-helix structure of DNA with James Watson in 1953, earning a Nobel Prize and reshaping biology.', 1916, 2004),
  ('a0000000-0000-0000-0000-000000000022', 'Carl Linnaeus', 'Swedish botanist who created the binomial nomenclature system for classifying organisms, laying the foundations of modern taxonomy and biological nomenclature.', 1707, 1778),
  ('a0000000-0000-0000-0000-000000000023', 'Antoine Lavoisier', 'French chemist considered the father of modern chemistry who identified oxygen and hydrogen, established the law of conservation of mass, and reformed chemical nomenclature.', 1743, 1794),
  ('a0000000-0000-0000-0000-000000000024', 'Blaise Pascal', 'French mathematician and physicist who invented one of the first mechanical calculators, made contributions to probability theory, and wrote the influential Pensées.', 1623, 1662),
  ('a0000000-0000-0000-0000-000000000025', 'Gottfried Leibniz', 'German polymath who independently developed calculus alongside Newton, invented binary arithmetic, and made major contributions to philosophy and metaphysics.', 1646, 1716),
  ('a0000000-0000-0000-0000-000000000026', 'Johannes Kepler', 'German astronomer who discovered the three laws of planetary motion, providing the mathematical foundation for Newton''s law of gravitation.', 1571, 1630),
  ('a0000000-0000-0000-0000-000000000027', 'Gregor Mendel', 'Austrian friar and scientist whose pea plant experiments laid the foundation for the laws of genetic inheritance, making him the father of modern genetics.', 1822, 1884),
  ('a0000000-0000-0000-0000-000000000028', 'Alexander Graham Bell', 'Scottish-born inventor credited with patenting the first practical telephone in 1876, transforming global communications and founding AT&T.', 1847, 1922),
  ('a0000000-0000-0000-0000-000000000029', 'Julius Caesar', 'Roman general and statesman who conquered Gaul, crossed the Rubicon to seize power, and was assassinated on the Ides of March; his name became a title for emperors.', -100, -44),
  ('a0000000-0000-0000-0000-00000000002a', 'Alexander the Great', 'Macedonian king who created one of the largest empires in history by age 30, spreading Greek culture from Greece to northwestern India through relentless military conquest.', -356, -323),
  ('a0000000-0000-0000-0000-00000000002b', 'Napoleon Bonaparte', 'French military commander and emperor who conquered much of Europe, reformed French law through the Napoleonic Code, and reshaped the political map of the continent.', 1769, 1821),
  ('a0000000-0000-0000-0000-00000000002c', 'Abraham Lincoln', 'American president who guided the United States through the Civil War, issued the Emancipation Proclamation, and preserved the Union before being assassinated in 1865.', 1809, 1865),
  ('a0000000-0000-0000-0000-00000000002d', 'Winston Churchill', 'British statesman who led the UK through World War II with defiant oratory and strategic resolve, later winning the Nobel Prize in Literature for his historical writings.', 1874, 1965),
  ('a0000000-0000-0000-0000-00000000002e', 'Mahatma Gandhi', 'Indian independence leader who pioneered non-violent civil disobedience to end British colonial rule in India, inspiring human rights movements worldwide.', 1869, 1948),
  ('a0000000-0000-0000-0000-00000000002f', 'Nelson Mandela', 'South African anti-apartheid revolutionary who spent 27 years in prison before becoming South Africa''s first democratically elected president in 1994.', 1918, 2013),
  ('a0000000-0000-0000-0000-000000000030', 'George Washington', 'American military commander who led the Continental Army to victory in the Revolutionary War and became the first President of the United States.', 1732, 1799),
  ('a0000000-0000-0000-0000-000000000031', 'Franklin D. Roosevelt', 'American president elected four times who led the US through the Great Depression with the New Deal and guided the nation through most of World War II.', 1882, 1945),
  ('a0000000-0000-0000-0000-000000000032', 'Joseph Stalin', 'Soviet dictator who industrialised the USSR through brutal Five-Year Plans, led the Soviet Union to victory over Nazi Germany, and ruled by mass terror.', 1878, 1953),
  ('a0000000-0000-0000-0000-000000000033', 'Mao Zedong', 'Chinese revolutionary leader who founded the People''s Republic of China in 1949 and ruled it until his death, overseeing both rapid industrialisation and catastrophic famines.', 1893, 1976),
  ('a0000000-0000-0000-0000-000000000034', 'Queen Elizabeth I', 'Queen of England who presided over the Elizabethan era, defeating the Spanish Armada and fostering a flourishing of arts and exploration during her 44-year reign.', 1533, 1603),
  ('a0000000-0000-0000-0000-000000000035', 'Cleopatra', 'Last active ruler of the Ptolemaic Kingdom of Egypt, who allied with Julius Caesar and Mark Antony before her kingdom was conquered by Rome after her death.', -69, -30),
  ('a0000000-0000-0000-0000-000000000036', 'Catherine the Great', 'German-born Empress of Russia who greatly expanded the empire, modernised governance, and made Russia a major European power during her 34-year reign.', 1729, 1796),
  ('a0000000-0000-0000-0000-000000000037', 'Genghis Khan', 'Founder of the Mongol Empire, the largest contiguous land empire in history, who united the Mongolian tribes and conquered vast territories across Asia and Europe.', 1162, 1227),
  ('a0000000-0000-0000-0000-000000000038', 'Charlemagne', 'King of the Franks who united much of Western Europe into the Carolingian Empire and was crowned first Holy Roman Emperor by Pope Leo III on Christmas Day 800.', 742, 814),
  ('a0000000-0000-0000-0000-000000000039', 'Peter the Great', 'Tsar of Russia who modernised the country along Western lines, founded St. Petersburg, and transformed Russia into a major imperial power through sweeping reforms.', 1672, 1725),
  ('a0000000-0000-0000-0000-00000000003a', 'Otto von Bismarck', 'Prussian statesman who unified the German states into the German Empire in 1871 and served as its first Chancellor, shaping European balance-of-power politics.', 1815, 1898),
  ('a0000000-0000-0000-0000-00000000003b', 'Vladimir Lenin', 'Russian revolutionary who led the Bolshevik Revolution of 1917, founded the Soviet Union, and established the first communist state in history.', 1870, 1924),
  ('a0000000-0000-0000-0000-00000000003c', 'Martin Luther King Jr.', 'American Baptist minister and civil rights leader whose nonviolent campaigns and "I Have a Dream" speech were pivotal to the passage of the Civil Rights Act of 1964.', 1929, 1968),
  ('a0000000-0000-0000-0000-00000000003d', 'John F. Kennedy', 'American president who navigated the Cuban Missile Crisis, launched the Apollo programme, and was assassinated in Dallas in 1963, becoming an enduring symbol of idealism.', 1917, 1963),
  ('a0000000-0000-0000-0000-00000000003e', 'Margaret Thatcher', 'British Conservative Prime Minister known as the "Iron Lady" who pursued free-market policies, privatised state industries, and transformed British economic policy.', 1925, 2013),
  ('a0000000-0000-0000-0000-00000000003f', 'Mikhail Gorbachev', 'Last leader of the Soviet Union whose policies of glasnost and perestroika helped end the Cold War and led to the dissolution of the USSR in 1991.', 1931, 2022),
  ('a0000000-0000-0000-0000-000000000040', 'Jawaharlal Nehru', 'First Prime Minister of independent India who shaped the country''s secular democratic constitution and pursued non-alignment foreign policy during the Cold War.', 1889, 1964),
  ('a0000000-0000-0000-0000-000000000041', 'Kemal Atatürk', 'Founder of modern Turkey who abolished the Ottoman Caliphate, created a secular republic, and carried out sweeping modernisation reforms including adopting the Latin alphabet.', 1881, 1938),
  ('a0000000-0000-0000-0000-000000000042', 'Simón Bolívar', 'Venezuelan military and political leader who liberated six South American countries from Spanish rule, becoming the most celebrated figure in Latin American history.', 1783, 1830),
  ('a0000000-0000-0000-0000-000000000043', 'Frederick the Great', 'King of Prussia who transformed his kingdom into a major European power through military genius and administrative reform, also a talented musician and patron of the arts.', 1712, 1786),
  ('a0000000-0000-0000-0000-000000000044', 'Joan of Arc', 'French peasant girl who led French armies to crucial victories during the Hundred Years'' War at age 17, was burned at the stake by the English, and became a national saint.', 1412, 1431),
  ('a0000000-0000-0000-0000-000000000045', 'Queen Victoria', 'British queen who reigned for 63 years over the vast British Empire at its peak, giving her name to an era defined by industrial expansion and strict moral values.', 1819, 1901),
  ('a0000000-0000-0000-0000-000000000046', 'Louis XIV', 'French king known as the Sun King who built Versailles, centralised power in the monarchy, and reigned for 72 years — the longest of any major European monarch.', 1638, 1715),
  ('a0000000-0000-0000-0000-000000000047', 'Henry VIII', 'English king who broke from the Catholic Church to annul his marriage, triggering the English Reformation; famous for his six wives and his consolidation of royal power.', 1491, 1547),
  ('a0000000-0000-0000-0000-000000000048', 'Harriet Tubman', 'American abolitionist and political activist who escaped slavery and then rescued approximately 70 enslaved people via the Underground Railroad over 13 missions.', 1822, 1913),
  ('a0000000-0000-0000-0000-000000000049', 'Frederick Douglass', 'American abolitionist who escaped slavery to become one of the most influential writers and orators of the 19th century, advising President Lincoln during the Civil War.', 1818, 1895),
  ('a0000000-0000-0000-0000-00000000004a', 'Ho Chi Minh', 'Vietnamese revolutionary leader who founded the Viet Minh independence movement and became the first president of North Vietnam, driving both French and American forces from his country.', 1890, 1969),
  ('a0000000-0000-0000-0000-00000000004b', 'Fidel Castro', 'Cuban revolutionary and statesman who led the 1959 revolution, established a communist government in Cuba, and remained in power for nearly five decades.', 1926, 2016),
  ('a0000000-0000-0000-0000-00000000004c', 'Che Guevara', 'Argentine Marxist revolutionary who played a key role in the Cuban Revolution and became a global symbol of anti-imperialism before being captured and executed in Bolivia.', 1928, 1967),
  ('a0000000-0000-0000-0000-00000000004d', 'Augustus Caesar', 'First Roman Emperor who transformed Rome from a republic into an empire, inaugurating two centuries of relative peace known as the Pax Romana after defeating Mark Antony.', -63, 14),
  ('a0000000-0000-0000-0000-00000000004e', 'Ramesses II', 'Egyptian pharaoh often regarded as the greatest and most celebrated ruler of ancient Egypt; he reigned for 66 years, building Abu Simbel and fighting the Battle of Kadesh.', -1303, -1213),
  ('a0000000-0000-0000-0000-00000000004f', 'Attila the Hun', 'Leader of the Hunnic Empire who terrorised the Roman Empire with devastating raids across Europe, earning the nickname "Scourge of God" from trembling Christian populations.', 406, 453),
  ('a0000000-0000-0000-0000-000000000050', 'Saladin', 'Kurdish Muslim sultan who united the Muslim world, recaptured Jerusalem from the Crusaders in 1187, and was renowned even by his enemies for chivalry and honour.', 1137, 1193),
  ('a0000000-0000-0000-0000-000000000051', 'William Shakespeare', 'English playwright and poet widely regarded as the greatest writer in the English language; his 37 plays and 154 sonnets continue to shape literature and language worldwide.', 1564, 1616),
  ('a0000000-0000-0000-0000-000000000052', 'Charles Dickens', 'English novelist whose serialised stories of Victorian poverty and injustice, including Oliver Twist and A Tale of Two Cities, made him the most popular writer of his era.', 1812, 1870),
  ('a0000000-0000-0000-0000-000000000053', 'Leo Tolstoy', 'Russian novelist and moral philosopher whose epic novels War and Peace and Anna Karenina are considered pinnacles of realistic fiction.', 1828, 1910),
  ('a0000000-0000-0000-0000-000000000054', 'Fyodor Dostoyevsky', 'Russian novelist whose works exploring human psychology and suffering, including Crime and Punishment and The Brothers Karamazov, profoundly influenced world literature.', 1821, 1881),
  ('a0000000-0000-0000-0000-000000000055', 'Ernest Hemingway', 'American novelist and journalist known for his spare prose style; his works including The Old Man and the Sea earned him the 1954 Nobel Prize in Literature.', 1899, 1961),
  ('a0000000-0000-0000-0000-000000000056', 'Virginia Woolf', 'English modernist novelist and essayist who pioneered stream-of-consciousness narrative in works like Mrs Dalloway and To the Lighthouse.', 1882, 1941),
  ('a0000000-0000-0000-0000-000000000057', 'Jane Austen', 'English novelist whose six major works including Pride and Prejudice and Emma are celebrated for their wit, social observation, and exploration of women''s lives.', 1775, 1817),
  ('a0000000-0000-0000-0000-000000000058', 'George Orwell', 'English novelist and essayist whose dystopian novels Animal Farm and Nineteen Eighty-Four remain definitive warnings about totalitarianism and propaganda.', 1903, 1950),
  ('a0000000-0000-0000-0000-000000000059', 'Gabriel García Márquez', 'Colombian novelist who pioneered magic realism with One Hundred Years of Solitude and won the 1982 Nobel Prize in Literature.', 1927, 2014),
  ('a0000000-0000-0000-0000-00000000005a', 'Franz Kafka', 'Czech-German novelist whose surreal, nightmarish works including The Metamorphosis and The Trial gave rise to the adjective "Kafkaesque" for bureaucratic absurdity.', 1883, 1924),
  ('a0000000-0000-0000-0000-00000000005b', 'J.R.R. Tolkien', 'English author and philologist who created Middle-earth in The Hobbit and The Lord of the Rings, laying the foundations of modern fantasy literature.', 1892, 1973),
  ('a0000000-0000-0000-0000-00000000005c', 'Agatha Christie', 'English crime novelist and playwright who created Hercule Poirot and Miss Marple; her 66 detective novels make her the best-selling fiction writer in history.', 1890, 1976),
  ('a0000000-0000-0000-0000-00000000005d', 'Mark Twain', 'American writer whose Adventures of Huckleberry Finn and The Adventures of Tom Sawyer are classics of American literature celebrated for their humour and social critique.', 1835, 1910),
  ('a0000000-0000-0000-0000-00000000005e', 'Oscar Wilde', 'Irish playwright and wit whose works including The Picture of Dorian Gray and The Importance of Being Earnest are celebrated for their epigrams and social satire.', 1854, 1900),
  ('a0000000-0000-0000-0000-00000000005f', 'Victor Hugo', 'French poet and novelist who wrote Les Misérables and The Hunchback of Notre-Dame; a leading figure of French Romanticism and a passionate political activist.', 1802, 1885),
  ('a0000000-0000-0000-0000-000000000060', 'Edgar Allan Poe', 'American writer who invented the detective fiction genre and pioneered gothic horror with tales like The Raven and The Tell-Tale Heart.', 1809, 1849),
  ('a0000000-0000-0000-0000-000000000061', 'Arthur Conan Doyle', 'Scottish physician and writer who created Sherlock Holmes, one of the most famous fictional characters in literary history, in 60 stories spanning 40 years.', 1859, 1930),
  ('a0000000-0000-0000-0000-000000000062', 'J.K. Rowling', 'British author of the Harry Potter series, which became the best-selling book series in history and transformed children''s publishing and global popular culture.', 1965, NULL),
  ('a0000000-0000-0000-0000-000000000063', 'Pablo Picasso', 'Spanish painter and sculptor who co-founded Cubism and created Guernica; one of the most influential and prolific artists of the 20th century.', 1881, 1973),
  ('a0000000-0000-0000-0000-000000000064', 'Vincent van Gogh', 'Dutch Post-Impressionist painter whose emotionally charged works including Starry Night and Sunflowers were largely unrecognised in his lifetime but now rank among the world''s most valuable.', 1853, 1890),
  ('a0000000-0000-0000-0000-000000000065', 'Frida Kahlo', 'Mexican painter celebrated for her deeply personal self-portraits blending surrealism and Mexican folk traditions; a feminist and political icon.', 1907, 1954),
  ('a0000000-0000-0000-0000-000000000066', 'Salvador Dalí', 'Spanish Surrealist painter whose flamboyant personality and meticulous technique produced iconic images like The Persistence of Memory.', 1904, 1989),
  ('a0000000-0000-0000-0000-000000000067', 'Andy Warhol', 'American artist and filmmaker who led the Pop Art movement, turning Campbell''s soup cans and Marilyn Monroe portraits into cultural landmarks.', 1928, 1987),
  ('a0000000-0000-0000-0000-000000000068', 'Michelangelo', 'Italian Renaissance sculptor and painter who created the Sistine Chapel ceiling and the statue of David, widely regarded as the greatest artist in Western history.', 1475, 1564),
  ('a0000000-0000-0000-0000-000000000069', 'Plato', 'Ancient Greek philosopher, student of Socrates, and teacher of Aristotle, whose dialogues on justice, beauty, and equality shaped Western philosophy and political thought.', -428, -348),
  ('a0000000-0000-0000-0000-00000000006a', 'Aristotle', 'Ancient Greek philosopher and polymath who tutored Alexander the Great and wrote foundational texts in logic, biology, ethics, and political science.', -384, -322),
  ('a0000000-0000-0000-0000-00000000006b', 'Immanuel Kant', 'German philosopher whose Critique of Pure Reason and categorical imperative transformed epistemology and ethics, making him one of the most influential thinkers of the modern era.', 1724, 1804),
  ('a0000000-0000-0000-0000-00000000006c', 'Friedrich Nietzsche', 'German philosopher famous for his concepts of the Übermensch and "God is dead," whose works profoundly influenced existentialism, postmodernism, and 20th-century thought.', 1844, 1900),
  ('a0000000-0000-0000-0000-00000000006d', 'Karl Marx', 'German philosopher and economist whose Communist Manifesto and Das Kapital provided the theoretical foundation for communist and socialist political movements worldwide.', 1818, 1883),
  ('a0000000-0000-0000-0000-00000000006e', 'René Descartes', 'French philosopher and mathematician who coined "I think, therefore I am," founded analytic geometry, and set the foundations of modern rationalist philosophy.', 1596, 1650),
  ('a0000000-0000-0000-0000-00000000006f', 'Sigmund Freud', 'Austrian neurologist who founded psychoanalysis, introducing concepts of the unconscious mind, repression, and the Oedipus complex that transformed psychology and culture.', 1856, 1939),
  ('a0000000-0000-0000-0000-000000000070', 'Carl Jung', 'Swiss psychiatrist who founded analytical psychology, introducing concepts of the collective unconscious, archetypes, and psychological types that influenced psychology and culture.', 1875, 1961),
  ('a0000000-0000-0000-0000-000000000071', 'Voltaire', 'French Enlightenment writer and philosopher who used satire to criticise religious intolerance and political tyranny; his novel Candide remains a masterpiece of satirical fiction.', 1694, 1778),
  ('a0000000-0000-0000-0000-000000000072', 'Jean-Jacques Rousseau', 'Swiss-French philosopher whose ideas on democracy, education, and the social contract profoundly influenced the French Revolution and modern political thought.', 1712, 1778),
  ('a0000000-0000-0000-0000-000000000073', 'Walt Whitman', 'American poet whose Leaves of Grass, including Song of Myself, celebrated democracy and the human body in free verse that transformed American poetry.', 1819, 1892),
  ('a0000000-0000-0000-0000-000000000074', 'Emily Dickinson', 'American poet who wrote nearly 1,800 poems in seclusion, most published posthumously; her compressed verse and unconventional punctuation made her one of America''s greatest poets.', 1830, 1886),
  ('a0000000-0000-0000-0000-000000000075', 'Martin Luther', 'German professor of theology whose 95 Theses challenging the Catholic Church sparked the Protestant Reformation and permanently split Western Christianity.', 1483, 1546),
  ('a0000000-0000-0000-0000-000000000076', 'Dante Alighieri', 'Italian poet who wrote the Divine Comedy, an epic journey through Hell, Purgatory, and Heaven, considered the supreme work of Italian literature.', 1265, 1321),
  ('a0000000-0000-0000-0000-000000000077', 'Homer', 'Ancient Greek poet traditionally credited with composing the Iliad and the Odyssey, the foundational texts of Western literature and a cornerstone of classical education.', -800, -701),
  ('a0000000-0000-0000-0000-000000000078', 'Confucius', 'Chinese philosopher and teacher whose emphasis on personal morality, family loyalty, and social harmony formed the basis of Confucianism, one of the most influential philosophies in East Asia.', -551, -479),
  ('a0000000-0000-0000-0000-000000000079', 'Ludwig van Beethoven', 'German composer who bridged the Classical and Romantic eras, composing nine symphonies including the Ninth after becoming completely deaf.', 1770, 1827),
  ('a0000000-0000-0000-0000-00000000007a', 'Wolfgang Amadeus Mozart', 'Austrian composer and prodigy who produced over 800 works including symphonies, operas, and concertos of sublime beauty before dying at 35.', 1756, 1791),
  ('a0000000-0000-0000-0000-00000000007b', 'Johann Sebastian Bach', 'German Baroque composer whose intricate counterpoint and harmonic innovation in works like the Brandenburg Concertos define the pinnacle of Baroque music.', 1685, 1750),
  ('a0000000-0000-0000-0000-00000000007c', 'Frédéric Chopin', 'Polish Romantic composer and virtuoso pianist who spent much of his career in Paris, composing nocturnes and polonaises that define the Romantic piano repertoire.', 1810, 1849),
  ('a0000000-0000-0000-0000-00000000007d', 'Richard Wagner', 'German opera composer who created the concept of the Gesamtkunstwerk with epic operas like the Ring Cycle that transformed 19th-century music.', 1813, 1883),
  ('a0000000-0000-0000-0000-00000000007e', 'Pyotr Tchaikovsky', 'Russian Romantic composer celebrated for his ballets Swan Lake, The Nutcracker, and Sleeping Beauty, and for his passionate, emotionally expressive symphonies.', 1840, 1893),
  ('a0000000-0000-0000-0000-00000000007f', 'Igor Stravinsky', 'Russian composer whose ballet The Rite of Spring caused a riot at its 1913 premiere and whose neoclassical works made him the most influential composer of the 20th century.', 1882, 1971),
  ('a0000000-0000-0000-0000-000000000080', 'Antonio Vivaldi', 'Italian Baroque composer and violinist whose The Four Seasons remains the most performed and recorded piece of Baroque music.', 1678, 1741),
  ('a0000000-0000-0000-0000-000000000081', 'Franz Schubert', 'Austrian composer who died at 31 yet produced over 600 lieder, nine symphonies, and chamber music of inexhaustible lyrical genius.', 1797, 1828),
  ('a0000000-0000-0000-0000-000000000082', 'Gustav Mahler', 'Austro-Bohemian conductor and composer whose massive symphonies bridge the Romantic and Modern eras, pushing orchestral music to its limits.', 1860, 1911),
  ('a0000000-0000-0000-0000-000000000083', 'Elvis Presley', 'American singer and actor who fused blues, gospel, and country into rock and roll, becoming the best-selling solo music artist of all time and transforming popular culture.', 1935, 1977),
  ('a0000000-0000-0000-0000-000000000084', 'John Lennon', 'English singer-songwriter and co-founder of The Beatles whose post-Beatles work including Imagine made him one of the most influential artists of the 20th century.', 1940, 1980),
  ('a0000000-0000-0000-0000-000000000085', 'Bob Dylan', 'American singer-songwriter who defined the folk and protest music of the 1960s and was awarded the Nobel Prize in Literature in 2016.', 1941, NULL),
  ('a0000000-0000-0000-0000-000000000086', 'Michael Jackson', 'American singer, songwriter, and dancer known as the King of Pop whose Thriller remains the best-selling album of all time.', 1958, 2009),
  ('a0000000-0000-0000-0000-000000000087', 'David Bowie', 'English singer-songwriter and actor who reinvented himself through personas like Ziggy Stardust, influencing fashion, gender expression, and every genre of popular music.', 1947, 2016),
  ('a0000000-0000-0000-0000-000000000088', 'Freddie Mercury', 'British singer and showman who fronted Queen and wrote Bohemian Rhapsody; his Live Aid performance in 1985 is considered the greatest concert moment in history.', 1946, 1991),
  ('a0000000-0000-0000-0000-000000000089', 'Jimi Hendrix', 'American guitarist and singer who revolutionised electric guitar playing with his psychedelic blues-rock style and is widely considered the greatest guitarist in history.', 1942, 1970),
  ('a0000000-0000-0000-0000-00000000008a', 'Bob Marley', 'Jamaican singer-songwriter who spread reggae and Rastafarianism worldwide; his posthumous compilation Legend is the best-selling reggae album of all time.', 1945, 1981),
  ('a0000000-0000-0000-0000-00000000008b', 'Frank Sinatra', 'American singer and actor known as "Ol'' Blue Eyes" whose vocal phrasing and stage presence defined the American popular song for four decades.', 1915, 1998),
  ('a0000000-0000-0000-0000-00000000008c', 'Billie Holiday', 'American jazz singer whose deeply personal vocal style and songs like Strange Fruit made her one of the most influential jazz vocalists and an enduring symbol of racial injustice.', 1915, 1959),
  ('a0000000-0000-0000-0000-00000000008d', 'Louis Armstrong', 'American jazz trumpeter and vocalist who was the most dominant and influential figure in jazz history, transforming the music from ensemble to solo art form.', 1901, 1971),
  ('a0000000-0000-0000-0000-00000000008e', 'Miles Davis', 'American jazz trumpeter who reinvented jazz multiple times, pioneering bebop, cool jazz, modal jazz, and jazz fusion with landmark albums like Kind of Blue.', 1926, 1991),
  ('a0000000-0000-0000-0000-00000000008f', 'Kurt Cobain', 'American singer-songwriter and guitarist who founded Nirvana and defined the grunge movement with Nevermind, bringing alternative rock to mainstream audiences.', 1967, 1994),
  ('a0000000-0000-0000-0000-000000000090', 'Prince', 'American musician and multi-instrumentalist who blended funk, pop, rock, and R&B across 39 studio albums, playing almost every instrument on his recordings.', 1958, 2016),
  ('a0000000-0000-0000-0000-000000000091', 'Amy Winehouse', 'British singer-songwriter whose soulful voice and deeply personal album Back to Black won five Grammy Awards and made her one of the best-selling artists of the 2000s.', 1983, 2011),
  ('a0000000-0000-0000-0000-000000000092', 'Leonard Cohen', 'Canadian singer-songwriter and poet whose literary lyrics on love, religion, and despair in songs like Hallelujah established him as one of the most revered musicians of the 20th century.', 1934, 2016),
  ('a0000000-0000-0000-0000-000000000093', 'Johnny Cash', 'American country singer known as "the Man in Black" whose late-career American Recordings series is widely considered among the greatest albums ever made.', 1932, 2003),
  ('a0000000-0000-0000-0000-000000000094', 'Aretha Franklin', 'American singer known as the "Queen of Soul" whose powerful voice and recordings including Respect made her one of the most influential musicians of the 20th century.', 1942, 2018),
  ('a0000000-0000-0000-0000-000000000095', 'Bruce Springsteen', 'American singer-songwriter known as "the Boss" whose epic live performances and blue-collar anthems like Born to Run define the rock and roll tradition.', 1949, NULL),
  ('a0000000-0000-0000-0000-000000000096', 'Madonna', 'American singer and actress known as the "Queen of Pop" who became one of the best-selling music artists of all time through constant reinvention and groundbreaking music videos.', 1958, NULL),
  ('a0000000-0000-0000-0000-000000000097', 'Bill Gates', 'American business magnate who co-founded Microsoft and made it the dominant personal computer software company; now a leading global philanthropist through the Bill & Melinda Gates Foundation.', 1955, NULL),
  ('a0000000-0000-0000-0000-000000000098', 'Jeff Bezos', 'American entrepreneur who founded Amazon in 1994 as an online bookstore and expanded it into the world''s largest e-commerce and cloud computing company.', 1964, NULL),
  ('a0000000-0000-0000-0000-000000000099', 'Mark Zuckerberg', 'American technology entrepreneur who co-founded Facebook at Harvard in 2004 and built it into a global social media empire encompassing Facebook, Instagram, and WhatsApp.', 1984, NULL),
  ('a0000000-0000-0000-0000-00000000009a', 'Warren Buffett', 'American investor and philanthropist known as the "Oracle of Omaha" who built Berkshire Hathaway into one of the world''s most valuable companies through patient value investing.', 1930, NULL),
  ('a0000000-0000-0000-0000-00000000009b', 'John D. Rockefeller', 'American oil magnate who founded Standard Oil and became the world''s first billionaire; his philanthropy established the University of Chicago and Rockefeller University.', 1839, 1937),
  ('a0000000-0000-0000-0000-00000000009c', 'Andrew Carnegie', 'Scottish-American industrialist who built Carnegie Steel into the dominant US steel company and then gave away 90% of his fortune to libraries and education.', 1835, 1919),
  ('a0000000-0000-0000-0000-00000000009d', 'Henry Ford', 'American industrialist who developed the moving assembly line, making the Model T the first affordable automobile for ordinary Americans and transforming manufacturing worldwide.', 1863, 1947),
  ('a0000000-0000-0000-0000-00000000009e', 'Walt Disney', 'American entrepreneur and animator who founded The Walt Disney Company, created Mickey Mouse, produced the first animated feature film Snow White, and built Disneyland.', 1901, 1966),
  ('a0000000-0000-0000-0000-00000000009f', 'Howard Hughes', 'American business magnate, film director, and aviator who set airspeed records and became one of the wealthiest people in the world before retreating into severe OCD-driven reclusion.', 1905, 1976),
  ('a0000000-0000-0000-0000-0000000000a0', 'Sam Walton', 'American businessman who founded Walmart in 1962, pioneering discount retail and supply chain management to build the world''s largest retailer.', 1918, 1992),
  ('a0000000-0000-0000-0000-0000000000a1', 'Larry Page', 'American computer scientist who co-founded Google with Sergey Brin, inventing the PageRank algorithm that made Google the world''s dominant search engine.', 1973, NULL),
  ('a0000000-0000-0000-0000-0000000000a2', 'Sergey Brin', 'American computer scientist who co-founded Google and served as its president, pioneering the search technology that underpins modern information access.', 1973, NULL),
  ('a0000000-0000-0000-0000-0000000000a3', 'Jack Ma', 'Chinese entrepreneur who founded Alibaba, transforming e-commerce in China and building one of the world''s most valuable technology companies from nothing.', 1964, NULL),
  ('a0000000-0000-0000-0000-0000000000a4', 'Larry Ellison', 'American entrepreneur who co-founded Oracle Corporation and turned it into the world''s largest enterprise software company, accumulating one of the world''s largest personal fortunes.', 1944, NULL),
  ('a0000000-0000-0000-0000-0000000000a5', 'Richard Branson', 'British entrepreneur who founded the Virgin Group comprising over 400 companies, from music to airlines to space tourism, becoming synonymous with entrepreneurial risk-taking.', 1950, NULL),
  ('a0000000-0000-0000-0000-0000000000a6', 'Ray Kroc', 'American businessman who transformed McDonald''s from a small California burger stand into the world''s largest fast food chain, franchising it across the globe.', 1902, 1984),
  ('a0000000-0000-0000-0000-0000000000a7', 'Coco Chanel', 'French fashion designer who liberated women''s fashion from corsets and created the little black dress, Chanel No. 5, and the Chanel suit, defining modern elegance.', 1883, 1971),
  ('a0000000-0000-0000-0000-0000000000a8', 'Oprah Winfrey', 'American media executive and talk show host whose syndicated show ran for 25 years; the first African-American female billionaire and one of the most influential public figures in history.', 1954, NULL),
  ('a0000000-0000-0000-0000-0000000000a9', 'Steve Wozniak', 'American electronics engineer who co-founded Apple with Steve Jobs, designing the Apple I and Apple II computers that launched the personal computer revolution.', 1950, NULL),
  ('a0000000-0000-0000-0000-0000000000aa', 'Thomas Edison', 'American inventor and businessman who developed the phonograph, the motion picture camera, and a practical incandescent light bulb, holding a record 1,093 patents.', 1847, 1931),
  ('a0000000-0000-0000-0000-0000000000ab', 'Muhammad Ali', 'American professional boxer and activist who won the heavyweight championship three times and was known for his speed, footwork, and outspoken advocacy for civil rights.', 1942, 2016),
  ('a0000000-0000-0000-0000-0000000000ac', 'Pelé', 'Brazilian football legend who won three FIFA World Cups, scored over 1,000 goals in his career, and is widely regarded as the greatest footballer of all time.', 1940, 2022),
  ('a0000000-0000-0000-0000-0000000000ad', 'Diego Maradona', 'Argentine football genius whose Hand of God goal and Goal of the Century in the 1986 World Cup quarter-final encapsulate both the controversy and brilliance of his career.', 1960, 2020),
  ('a0000000-0000-0000-0000-0000000000ae', 'Michael Jordan', 'American basketball player who won six NBA championships with the Chicago Bulls and is widely regarded as the greatest basketball player of all time.', 1963, NULL),
  ('a0000000-0000-0000-0000-0000000000af', 'Tiger Woods', 'American golfer who won 15 major championships and dominated golf for over a decade, becoming one of the highest-paid athletes in history.', 1975, NULL),
  ('a0000000-0000-0000-0000-0000000000b0', 'Serena Williams', 'American tennis player who won 23 Grand Slam singles titles, the most by any player in the Open Era, and is widely regarded as the greatest tennis player of all time.', 1981, NULL),
  ('a0000000-0000-0000-0000-0000000000b1', 'Roger Federer', 'Swiss tennis player who won 20 Grand Slam singles titles and is celebrated as one of the most elegant and complete players the sport has ever seen.', 1981, NULL),
  ('a0000000-0000-0000-0000-0000000000b2', 'Usain Bolt', 'Jamaican sprinter who holds the world records in the 100m and 200m and won eight Olympic gold medals, becoming the fastest human ever timed.', 1986, NULL),
  ('a0000000-0000-0000-0000-0000000000b3', 'Michael Phelps', 'American swimmer who won 23 Olympic gold medals — the most by any Olympian in history — across four consecutive Olympic Games.', 1985, NULL),
  ('a0000000-0000-0000-0000-0000000000b4', 'Jesse Owens', 'American track and field athlete who won four gold medals at the 1936 Berlin Olympics, embarrassing Hitler''s claims of Aryan racial superiority on the world stage.', 1913, 1980),
  ('a0000000-0000-0000-0000-0000000000b5', 'Babe Ruth', 'American baseball player known as "the Sultan of Swat" whose 714 home runs and larger-than-life personality made him the greatest player of his era.', 1895, 1948),
  ('a0000000-0000-0000-0000-0000000000b6', 'Ayrton Senna', 'Brazilian Formula One driver who won three World Championships and is widely regarded as the greatest racing driver in history; his death at Imola in 1994 shocked the world.', 1960, 1994),
  ('a0000000-0000-0000-0000-0000000000b7', 'LeBron James', 'American basketball player who won four NBA championships with three different teams and surpassed Kareem Abdul-Jabbar''s all-time NBA scoring record in 2023.', 1984, NULL),
  ('a0000000-0000-0000-0000-0000000000b8', 'Lionel Messi', 'Argentine footballer who won eight Ballon d''Or awards and led Argentina to the 2022 FIFA World Cup, cementing his place as the greatest player of his generation.', 1987, NULL),
  ('a0000000-0000-0000-0000-0000000000b9', 'Roger Bannister', 'British middle-distance runner who on 6 May 1954 became the first person to run a mile in under four minutes, a barrier widely believed to be physiologically impossible.', 1929, 2018),
  ('a0000000-0000-0000-0000-0000000000ba', 'Jack Nicklaus', 'American golfer known as "the Golden Bear" who won 18 major championships — the most in history — and is considered the greatest golfer of all time by many experts.', 1940, NULL),
  ('a0000000-0000-0000-0000-0000000000bb', 'Wayne Gretzky', 'Canadian ice hockey player known as "the Great One" who scored more goals than any other player and whose total points tally exceeds the second-place scorer by over 1,000.', 1961, NULL),
  ('a0000000-0000-0000-0000-0000000000bc', 'Nadia Comaneci', 'Romanian gymnast who at the 1976 Montreal Olympics became the first gymnast to be awarded a perfect score of 10, winning three gold medals at age 14.', 1961, NULL),
  ('a0000000-0000-0000-0000-0000000000bd', 'Lewis Hamilton', 'British Formula One driver who won a record-equalling seven World Championships and holds records for most wins, poles, and podiums in F1 history.', 1985, NULL),
  ('a0000000-0000-0000-0000-0000000000be', 'Simone Biles', 'American gymnast who won seven Olympic gold medals and 23 World Championship gold medals, widely regarded as the greatest gymnast of all time.', 1997, NULL),
  ('a0000000-0000-0000-0000-0000000000bf', 'Christopher Columbus', 'Italian explorer who completed four voyages to the Americas under Spanish patronage beginning in 1492, opening sustained contact between Europe and the Americas.', 1451, 1506),
  ('a0000000-0000-0000-0000-0000000000c0', 'Ferdinand Magellan', 'Portuguese explorer who led the first expedition to circumnavigate the Earth, though he was killed in the Philippines before completing the voyage.', 1480, 1521),
  ('a0000000-0000-0000-0000-0000000000c1', 'Marco Polo', 'Venetian merchant and explorer whose 24-year journey to China and service in the court of Kublai Khan produced one of the most influential travel accounts in history.', 1254, 1324),
  ('a0000000-0000-0000-0000-0000000000c2', 'James Cook', 'British explorer and cartographer who made three voyages of discovery, mapping New Zealand, Australia, and Hawaii and charting the Pacific Ocean with unprecedented accuracy.', 1728, 1779),
  ('a0000000-0000-0000-0000-0000000000c3', 'Amelia Earhart', 'American aviation pioneer who became the first woman to fly solo across the Atlantic Ocean in 1932 and disappeared over the Pacific during an attempted round-the-world flight.', 1897, 1937),
  ('a0000000-0000-0000-0000-0000000000c4', 'Edmund Hillary', 'New Zealand mountaineer who along with Tenzing Norgay became the first confirmed person to summit Mount Everest on 29 May 1953.', 1919, 2008),
  ('a0000000-0000-0000-0000-0000000000c5', 'Yuri Gagarin', 'Soviet cosmonaut who on 12 April 1961 became the first human to travel into outer space and orbit the Earth, a milestone for all humanity.', 1934, 1968),
  ('a0000000-0000-0000-0000-0000000000c6', 'Neil Armstrong', 'American astronaut who on 20 July 1969 became the first human to walk on the Moon during the Apollo 11 mission, declaring it "one small step for man."', 1930, 2012),
  ('a0000000-0000-0000-0000-0000000000c7', 'Charles Lindbergh', 'American aviator who in 1927 completed the first solo non-stop transatlantic flight from New York to Paris in 33.5 hours in his plane, the Spirit of St. Louis.', 1902, 1974),
  ('a0000000-0000-0000-0000-0000000000c8', 'Ernest Shackleton', 'Anglo-Irish Antarctic explorer who led the legendary Endurance expedition of 1914–1916, keeping all 28 crew members alive after their ship was crushed by pack ice.', 1874, 1922),
  ('a0000000-0000-0000-0000-0000000000c9', 'Roald Amundsen', 'Norwegian explorer who led the first expedition to reach the South Pole on 14 December 1911 and was the first to complete the Northwest Passage by sea.', 1872, 1928),
  ('a0000000-0000-0000-0000-0000000000ca', 'Ibn Battuta', 'Moroccan explorer who over 29 years travelled approximately 75,000 miles through Africa, the Middle East, South Asia, and China — the most extensive medieval journey ever recorded.', 1304, 1368),
  ('a0000000-0000-0000-0000-0000000000cb', 'Vasco da Gama', 'Portuguese explorer who was the first to sail directly from Europe to India around the Cape of Good Hope in 1498, opening the sea route that transformed global trade.', 1460, 1524),
  ('a0000000-0000-0000-0000-0000000000cc', 'Charles de Gaulle', 'French general and statesman who led Free France during WWII, founded the Fifth Republic, and served as France''s first president, shaping French foreign and domestic policy for decades.', 1890, 1970),
  ('a0000000-0000-0000-0000-0000000000cd', 'Archimedes', 'Ancient Greek mathematician and inventor of Syracuse who discovered the principles of the lever and buoyancy, and devised war machines that delayed Rome''s conquest of Syracuse.', -287, -212),
  ('a0000000-0000-0000-0000-0000000000ce', 'Socrates', 'Ancient Athenian philosopher who developed the Socratic method of inquiry, was a foundational figure in Western philosophy, and was sentenced to death for impiety and corrupting the youth.', -470, -399),
  ('a0000000-0000-0000-0000-0000000000cf', 'Johannes Gutenberg', 'German goldsmith and inventor who introduced movable type printing to Europe around 1440, launching the Printing Revolution that democratised knowledge and transformed civilisation.', 1400, 1468),
  ('a0000000-0000-0000-0000-0000000000d0', 'Florence Nightingale', 'British social reformer and founder of modern nursing who transformed hospital sanitation during the Crimean War, reducing death rates dramatically through statistical analysis and hygiene reforms.', 1820, 1910);
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000009', 'Place & Travel', 'Woolsthorpe, Lincolnshire', 'Born prematurely in a farmhouse; father died before his birth; raised by grandmother after mother remarried.', 'range', 1643, 1661, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000009', 'Place & Travel', 'Cambridge', 'Studied and later worked at Trinity College Cambridge for most of his adult life, interrupted only by plague years.', 'range', 1661, 1696, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000009', 'Place & Travel', 'London — Royal Mint', 'Moved to London to serve as Warden then Master of the Royal Mint, prosecuting counterfeiters with unusual zeal.', 'range', 1696, 1727, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000009', 'Work & Education', 'King''s School Grantham', 'Attended boarding school where he showed early mechanical aptitude, building model windmills and sundials.', 'range', 1655, 1661, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000009', 'Work & Education', 'Trinity College Cambridge', 'Enrolled as a subsizar (working student); studied Descartes and Galileo; graduated BA 1665.', 'range', 1661, 1665, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000009', 'Work & Education', 'Annus Mirabilis — plague years', 'Retreated to Woolsthorpe during plague 1665–67; developed calculus, optics, and law of gravitation in 18 months.', 'range', 1665, 1667, '#10b981'),
  ('a0000000-0000-0000-0000-000000000009', 'Work & Education', 'Lucasian Professor of Mathematics', 'Appointed Lucasian Professor at Cambridge aged 26, the same chair later held by Stephen Hawking.', 'range', 1669, 1702, '#059669'),
  ('a0000000-0000-0000-0000-000000000009', 'Work & Education', 'Principia Mathematica published', 'Published in 1687 at Halley''s urging and expense; laid out laws of motion and universal gravitation; transformed science forever.', 'point', 1687, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000009', 'Work & Education', 'Opticks published', 'Published in 1704; described light and colour experiments with prisms; written in English rather than Latin for wider readership.', 'point', 1704, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000009', 'Work & Education', 'Master of the Royal Mint', 'Oversaw the great recoinage of 1696–1699, replacing clipped and debased coins; vigorously prosecuted forger William Chaloner.', 'range', 1699, 1727, '#047857'),
  ('a0000000-0000-0000-0000-000000000009', 'Health', 'Nervous breakdown', 'Suffered a serious mental breakdown in 1693 possibly due to mercury poisoning from alchemical experiments; wrote incoherent letters to friends.', 'point', 1693, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000009', 'Relations & Family', 'Catherine Barton (niece)', 'His niece Catherine Barton lived with him in London and served as his housekeeper; she later married John Conduitt.', 'range', 1696, 1727, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000009', 'Relations & Family', 'Rivalry with Leibniz', 'Bitter priority dispute over who invented calculus; orchestrated Royal Society inquiry that found in his favour but damaged both reputations.', 'range', 1699, 1716, '#db2777'),
  ('a0000000-0000-0000-0000-000000000009', 'Activities', 'Alchemy experiments', 'Wrote over a million words on alchemy, searching for the philosopher''s stone; kept this work largely secret during his lifetime.', 'range', 1669, 1693, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000009', 'Activities', 'President of the Royal Society', 'Served as president from 1703 until his death, dominating British science and using the position to crush rivals like Flamsteed.', 'range', 1703, 1727, '#d97706'),
  ('a0000000-0000-0000-0000-000000000009', 'Activities', 'Theological writings', 'Wrote extensively on biblical prophecy and Arianism, rejecting the Trinity; these heretical views were kept secret until after his death.', 'range', 1670, 1720, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000009', 'Assets', 'Knighted by Queen Anne', 'Knighted in 1705 — the first scientist to receive a knighthood, primarily for his political service rather than scientific achievement.', 'point', 1705, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000009', 'Assets', 'Profitable Mint salary', 'Earned a very generous salary as Master of the Mint plus profits; died a wealthy man worth approximately £30,000.', 'range', 1699, 1727, '#0d9488'),
  ('a0000000-0000-0000-0000-000000000009', 'Items', 'Prism experiments', 'Used glass prisms to split white light into a spectrum; described in Opticks; the original prisms were carefully preserved.', 'range', 1665, 1704, '#64748b'),
  ('a0000000-0000-0000-0000-000000000009', 'Items', 'Newton''s reflecting telescope', 'Built the first practical reflecting telescope in 1668 to avoid chromatic aberration; presented to the Royal Society in 1671.', 'point', 1668, NULL, '#475569');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000000a', 'Place & Travel', 'Pisa, Italy', 'Born and raised in Pisa; attended the University of Pisa where he reportedly dropped objects from the Leaning Tower.', 'range', 1564, 1592, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000a', 'Place & Travel', 'Padua, Republic of Venice', 'Spent 18 years at the University of Padua — the happiest and most productive period of his life, protected by Venetian freedom.', 'range', 1592, 1610, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000a', 'Place & Travel', 'Florence — Medici court', 'Moved to Florence as court philosopher to Cosimo II de'' Medici; proximity to Rome ultimately led to his trial.', 'range', 1610, 1642, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000000a', 'Work & Education', 'University of Pisa — professor', 'Appointed professor of mathematics aged 25; began experiments on motion and falling bodies that challenged Aristotle.', 'range', 1589, 1592, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000000a', 'Work & Education', 'University of Padua — professor', 'Taught mathematics, mechanics, and astronomy; had over 80 students; invented a military compass and improved the thermometer.', 'range', 1592, 1610, '#10b981'),
  ('a0000000-0000-0000-0000-00000000000a', 'Work & Education', 'Telescopic observations', 'Built improved telescope in 1609 and discovered Jupiter''s moons, lunar craters, and phases of Venus; published in Sidereus Nuncius 1610.', 'range', 1609, 1613, '#059669'),
  ('a0000000-0000-0000-0000-00000000000a', 'Work & Education', 'Dialogue Concerning the Two Chief World Systems', 'Published in 1632; argued for Copernican heliocentrism through dialogue; led directly to his Inquisition trial.', 'point', 1632, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000000a', 'Work & Education', 'Two New Sciences', 'Final masterwork published in 1638 while under house arrest; laid foundations of modern physics and kinematics.', 'point', 1638, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000000a', 'Health', 'House arrest and blindness', 'Placed under house arrest by Inquisition in 1633; went totally blind by 1638 but continued dictating scientific work until death.', 'range', 1633, 1642, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000000a', 'Relations & Family', 'Marina Gamba', 'Long-term companion who bore him three illegitimate children; Galileo never married her but ensured their children were cared for.', 'range', 1599, 1610, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000000a', 'Relations & Family', 'Virginia (Sister Maria Celeste)', 'His eldest daughter entered a convent aged 13 and became a devoted correspondent; her letters to him were among his most treasured possessions.', 'range', 1613, 1634, '#db2777'),
  ('a0000000-0000-0000-0000-00000000000a', 'Relations & Family', 'Inquisition trial', 'Tried by the Roman Inquisition in 1633 for heresy; forced to recant heliocentrism; legend holds he muttered "and yet it moves."', 'point', 1633, NULL, '#f97316'),
  ('a0000000-0000-0000-0000-00000000000a', 'Activities', 'Patronage of Medici', 'Cultivated Medici patronage assiduously; named Jupiter''s moons after the Medici family to secure his court position.', 'range', 1610, 1642, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000000a', 'Activities', 'Pendulum clock concept', 'Conceived the pendulum clock mechanism in 1637 while observing a swinging lamp; his son Vincenzo began building it but neither completed it.', 'point', 1637, NULL, '#d97706'),
  ('a0000000-0000-0000-0000-00000000000a', 'Assets', 'Improved telescope business', 'Manufactured and sold improved telescopes at Padua, earning substantial income from merchants and military customers.', 'range', 1609, 1613, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000000a', 'Items', 'Galileo''s telescopes', 'Constructed telescopes achieving 20× magnification; two surviving examples are preserved in the Museo Galileo in Florence.', 'range', 1609, 1642, '#64748b'),
  ('a0000000-0000-0000-0000-00000000000a', 'Items', 'Sector (military compass)', 'Invented a proportional compass or sector used for military and engineering calculations; sold copies and gave lessons on its use.', 'range', 1597, 1610, '#475569');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000000b', 'Place & Travel', 'Shrewsbury, England', 'Born into a wealthy family; father was a doctor; grew up collecting beetles and developing a passion for natural history.', 'range', 1809, 1825, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000b', 'Place & Travel', 'Edinburgh & Cambridge', 'Studied medicine briefly at Edinburgh then moved to Cambridge intending to become a clergyman; graduated 1831.', 'range', 1825, 1831, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000b', 'Place & Travel', 'Voyage of the Beagle', 'Five-year circumnavigation (1831–1836) visiting the Galapagos Islands; observations directly inspired the theory of natural selection.', 'range', 1831, 1836, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000000b', 'Place & Travel', 'Down House, Kent', 'Retreated to Down House in 1842 where he lived and worked for the rest of his life, rarely leaving due to chronic illness.', 'range', 1842, 1882, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000b', 'Work & Education', 'Edinburgh medical studies', 'Enrolled at Edinburgh medical school aged 16; found surgery without anaesthesia too distressing; turned to natural history instead.', 'range', 1825, 1827, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000000b', 'Work & Education', 'Christ''s College Cambridge', 'Read theology but spent more time beetle-collecting; met botanist John Stevens Henslow who recommended him for the Beagle voyage.', 'range', 1828, 1831, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000000b', 'Work & Education', 'On the Origin of Species', 'Published 1859 after 20 years of careful preparation; sold out on first day; immediately transformed biology and provoked fierce debate.', 'point', 1859, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000000b', 'Work & Education', 'The Descent of Man', 'Published 1871; explicitly applied evolution to humans; argued humans and apes share common ancestry, scandalising Victorian society.', 'point', 1871, NULL, '#059669'),
  ('a0000000-0000-0000-0000-00000000000b', 'Work & Education', 'Research at Down House', 'Conducted meticulous experiments on barnacles, earthworms, orchids, and carnivorous plants; published 19 books in total.', 'range', 1842, 1882, '#047857'),
  ('a0000000-0000-0000-0000-00000000000b', 'Health', 'Chronic illness', 'Suffered for 40 years from unexplained illness — possibly Chagas disease contracted in South America — including severe vomiting and heart palpitations.', 'range', 1837, 1882, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000000b', 'Relations & Family', 'Emma Wedgwood (wife)', 'Married his first cousin Emma in 1839; she was deeply religious and they had a tender marriage despite disagreeing about religion.', 'range', 1839, 1882, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000000b', 'Relations & Family', 'Ten children', 'Had ten children with Emma; three died in infancy; he feared his own ill health was inherited by his children, fuelling his work.', 'range', 1839, 1858, '#db2777'),
  ('a0000000-0000-0000-0000-00000000000b', 'Relations & Family', 'Death of Anne Darwin', 'His beloved daughter Anne died aged 10 in 1851; the tragedy destroyed any remaining religious faith and deepened his agnosticism.', 'point', 1851, NULL, '#f97316'),
  ('a0000000-0000-0000-0000-00000000000b', 'Activities', 'Beetle collecting obsession', 'Passionate beetle collector from youth; once put a live beetle in his mouth to free his hands; made important entomological discoveries.', 'range', 1820, 1836, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000000b', 'Activities', 'Correspondence network', 'Maintained thousands of letters with scientists worldwide; used global network of correspondents to gather evidence for his theory.', 'range', 1836, 1882, '#d97706'),
  ('a0000000-0000-0000-0000-00000000000b', 'Assets', 'Inherited wealth', 'Benefited from substantial Wedgwood and Darwin family fortunes; never needed paid employment; his wealth freed him for research.', 'range', 1836, 1882, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000000b', 'Assets', 'Book royalties', 'Origin of Species went through six editions; earned significant royalties that supplemented his investment income.', 'range', 1859, 1882, '#0d9488'),
  ('a0000000-0000-0000-0000-00000000000b', 'Items', 'HMS Beagle specimen collections', 'Collected thousands of geological and biological specimens on the Beagle voyage; fossils of giant sloths and armadillos proved crucial.', 'range', 1831, 1836, '#64748b'),
  ('a0000000-0000-0000-0000-00000000000b', 'Items', 'Galapagos finch specimens', 'Collected finches from different Galapagos islands; differences in beak shape became the iconic illustration of natural selection.', 'range', 1835, 1836, '#475569');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000000c', 'Place & Travel', 'Smiljan, Serbia (now Croatia)', 'Born in a Serbian village; father was an Orthodox priest; showed extraordinary memory and ability to perform calculus mentally as a child.', 'range', 1856, 1875, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000c', 'Place & Travel', 'Graz & Prague', 'Studied engineering at Graz Polytechnic; developed concept of rotating magnetic field; moved to Prague briefly before Budapest.', 'range', 1875, 1882, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000c', 'Place & Travel', 'New York City', 'Arrived in 1884 with four cents in his pocket; worked briefly for Edison before their famous falling-out over AC versus DC.', 'range', 1884, 1943, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000000c', 'Work & Education', 'Edison Machine Works', 'Worked for Thomas Edison in NYC 1884–85; reportedly promised $50,000 to redesign Edison''s DC motors; Edison refused to pay, triggering his departure.', 'range', 1884, 1885, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000000c', 'Work & Education', 'AC induction motor & Tesla coil', 'Patented AC induction motor in 1888; sold patents to Westinghouse for $60,000 plus royalties; invented the Tesla coil in 1891.', 'range', 1887, 1895, '#10b981'),
  ('a0000000-0000-0000-0000-00000000000c', 'Work & Education', 'Niagara Falls power plant', 'Westinghouse AC system chosen over Edison''s DC to power the 1893 World''s Fair and then Niagara Falls; vindicated AC in the "War of Currents."', 'range', 1893, 1896, '#059669'),
  ('a0000000-0000-0000-0000-00000000000c', 'Work & Education', 'Wardenclyffe Tower project', 'Built the Wardenclyffe Tower on Long Island 1901–1906 to transmit wireless energy globally; JP Morgan withdrew funding and the project failed.', 'range', 1901, 1906, '#047857'),
  ('a0000000-0000-0000-0000-00000000000c', 'Work & Education', 'Radio and remote control patents', 'Demonstrated remote-controlled boat in 1898; his 1897 radio patents were ultimately recognised as predating Marconi''s by the US Supreme Court in 1943.', 'range', 1897, 1900, '#10b981'),
  ('a0000000-0000-0000-0000-00000000000c', 'Health', 'OCD and phobias', 'Suffered from severe OCD, was obsessed with the number 3, and had extreme phobias including a terror of round objects and women''s earrings.', 'range', 1880, 1943, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000000c', 'Health', 'Destitution in old age', 'Spent his final years in poverty at the Hotel New Yorker, feeding pigeons in Bryant Park; his extraordinary mind deteriorated in isolation.', 'range', 1920, 1943, '#dc2626'),
  ('a0000000-0000-0000-0000-00000000000c', 'Relations & Family', 'Rivalry with Edison', 'The War of Currents pitted Tesla''s AC against Edison''s DC; Edison used electrocution of animals to discredit AC in a vicious public campaign.', 'range', 1887, 1893, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000000c', 'Relations & Family', 'Friendship with Mark Twain', 'Close friends with Mark Twain; Tesla photographed Twain in his lab in 1894 in one of the first photographs taken by phosphorescent light.', 'range', 1894, 1910, '#db2777'),
  ('a0000000-0000-0000-0000-00000000000c', 'Activities', 'Pigeon care', 'Cared deeply for pigeons throughout his life; became obsessed with a particular white pigeon he described as "the one great love of my life."', 'range', 1900, 1943, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000000c', 'Activities', 'Public demonstrations', 'Gave spectacular public lectures passing 250,000-volt currents through his body; made Tesla coil discharges a public spectacle.', 'range', 1891, 1898, '#d97706'),
  ('a0000000-0000-0000-0000-00000000000c', 'Assets', 'Westinghouse AC patents deal', 'Sold AC motor patents to Westinghouse for $60,000 plus $2.50 per horsepower royalty; later tore up the royalty agreement to save Westinghouse.', 'point', 1888, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000000c', 'Assets', 'Financial ruin', 'Lost all financial backing after Wardenclyffe failure; spent later life in debt; J.P. Morgan and other financiers refused further investment.', 'range', 1906, 1943, '#0d9488'),
  ('a0000000-0000-0000-0000-00000000000c', 'Items', 'Tesla coil', 'Invented the resonant transformer circuit (Tesla coil) in 1891; used to produce high-voltage, high-frequency alternating current electricity.', 'point', 1891, NULL, '#64748b'),
  ('a0000000-0000-0000-0000-00000000000c', 'Items', 'Wardenclyffe Tower', 'Massive 57-metre tower built at Shoreham, Long Island; intended for global wireless power transmission; demolished in 1917 for scrap metal.', 'range', 1901, 1917, '#475569');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000000d', 'Place & Travel', 'Oxford, England', 'Born in Oxford during WWII; parents had moved from London to escape the Blitz; grew up in St Albans, Hertfordshire.', 'range', 1942, 1959, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000d', 'Place & Travel', 'Oxford & Cambridge', 'Read physics at Oxford then moved to Cambridge for doctoral research in cosmology under Dennis Sciama.', 'range', 1959, 1965, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000d', 'Place & Travel', 'Cambridge (career-long)', 'Spent almost his entire career at Cambridge; Lucasian Professor from 1979 to 2009; became the city''s most famous resident.', 'range', 1965, 2018, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000000d', 'Work & Education', 'Oxford University', 'Read natural sciences, specialising in physics; described himself as doing little work but still graduating with first-class honours.', 'range', 1959, 1962, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000000d', 'Work & Education', 'PhD Cambridge — cosmology', 'Doctoral thesis on singularities in the expanding universe; completed despite advancing ALS; examined by Dennis Sciama and Roger Penrose.', 'range', 1962, 1966, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000000d', 'Work & Education', 'Hawking radiation theory', 'Proposed in 1974 that black holes emit radiation due to quantum effects near the event horizon — his most celebrated theoretical contribution.', 'point', 1974, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000000d', 'Work & Education', 'Lucasian Professor', 'Held the Lucasian Chair of Mathematics at Cambridge 1979–2009, the same professorship once held by Isaac Newton.', 'range', 1979, 2009, '#059669'),
  ('a0000000-0000-0000-0000-00000000000d', 'Work & Education', 'A Brief History of Time', 'Published 1988; sold over 10 million copies worldwide; spent 237 weeks on the Sunday Times bestseller list; made cosmology accessible.', 'point', 1988, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000000d', 'Health', 'ALS diagnosis', 'Diagnosed with motor neurone disease aged 21; given two years to live; defied prognosis and lived 55 more years.', 'point', 1963, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000000d', 'Health', 'Loss of speech — voice synthesiser', 'Lost his speech after a tracheotomy in 1985; used a custom speech synthesiser with an American accent that became his recognisable voice.', 'range', 1985, 2018, '#dc2626'),
  ('a0000000-0000-0000-0000-00000000000d', 'Relations & Family', 'Jane Wilde (first wife)', 'Married physics student Jane Wilde in 1965; she provided emotional support through his illness; they divorced in 1995 after 30 years.', 'range', 1965, 1995, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000000d', 'Relations & Family', 'Elaine Mason (second wife)', 'Married his nurse Elaine Mason in 1995; controversial and stormy marriage; divorced in 2006.', 'range', 1995, 2006, '#db2777'),
  ('a0000000-0000-0000-0000-00000000000d', 'Relations & Family', 'Three children', 'Had three children with Jane: Robert, Lucy, and Timothy; Lucy later co-wrote children''s books with her father.', 'range', 1967, 1979, '#f97316'),
  ('a0000000-0000-0000-0000-00000000000d', 'Activities', 'Zero-gravity flight', 'In 2007 experienced weightlessness aboard a modified Boeing 727; declared it "space, here I come" despite being wheelchair-bound.', 'point', 2007, NULL, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000000d', 'Activities', 'Media appearances and advocacy', 'Appeared on Star Trek, The Simpsons, and Big Bang Theory; advocated strongly for disability rights and scientific education.', 'range', 1988, 2018, '#d97706'),
  ('a0000000-0000-0000-0000-00000000000d', 'Assets', 'Book advances and royalties', 'A Brief History of Time generated millions in royalties; its success made him financially secure and enabled his continued research.', 'range', 1988, 2018, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000000d', 'Items', 'Motorised wheelchair', 'Used a series of increasingly sophisticated motorised wheelchairs; controlled latterly by cheek muscle movements using an infrared sensor.', 'range', 1970, 2018, '#64748b'),
  ('a0000000-0000-0000-0000-00000000000d', 'Items', 'Intel speech synthesiser', 'Used a custom Intel-equipped speech synthesiser that generated his iconic voice; declined offers to upgrade to a more modern voice.', 'range', 1985, 2018, '#475569');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000000e', 'Place & Travel', 'Far Rockaway, Queens, NY', 'Born and raised in Far Rockaway; tinkered with radios from childhood; father Melville encouraged scientific curiosity through nature walks.', 'range', 1918, 1935, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000e', 'Place & Travel', 'MIT & Princeton', 'Studied at MIT then Princeton for his PhD; perfect score on the Putnam mathematics exam; arrived at Princeton aged 22.', 'range', 1935, 1942, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000e', 'Place & Travel', 'Los Alamos, New Mexico', 'Recruited for the Manhattan Project at Los Alamos aged 24; became notorious for safe-cracking and pranks while doing serious physics.', 'range', 1943, 1945, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000000e', 'Place & Travel', 'Caltech, Pasadena', 'Joined Caltech in 1950 where he spent the rest of his career; loved the Californian atmosphere and Pasadena''s eclectic culture.', 'range', 1950, 1988, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000e', 'Work & Education', 'MIT — Physics degree', 'Graduated from MIT in 1939 with a perfect 4.0 GPA; already writing original physics papers as an undergraduate.', 'range', 1935, 1939, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000000e', 'Work & Education', 'Princeton PhD — path integrals', 'Developed path integral formulation of quantum mechanics in his Princeton doctoral thesis under John Wheeler.', 'range', 1939, 1942, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000000e', 'Work & Education', 'Quantum electrodynamics (QED)', 'Developed QED diagrams — now called Feynman diagrams — providing a revolutionary way to calculate quantum field interactions; Nobel Prize 1965.', 'range', 1947, 1950, '#10b981'),
  ('a0000000-0000-0000-0000-00000000000e', 'Work & Education', 'Feynman Lectures on Physics', 'Delivered the legendary Caltech introductory physics lectures 1961–63; published in three volumes that remain the most read physics texts ever written.', 'range', 1961, 1963, '#059669'),
  ('a0000000-0000-0000-0000-00000000000e', 'Work & Education', 'Challenger disaster investigation', 'Served on the Rogers Commission; famously demonstrated O-ring failure in ice water live on television; added his own minority report.', 'point', 1986, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000000e', 'Health', 'Rare cancers', 'Diagnosed with two rare forms of kidney cancer in 1986; underwent surgery but declined final dialysis, saying "I''d hate to die twice."', 'range', 1986, 1988, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000000e', 'Relations & Family', 'Arline Greenbaum (first wife)', 'Married his high school sweetheart Arline knowing she had tuberculosis; she died in Albuquerque in 1945; he wept when alone.', 'range', 1942, 1945, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000000e', 'Relations & Family', 'Gweneth Howarth (third wife)', 'Met English au pair Gweneth Howarth in Geneva; married 1960; she was the great love of his adult life and they had two children.', 'range', 1960, 1988, '#db2777'),
  ('a0000000-0000-0000-0000-00000000000e', 'Relations & Family', 'Nobel Prize in Physics', 'Shared the 1965 Nobel Prize in Physics with Schwinger and Tomonaga for work on quantum electrodynamics; initially wanted to decline.', 'point', 1965, NULL, '#f97316'),
  ('a0000000-0000-0000-0000-00000000000e', 'Activities', 'Bongo drumming', 'Played bongo drums seriously; performed at a ballet in Pasadena; would often drum at a topless bar in Las Vegas where he did physics on napkins.', 'range', 1945, 1988, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000000e', 'Activities', 'Safe-cracking at Los Alamos', 'Famously picked locks and cracked safes at Los Alamos containing atomic bomb secrets; sent notes to colleagues saying "I know what you''re doing."', 'range', 1943, 1945, '#d97706'),
  ('a0000000-0000-0000-0000-00000000000e', 'Activities', 'Art and strip clubs', 'Drew life models under the pseudonym "Ofey"; the artwork was shown at exhibitions; frequented a Pasadena strip club as his regular office.', 'range', 1955, 1975, '#b45309'),
  ('a0000000-0000-0000-0000-00000000000e', 'Assets', 'Nobel Prize award', 'Won the Nobel Prize in Physics in 1965 worth around $55,000 at the time, shared three ways; used some to fund his travel to Japan.', 'point', 1965, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000000e', 'Items', 'Feynman''s bongo drums', 'His bongo drums were a signature possession; he played them in processions at Caltech and in his famous recorded interviews.', 'range', 1945, 1988, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000000f', 'Place & Travel', 'London & Guildford', 'Born in Maida Vale, London; parents were in India with the ICS; spent childhood shuttling between boarding houses and school.', 'range', 1912, 1926, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000f', 'Place & Travel', 'Sherborne School, Dorset', 'Cycled 60 miles alone on the first day of a national railway strike to get to school; his devotion to mathematics appalled his headmaster.', 'range', 1926, 1931, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000f', 'Place & Travel', 'Cambridge & Princeton', 'Read mathematics at King''s College Cambridge; then studied under Church at Princeton earning his PhD in 1938.', 'range', 1931, 1938, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000000f', 'Place & Travel', 'Bletchley Park', 'Recruited to the Government Code and Cipher School at Bletchley Park in 1939; his work there shortened the war by an estimated two years.', 'range', 1939, 1945, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000000f', 'Work & Education', 'King''s College Cambridge', 'Elected a fellow of King''s College in 1935 for his dissertation on the central limit theorem; his intellectual home for the rest of his life.', 'range', 1931, 1936, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000000f', 'Work & Education', 'On Computable Numbers (1936)', 'Published the foundational paper introducing the concept of the Turing machine — the theoretical basis of all modern computers.', 'point', 1936, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000000f', 'Work & Education', 'Breaking Enigma at Bletchley', 'Led Hut 8 codebreaking operation; designed the electromechanical Bombe that broke Enigma; his work was vital to naval victories in the Atlantic.', 'range', 1939, 1945, '#059669'),
  ('a0000000-0000-0000-0000-00000000000f', 'Work & Education', 'Computing Machinery and Intelligence', 'Published the 1950 paper proposing the Turing Test as a measure of machine intelligence; one of the most cited papers in AI history.', 'point', 1950, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000000f', 'Work & Education', 'Manchester computers and morphogenesis', 'Worked on the Manchester Mark 1 computer and published a groundbreaking paper on morphogenesis explaining how patterns form in nature.', 'range', 1948, 1954, '#10b981'),
  ('a0000000-0000-0000-0000-00000000000f', 'Health', 'Chemical castration', 'Convicted of "gross indecency" in 1952 for his relationship with Arnold Murray; sentenced to hormonal castration; suffered serious side effects.', 'range', 1952, 1954, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000000f', 'Health', 'Death by cyanide', 'Found dead in June 1954 with a half-eaten apple beside him; coroner ruled suicide by cyanide; some historians dispute this finding.', 'point', 1954, NULL, '#dc2626'),
  ('a0000000-0000-0000-0000-00000000000f', 'Relations & Family', 'Christopher Morcom', 'Deep friendship with Christopher Morcom at Sherborne; Morcom died of tuberculosis in 1930; the loss profoundly shaped Turing''s thinking about mind and body.', 'range', 1927, 1930, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000000f', 'Relations & Family', 'Arnold Murray', 'Brief relationship with 19-year-old Arnold Murray led to police investigation and criminal prosecution that destroyed his career.', 'range', 1952, 1952, '#db2777'),
  ('a0000000-0000-0000-0000-00000000000f', 'Activities', 'Marathon running', 'Was a serious long-distance runner; considered trying out for the 1948 British Olympic marathon team and ran a 2:46 time.', 'range', 1945, 1952, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000000f', 'Activities', 'Chess playing', 'Devised one of the first chess-playing algorithms (Turochamp) in 1948; played it out by hand since no computer existed yet to run it.', 'range', 1948, 1953, '#d97706'),
  ('a0000000-0000-0000-0000-00000000000f', 'Assets', 'Royal pardon', 'Granted a posthumous royal pardon in 2013; in 2021 his image was put on the British £50 note — the highest denomination.', 'point', 2013, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000000f', 'Items', 'The Bombe machine', 'The electromechanical Bombe he designed was built in over 200 copies at Bletchley; instrumental in cracking the daily Enigma settings.', 'range', 1940, 1945, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000010', 'Place & Travel', 'Copenhagen, Denmark', 'Born and raised in Copenhagen; father was a physiology professor; grew up in an intellectual household discussing science and philosophy.', 'range', 1885, 1911, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000010', 'Place & Travel', 'England — Rutherford''s lab', 'Spent a formative year at Manchester with Rutherford studying radioactivity; developed his model of the atom.', 'range', 1911, 1913, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000010', 'Place & Travel', 'Copenhagen Institute for Theoretical Physics', 'Founded the institute in 1920 which became the world centre of quantum physics; the "Copenhagen interpretation" is named after it.', 'range', 1920, 1962, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000010', 'Place & Travel', 'USA — Manhattan Project', 'Fled Nazi-occupied Denmark in 1943 to Sweden then UK then Los Alamos; advised on the Manhattan Project under the name Nicholas Baker.', 'range', 1943, 1945, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000010', 'Work & Education', 'PhD University of Copenhagen', 'Earned his doctorate in 1911; thesis on the electron theory of metals identified limitations in classical physics that only quantum theory could fix.', 'range', 1905, 1911, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000010', 'Work & Education', 'Bohr model of the atom', 'Proposed in 1913 that electrons orbit the nucleus in fixed shells and emit radiation when jumping between orbits; Nobel Prize 1922.', 'point', 1913, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000010', 'Work & Education', 'Copenhagen interpretation of quantum mechanics', 'Developed the philosophical framework for understanding quantum mechanics emphasising wave-particle duality and the uncertainty principle.', 'range', 1925, 1935, '#059669'),
  ('a0000000-0000-0000-0000-000000000010', 'Work & Education', 'Debates with Einstein', 'Engaged in famous series of debates with Einstein over quantum mechanics at Solvay conferences; defended Copenhagen interpretation against EPR paradox.', 'range', 1927, 1935, '#047857'),
  ('a0000000-0000-0000-0000-000000000010', 'Work & Education', 'Atoms for Peace advocacy', 'After WWII advocated for open international exchange of nuclear information; wrote to Churchill and Roosevelt arguing secrecy was counterproductive.', 'range', 1944, 1962, '#10b981'),
  ('a0000000-0000-0000-0000-000000000010', 'Health', 'Escape from Nazi Denmark', 'Bohr''s mother was Jewish; fled by fishing boat to Sweden in 1943 days before planned arrest; flew to Scotland in a Mosquito bomber.', 'point', 1943, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000010', 'Relations & Family', 'Margrethe Nørlund (wife)', 'Married in 1912; Margrethe served as a devoted partner and sounding board; they had six sons, two of whom died young.', 'range', 1912, 1962, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000010', 'Relations & Family', 'Werner Heisenberg', 'Deep mentor-student relationship that turned ambiguous during WWII; their famous 1941 Copenhagen meeting has never been fully explained.', 'range', 1922, 1945, '#db2777'),
  ('a0000000-0000-0000-0000-000000000010', 'Activities', 'Football player', 'Was a serious football goalkeeper who played for Akademisk Boldklub; his brother Harald represented Denmark at the 1908 Olympics.', 'range', 1903, 1912, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000010', 'Activities', 'Directed Institute for Theoretical Physics', 'The Bohr Institute attracted every major quantum physicist of the 20th century; Bohr hosted them all, making Copenhagen the centre of world physics.', 'range', 1920, 1962, '#d97706'),
  ('a0000000-0000-0000-0000-000000000010', 'Assets', 'Nobel Prize in Physics 1922', 'Awarded the Nobel Prize for his investigations of atomic structure and radiation; used prize money to fund his institute''s operations.', 'point', 1922, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000010', 'Items', 'Complimentary Carlsberg mansion', 'Carlsberg Brewery awarded Bohr the "House of Honour" — a mansion with a private pipeline connected to the brewery for free beer for life.', 'range', 1932, 1962, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000011', 'Place & Travel', 'Kiel & Munich, Germany', 'Born in Kiel; family moved to Munich where he attended the Maximilian Gymnasium; excelled in music and academics equally.', 'range', 1858, 1874, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000011', 'Place & Travel', 'Munich & Berlin (university)', 'Studied physics at Munich and Berlin; studied under Helmholtz and Kirchhoff; spent his entire academic career in German universities.', 'range', 1874, 1900, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000011', 'Place & Travel', 'Berlin (career-long)', 'Became professor at the University of Berlin in 1889; lived and worked in Berlin through both world wars until evacuation in 1944.', 'range', 1889, 1947, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000011', 'Work & Education', 'University of Munich — physics', 'His Munich professor famously told him physics was a finished subject; Planck replied he didn''t want to discover new things, just understand existing ones.', 'range', 1874, 1879, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000011', 'Work & Education', 'Thermodynamics research', 'PhD thesis on entropy; spent 1880s working on thermodynamics; this led to his work on blackbody radiation and the quantum hypothesis.', 'range', 1879, 1899, '#10b981'),
  ('a0000000-0000-0000-0000-000000000011', 'Work & Education', 'Quantum hypothesis — Planck constant', 'On 14 December 1900 presented his quantum hypothesis to the German Physical Society; called it "an act of desperation" — a revolutionary breakthrough.', 'point', 1900, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000011', 'Work & Education', 'President of Kaiser Wilhelm Society', 'Served as president 1930–37; tried to preserve German science under the Nazis but lost control as Jewish scientists were expelled.', 'range', 1930, 1937, '#047857'),
  ('a0000000-0000-0000-0000-000000000011', 'Work & Education', 'Nobel Prize in Physics 1918', 'Awarded the Nobel Prize for the discovery of energy quanta; used prize money to help fund German scientific institutions after WWI.', 'point', 1918, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000011', 'Health', 'Personal tragedies of the wars', 'Lost his eldest son Karl in WWI; twin daughters both died in childbirth in 1917–18; second son Erwin executed by Nazis in 1945 for alleged role in assassination plot.', 'range', 1914, 1945, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000011', 'Health', 'House destroyed in Berlin', 'His Berlin home was destroyed by Allied bombing in 1944; he spent his final years evacuated to Bavaria, rescued by Allied troops.', 'point', 1944, NULL, '#dc2626'),
  ('a0000000-0000-0000-0000-000000000011', 'Relations & Family', 'Marie Merck (first wife)', 'Married Marie Merck in 1885; had four children; Marie died in 1909 leaving Planck devastated.', 'range', 1885, 1909, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000011', 'Relations & Family', 'Marga von Hoesslin (second wife)', 'Married Marie''s niece Marga in 1911; had one more son Erwin; the family sustained him through personal and national catastrophes.', 'range', 1911, 1947, '#db2777'),
  ('a0000000-0000-0000-0000-000000000011', 'Activities', 'Piano and music', 'Was an accomplished pianist and composer; performed chamber music with Einstein; considered a professional music career before choosing physics.', 'range', 1870, 1930, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000011', 'Activities', 'Mountaineering', 'Was an enthusiastic mountaineer who climbed in the Alps well into his old age; said mountains gave him the same satisfaction as physics.', 'range', 1880, 1920, '#d97706'),
  ('a0000000-0000-0000-0000-000000000011', 'Assets', 'Nobel Prize and professorship', 'Nobel Prize in Physics plus his Berlin professorship provided financial security; Max Planck Institutes worldwide are named in his honour.', 'point', 1918, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000011', 'Items', 'Planck''s blackbody radiation formula', 'The equation he derived on 14 December 1900 — using his constant h — is inscribed on a plaque at the German Physical Society building.', 'point', 1900, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000012', 'Place & Travel', 'Newington Butts, Surrey', 'Born to a poor blacksmith family; had little formal education; family moved to London where he grew up in poverty.', 'range', 1791, 1813, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000012', 'Place & Travel', 'Royal Institution, London', 'Worked at the Royal Institution for over 50 years, eventually living there in a grace-and-favour apartment; it was his entire world.', 'range', 1813, 1867, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000012', 'Place & Travel', 'European tour with Davy', 'Accompanied Humphry Davy and his wife on an 18-month tour of Europe 1813–15; met Volta, Ampère, and other leading scientists.', 'range', 1813, 1815, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000012', 'Work & Education', 'Bookbinder''s apprentice', 'Apprenticed to bookbinder George Riebau aged 14; read every book he bound including Encyclopaedia Britannica''s electricity articles; educated himself entirely.', 'range', 1805, 1812, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000012', 'Work & Education', 'Laboratory assistant to Humphry Davy', 'Sent his meticulous notes of Davy''s Royal Institution lectures to Davy; hired as laboratory assistant in 1813 — his only formal science job application.', 'range', 1813, 1820, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000012', 'Work & Education', 'Discovery of electromagnetic induction', 'In August 1831 demonstrated electromagnetic induction by moving a magnet through a wire coil; the principle behind every electric generator.', 'point', 1831, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000012', 'Work & Education', 'Faraday''s laws of electrolysis', 'Formulated two laws of electrolysis in 1833–34; introduced the terms electrode, cathode, anode, electrolyte, and ion.', 'range', 1833, 1834, '#059669'),
  ('a0000000-0000-0000-0000-000000000012', 'Work & Education', 'Christmas Lectures for children', 'Instituted the Royal Institution Christmas Lectures in 1825; gave them himself 19 times; they continue to this day and are televised annually.', 'range', 1825, 1860, '#047857'),
  ('a0000000-0000-0000-0000-000000000012', 'Work & Education', 'Field theory and Faraday effect', 'Introduced the concept of the electromagnetic field in 1845 and discovered the Faraday effect, linking light and magnetism.', 'range', 1845, 1855, '#10b981'),
  ('a0000000-0000-0000-0000-000000000012', 'Health', 'Mental decline in later life', 'Suffered progressive memory loss and depression from about 1839, attributed to possible chemical poisoning from decades of lab work.', 'range', 1839, 1867, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000012', 'Relations & Family', 'Sarah Barnard (wife)', 'Married Sarah Barnard in 1821 after a six-year courtship; she was a devoted Sandemanian partner; they had no children.', 'range', 1821, 1867, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000012', 'Relations & Family', 'Rivalry with Humphry Davy', 'Davy grew jealous of Faraday''s rising fame; attempted to block his election to the Royal Society; Faraday was elected anyway in 1824.', 'range', 1820, 1829, '#db2777'),
  ('a0000000-0000-0000-0000-000000000012', 'Activities', 'Sandemanian faith', 'Was a deeply devout member of the Sandemanian church, a small Christian sect; twice elected elder; faith was central to his identity.', 'range', 1821, 1867, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000012', 'Activities', 'Public science lectures', 'Gave celebrated Friday Evening Discourses at the Royal Institution attracting fashionable London society; a superb and theatrical communicator.', 'range', 1825, 1862, '#d97706'),
  ('a0000000-0000-0000-0000-000000000012', 'Assets', 'Declined knighthood', 'Declined both a knighthood and the presidency of the Royal Society; said he wished to remain plain Michael Faraday to the end.', 'point', 1857, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000012', 'Assets', 'Grace-and-favour apartment', 'Queen Victoria gave him a grace-and-favour apartment at Hampton Court in 1858 where he spent his final years.', 'range', 1858, 1867, '#0d9488'),
  ('a0000000-0000-0000-0000-000000000012', 'Items', 'Faraday cage', 'Built and demonstrated the Faraday cage in 1836 — a room lined with metal foil that blocked all electrical effects; the principle is used in every microwave oven.', 'point', 1836, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000013', 'Place & Travel', 'Dole, Jura, France', 'Born in a small tanning town; showed early talent for art; family moved to Arbois where he attended school.', 'range', 1822, 1838, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000013', 'Place & Travel', 'Paris — École Normale Supérieure', 'Moved to Paris aged 16 for school; homesick and returned briefly; came back and studied at the École Normale Supérieure, graduating 4th in chemistry.', 'range', 1838, 1849, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000013', 'Place & Travel', 'Strasbourg, Lille & Paris', 'Professor at Strasbourg then Lille; moved back to Paris in 1857 as science director of the École Normale; Paris remained his base.', 'range', 1849, 1895, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000013', 'Work & Education', 'Crystal chirality discovery', 'PhD research on molecular chirality in tartrate crystals; discovered that life produces asymmetric molecules — the origin of biochemistry.', 'range', 1847, 1852, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000013', 'Work & Education', 'Germ theory of fermentation', 'Proved in 1857–63 that fermentation is caused by microorganisms, not spontaneous chemistry; demolished spontaneous generation theory.', 'range', 1857, 1863, '#10b981'),
  ('a0000000-0000-0000-0000-000000000013', 'Work & Education', 'Pasteurization process', 'Developed the process of heating wine and milk to kill pathogens without destroying the product; first applied commercially in the 1860s.', 'range', 1863, 1870, '#059669'),
  ('a0000000-0000-0000-0000-000000000013', 'Work & Education', 'Anthrax and chicken cholera vaccines', 'Developed attenuated vaccines for chicken cholera (1879) and anthrax (1881); dramatic public demonstration at Pouilly-le-Fort proved the anthrax vaccine.', 'range', 1879, 1882, '#047857'),
  ('a0000000-0000-0000-0000-000000000013', 'Work & Education', 'Rabies vaccine', 'Developed rabies vaccine in 1885; first used on human Joseph Meister who had been bitten by a rabid dog; the boy survived.', 'point', 1885, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000013', 'Work & Education', 'Pasteur Institute founded', 'Founded the Pasteur Institute in 1887; became the world''s leading centre for bacteriology and vaccine research; he lived there until his death.', 'range', 1887, 1895, '#059669'),
  ('a0000000-0000-0000-0000-000000000013', 'Health', 'Series of strokes', 'Suffered a severe stroke aged 45 in 1868, leaving him partially paralysed; remarkably continued major research despite hemiplegia.', 'range', 1868, 1895, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000013', 'Relations & Family', 'Marie Laurent (wife)', 'Married the rector''s daughter Marie Laurent in 1849 at Strasbourg; she became an invaluable assistant in his laboratory work.', 'range', 1849, 1895, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000013', 'Relations & Family', 'Death of three children', 'Three of his five children died of typhoid fever; the personal tragedy reinforced his determination to fight infectious disease.', 'range', 1859, 1866, '#db2777'),
  ('a0000000-0000-0000-0000-000000000013', 'Activities', 'Silkworm disease research', 'Spent five years saving the French silk industry by identifying and solving pébrine and flacherie diseases of silkworms on request from Napoleon III.', 'range', 1865, 1870, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000013', 'Activities', 'Porcelain painting', 'Was an accomplished porcelain painter in his youth; several of his works survive including portraits of family members.', 'range', 1835, 1848, '#d97706'),
  ('a0000000-0000-0000-0000-000000000013', 'Assets', 'State pension and honours', 'Received a state pension of 12,000 francs a year from the French government; made a Grand Officer of the Légion d''Honneur.', 'range', 1874, 1895, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000013', 'Items', 'Swan-neck flasks', 'Used specially designed swan-neck flasks in 1859 to disprove spontaneous generation; broth in the curved-neck flasks stayed sterile indefinitely.', 'point', 1859, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000014', 'Place & Travel', 'London, England', 'Born in London; father was Lord Byron who left one month after her birth; raised by her mathematically-minded mother Anne Isabella Milbanke.', 'range', 1815, 1835, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000014', 'Place & Travel', 'London society and country houses', 'Moved between London townhouses and country estates; her mother insisted on intensive mathematics tutoring to suppress any "poetical" tendencies inherited from Byron.', 'range', 1820, 1852, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000014', 'Work & Education', 'Mathematics tutoring by Mary Somerville', 'Studied under celebrated mathematician Mary Somerville from 1834; Somerville introduced her to Charles Babbage at a dinner party.', 'range', 1834, 1836, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000014', 'Work & Education', 'Collaboration with Charles Babbage', 'Became Babbage''s intellectual partner; translated an Italian article about his Analytical Engine and added her own Notes three times longer than the original.', 'range', 1840, 1843, '#10b981'),
  ('a0000000-0000-0000-0000-000000000014', 'Work & Education', 'Notes on the Analytical Engine (1843)', 'Her Notes (published 1843) contained the first published algorithm and her visionary speculation that such an engine could compose music or manipulate symbols.', 'point', 1843, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000014', 'Work & Education', 'Mathematical studies under De Morgan', 'Studied advanced mathematics under Augustus De Morgan of London University; he noted she had the aptitude for an "original mathematical investigator."', 'range', 1840, 1843, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000014', 'Health', 'Childhood paralysis', 'Suffered from measles aged 8 that caused partial paralysis; bedridden for over a year; possibly a factor in later health struggles.', 'range', 1823, 1824, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000014', 'Health', 'Uterine cancer', 'Diagnosed with uterine cancer in 1851; died in November 1852 aged 36 in great pain; buried next to her father Byron in Nottinghamshire.', 'range', 1851, 1852, '#dc2626'),
  ('a0000000-0000-0000-0000-000000000014', 'Relations & Family', 'William King, Earl of Lovelace', 'Married William King in 1835 who became Earl of Lovelace in 1838; had three children; the marriage gave her financial security and social position.', 'range', 1835, 1852, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000014', 'Relations & Family', 'Lord Byron (father)', 'Never knew her famous father who died in Greece when she was 8; her mother hid his portrait; Ada requested burial beside him.', 'range', 1815, 1852, '#db2777'),
  ('a0000000-0000-0000-0000-000000000014', 'Relations & Family', 'Friendship with Charles Dickens', 'Close friend of Dickens; she requested that he read her a passage from Dombey and Son on her deathbed.', 'range', 1843, 1852, '#f97316'),
  ('a0000000-0000-0000-0000-000000000014', 'Activities', 'Horse racing gambling', 'Attempted to develop a mathematical system for betting on horse races; accumulated significant debts of approximately £3,200 and pawned family jewels.', 'range', 1844, 1852, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000014', 'Activities', 'Music study', 'Was an accomplished musician who studied music theory; saw deep parallels between musical harmony and mathematical relationships.', 'range', 1825, 1845, '#d97706'),
  ('a0000000-0000-0000-0000-000000000014', 'Assets', 'Lovelace estate', 'The Lovelace earldom provided estates at East Horsley Park; her husband was supportive of her intellectual pursuits.', 'range', 1838, 1852, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000014', 'Items', 'Babbage''s Analytical Engine plans', 'Worked from Babbage''s mechanical drawings; the Engine was never built but her algorithm for computing Bernoulli numbers would have run on it.', 'range', 1840, 1843, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000015', 'Place & Travel', 'New York City', 'Born in Manhattan to a wealthy Jewish family; father was a textile importer; attended the Ethical Culture School which emphasised science and humanism.', 'range', 1904, 1922, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000015', 'Place & Travel', 'Harvard, Cambridge & Göttingen', 'Graduated Harvard in 3 years; studied at the Cavendish then the University of Göttingen where he earned his PhD under Max Born in 1927.', 'range', 1922, 1929, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000015', 'Place & Travel', 'Berkeley & Caltech', 'Built simultaneous physics departments at Berkeley and Caltech into major centres of theoretical physics; trained a generation of American physicists.', 'range', 1929, 1943, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000015', 'Place & Travel', 'Los Alamos, New Mexico', 'Selected and designed the secret laboratory at Los Alamos as director of the Manhattan Project; lived there with his family 1943–45.', 'range', 1943, 1945, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000015', 'Work & Education', 'Harvard — chemistry to physics', 'Entered Harvard in chemistry; switched to physics in his first year; completed four-year degree in three years with exceptional results.', 'range', 1922, 1925, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000015', 'Work & Education', 'Theoretical physics — neutron stars', 'With his student Volkoff predicted in 1939 the existence of neutron stars and black holes — work largely ignored until confirmed decades later.', 'range', 1935, 1943, '#10b981'),
  ('a0000000-0000-0000-0000-000000000015', 'Work & Education', 'Manhattan Project director', 'Led 6,000 people at Los Alamos; the first atomic bomb was tested at Trinity in July 1945; he quoted the Bhagavad Gita: "Now I am become Death."', 'range', 1943, 1945, '#059669'),
  ('a0000000-0000-0000-0000-000000000015', 'Work & Education', 'Institute for Advanced Study, Princeton', 'Directed the Institute for Advanced Study 1947–66; opposed hydrogen bomb development; advised the Atomic Energy Commission.', 'range', 1947, 1966, '#047857'),
  ('a0000000-0000-0000-0000-000000000015', 'Work & Education', 'Security clearance revoked', 'FBI surveillance of his left-wing associations led to a 1954 hearing stripping his security clearance; publicly humiliated and removed from influence.', 'point', 1954, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000015', 'Health', 'Profound depression post-war', 'Suffered significant psychological guilt after Hiroshima and Nagasaki; told President Truman "I have blood on my hands"; Truman never forgave him.', 'range', 1945, 1954, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000015', 'Health', 'Throat cancer', 'Heavy smoker; diagnosed with throat cancer in 1966; died in February 1967 aged 62.', 'range', 1966, 1967, '#dc2626'),
  ('a0000000-0000-0000-0000-000000000015', 'Relations & Family', 'Katherine "Kitty" Harrison (wife)', 'Married Kitty Harrison in 1940; she had been married three times before; they had two children; she helped him through the security hearing ordeal.', 'range', 1940, 1967, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000015', 'Relations & Family', 'Jean Tatlock', 'Communist Party member and psychiatrist; on-and-off love affair from 1936; her suicide in 1944 devastated Oppenheimer.', 'range', 1936, 1944, '#db2777'),
  ('a0000000-0000-0000-0000-000000000015', 'Activities', 'Sanskrit and Bhagavad Gita', 'Learned Sanskrit to read the Bhagavad Gita in the original; quoted it at Trinity test; the text deeply informed his ethical thinking.', 'range', 1933, 1967, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000015', 'Activities', 'Anti-nuclear advocacy', 'After WWII became the most prominent advocate for international control of nuclear weapons; this advocacy contributed to his political persecution.', 'range', 1945, 1954, '#d97706'),
  ('a0000000-0000-0000-0000-000000000015', 'Assets', 'Perro Caliente ranch', 'Owned a ranch in New Mexico''s Pecos Valley called Perro Caliente; loved horseback riding and the desert landscape that drew him to Los Alamos.', 'range', 1929, 1967, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000015', 'Items', 'Trinity test gadget', 'Led the design of "the Gadget," the first nuclear device detonated at Trinity, New Mexico on 16 July 1945 with a yield of 21 kilotons.', 'point', 1945, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000016', 'Place & Travel', 'Budapest, Hungary', 'Born into a wealthy Jewish banking family; memorised telephone directories for entertainment; learned Latin, Greek, and seven languages as a child.', 'range', 1903, 1921, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000016', 'Place & Travel', 'Berlin, Zürich & Budapest', 'Simultaneously studied chemical engineering at ETH Zurich and mathematics at Budapest; earned both PhD and chemistry degree by 1926.', 'range', 1921, 1930, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000016', 'Place & Travel', 'Princeton — Institute for Advanced Study', 'One of the first six professors appointed to the Institute for Advanced Study in 1933; remained for life; drove a new Cadillac every year.', 'range', 1930, 1957, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000016', 'Work & Education', 'PhD in mathematics — set theory', 'PhD from Budapest at age 22; simultaneously published 32 papers; his PhD thesis established the modern definition of ordinal numbers.', 'range', 1921, 1926, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000016', 'Work & Education', 'Foundations of quantum mechanics', 'Published Mathematical Foundations of Quantum Mechanics in 1932; provided the rigorous mathematical framework for quantum theory.', 'point', 1932, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000016', 'Work & Education', 'Game theory', 'Invented game theory with Morgenstern in Theory of Games and Economic Behavior (1944); transformed economics and strategic thinking.', 'range', 1940, 1944, '#059669'),
  ('a0000000-0000-0000-0000-000000000016', 'Work & Education', 'Manhattan Project and EDVAC', 'Key consultant at Los Alamos; designed the implosion lens for the Fat Man bomb; wrote the EDVAC report defining the von Neumann computer architecture.', 'range', 1943, 1946, '#047857'),
  ('a0000000-0000-0000-0000-000000000016', 'Work & Education', 'MANIAC computer and cellular automata', 'Led construction of IAS MANIAC computer; pioneered Monte Carlo methods and self-replicating automata that prefigured DNA self-replication.', 'range', 1946, 1956, '#10b981'),
  ('a0000000-0000-0000-0000-000000000016', 'Health', 'Cancer from nuclear testing', 'Developed bone and brain cancer, likely from witnessing multiple nuclear tests; died aged 53 in Walter Reed military hospital under military guard.', 'range', 1955, 1957, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000016', 'Relations & Family', 'Mariette Kovesi (first wife)', 'Married Mariette Kovesi in 1930; had one daughter Marina; Mariette left him for a physicist colleague in 1937.', 'range', 1930, 1937, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000016', 'Relations & Family', 'Klara Dan (second wife)', 'Married Hungarian socialite Klara Dan in 1938; she became one of the first computer programmers, coding the MANIAC simulations.', 'range', 1938, 1957, '#db2777'),
  ('a0000000-0000-0000-0000-000000000016', 'Activities', 'Extravagant parties', 'Famous for raucous parties at his Princeton home; entertained with German marching songs and jokes; loved nightclubs despite his genius.', 'range', 1935, 1955, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000016', 'Activities', 'AEC advisory roles', 'Served on the Atomic Energy Commission and influential US military advisory boards; his strategic advice shaped Cold War nuclear policy.', 'range', 1950, 1957, '#d97706'),
  ('a0000000-0000-0000-0000-000000000016', 'Assets', 'Highest-paid government consultant', 'Among the highest-paid scientific consultants in the US government; drove new Cadillacs annually and spent lavishly on parties.', 'range', 1943, 1957, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000016', 'Items', 'von Neumann architecture diagram', 'His 1945 EDVAC report diagram of a CPU, memory, and input/output units defines the architecture of virtually every computer built since.', 'point', 1945, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000017', 'Place & Travel', 'Erlangen, Bavaria', 'Born into a Jewish academic family; father Max Noether was a distinguished mathematician; grew up in a scholarly household.', 'range', 1882, 1900, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000017', 'Place & Travel', 'Erlangen & Göttingen', 'Studied at Erlangen — as an auditor as women couldn''t formally enrol — then spent most of her career at Göttingen, the world centre of mathematics.', 'range', 1900, 1933, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000017', 'Place & Travel', 'Bryn Mawr College, Pennsylvania', 'Fled Nazi Germany in 1933; appointed to Bryn Mawr College in Pennsylvania; also lectured at the Institute for Advanced Study at Princeton.', 'range', 1933, 1935, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000017', 'Work & Education', 'Erlangen University — unofficial student', 'Audited courses at Erlangen (1900–02) when women required special permission; passed exams and enrolled formally from 1904.', 'range', 1900, 1907, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000017', 'Work & Education', 'PhD on algebraic invariants', 'Earned PhD from Erlangen in 1907 under Paul Gordan; thesis on algebraic invariants; described her own work as "crap" years later.', 'range', 1904, 1907, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000017', 'Work & Education', 'Noether''s Theorem (1915)', 'Proved in 1915 that every differentiable symmetry in physics corresponds to a conservation law; Einstein called it "the most significant theorem in mathematical physics."', 'point', 1915, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000017', 'Work & Education', 'Abstract algebra revolution', 'Her 1921 paper on ideal theory and her 1927 work on non-commutative algebras revolutionised abstract algebra; her approach shapes all modern algebra.', 'range', 1920, 1932, '#059669'),
  ('a0000000-0000-0000-0000-000000000017', 'Work & Education', 'Teaching without pay at Göttingen', 'Taught at Göttingen for years without formal appointment or pay; colleagues submitted lecture schedules under their own names on her behalf.', 'range', 1915, 1922, '#047857'),
  ('a0000000-0000-0000-0000-000000000017', 'Health', 'Post-surgery death', 'Died unexpectedly four days after surgery to remove a uterine tumour in 1935, aged 53; Albert Einstein wrote her New York Times obituary.', 'point', 1935, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000017', 'Relations & Family', 'Dismissed by the Nazis', 'Among the first Jewish academics dismissed when the Nazis came to power in 1933; refused a Nazi loyalty oath and was barred from teaching.', 'point', 1933, NULL, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000017', 'Relations & Family', 'Father Max Noether (mentor)', 'Her father was a distinguished mathematician; he supported her education at a time when female mathematicians were extremely rare.', 'range', 1882, 1920, '#db2777'),
  ('a0000000-0000-0000-0000-000000000017', 'Activities', 'Noether school of algebra', 'Attracted a devoted group of students called the "Noether boys" who helped disseminate her abstract algebraic methods worldwide.', 'range', 1920, 1933, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000017', 'Activities', 'Social democracy and pacifism', 'Was an active Social Democrat; opposed WWI; her political views contributed to her precarious employment situation in Germany.', 'range', 1914, 1933, '#d97706'),
  ('a0000000-0000-0000-0000-000000000017', 'Assets', 'Bryn Mawr professorship', 'Finally received a proper paid professorship at Bryn Mawr; the first regular academic salary of her career, aged 51.', 'range', 1933, 1935, '#14b8a6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000018', 'Place & Travel', 'Erode & Kumbakonam, Tamil Nadu', 'Born in Erode; raised in Kumbakonam; passed Government Arts College entrance exam but failed non-mathematical subjects and lost scholarship.', 'range', 1887, 1914, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000018', 'Place & Travel', 'Cambridge, England', 'Invited by G.H. Hardy to Cambridge in 1914; arrived at Trinity College; produced extraordinary results during five years in England.', 'range', 1914, 1919, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000018', 'Place & Travel', 'Madras (return)', 'Returned to India in 1919 gravely ill; died in Kumbakonam in 1920 aged 32, leaving behind notebooks still generating new mathematics today.', 'range', 1919, 1920, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000018', 'Work & Education', 'Self-taught mathematics', 'Mastered the 1902 edition of Carr''s Synopsis of Pure Mathematics by age 13; using it as a template, derived thousands of new results on his own.', 'range', 1900, 1910, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000018', 'Work & Education', 'Clerk at Madras Port Trust', 'Worked as a shipping clerk for ₹30/month; filled notebooks with mathematics in his spare time; sent results to Cambridge professors.', 'range', 1912, 1914, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000018', 'Work & Education', 'Collaboration with G.H. Hardy', 'Hardy recognised his genius from his letter; their collaboration produced masterworks on partitions, mock theta functions, and the taxicab number.', 'range', 1914, 1919, '#10b981'),
  ('a0000000-0000-0000-0000-000000000018', 'Work & Education', 'Hardy-Ramanujan number (1729)', 'On Hardy''s visit saying he came in cab 1729, Ramanujan replied it was the smallest number expressible as sum of two cubes in two different ways.', 'point', 1918, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000018', 'Work & Education', 'Fellow of the Royal Society', 'Elected FRS in 1918 aged 30 — the first Indian FRS and one of the youngest ever elected; also elected Fellow of Trinity College Cambridge.', 'point', 1918, NULL, '#047857'),
  ('a0000000-0000-0000-0000-000000000018', 'Health', 'Tuberculosis and malnutrition', 'Suffered from tuberculosis and other diseases in England worsened by wartime food shortages and difficulty obtaining vegetarian food; hospitalised repeatedly.', 'range', 1917, 1920, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000018', 'Relations & Family', 'Janaki Ammal (wife)', 'Married Janaki Ammal in 1909 arranged by his mother; she was 9 at the time (not uncommon then); Ramanujan lived largely apart from her.', 'range', 1909, 1920, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000018', 'Relations & Family', 'G.H. Hardy', 'Hardy said his collaboration with Ramanujan was the one romantic incident of his mathematical life; deeply admired his intuition.', 'range', 1914, 1920, '#db2777'),
  ('a0000000-0000-0000-0000-000000000018', 'Activities', 'Hindu devotion', 'Was deeply religious; claimed the goddess Namagiri appeared in his dreams and revealed mathematical formulae to him; all his work came from intuition.', 'range', 1887, 1920, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000018', 'Activities', 'Producing results without proofs', 'Most of his formulae came without formal proofs; mathematicians have spent a century proving results from his lost notebook found in 1976.', 'range', 1910, 1920, '#d97706'),
  ('a0000000-0000-0000-0000-000000000018', 'Assets', 'Poverty and scholarship failure', 'Repeatedly failed college due to neglect of non-mathematical subjects; lived in poverty until Hardy''s invitation transformed his circumstances.', 'range', 1905, 1914, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000018', 'Items', 'Ramanujan''s notebooks', 'Left several notebooks crammed with unproven results; the "Lost Notebook" discovered at Trinity in 1976 contained hundreds more; still active research.', 'range', 1904, 1920, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000019', 'Place & Travel', 'Brooklyn, New York', 'Born in Brooklyn to Ukrainian Jewish immigrants; the 1939 World''s Fair sparked his lifelong passion for science and the future.', 'range', 1934, 1951, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000019', 'Place & Travel', 'Chicago & California (study)', 'Studied at the University of Chicago; PhD in astronomy 1960; worked at Yerkes Observatory and Harvard before moving to Cornell.', 'range', 1951, 1968, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000019', 'Place & Travel', 'Cornell University, Ithaca', 'Joined Cornell in 1968 where he built its laboratory for planetary studies; spent his most productive years here.', 'range', 1968, 1996, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000019', 'Work & Education', 'University of Chicago — astronomy', 'Earned his BA, BS, and PhD all from Chicago; inspired by Kuiper and Miller; proved Venus has an extreme greenhouse effect.', 'range', 1951, 1960, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000019', 'Work & Education', 'NASA planetary missions', 'Served as scientific advisor to NASA; briefed Apollo astronauts; contributed to Mariner 2, Viking, Voyager, and Galileo missions.', 'range', 1959, 1995, '#10b981'),
  ('a0000000-0000-0000-0000-000000000019', 'Work & Education', 'Cosmos: A Personal Voyage (1980)', 'Wrote and presented the 13-part Cosmos TV series watched by 500 million people in 60 countries; the most widely watched PBS series in history.', 'point', 1980, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000019', 'Work & Education', 'The Pale Blue Dot', 'Persuaded NASA to turn Voyager 1 around in 1990 to photograph Earth from 6 billion km; the resulting image and his essay became iconic.', 'point', 1990, NULL, '#047857'),
  ('a0000000-0000-0000-0000-000000000019', 'Work & Education', 'Pulitzer Prize for The Dragons of Eden', 'Won the 1978 Pulitzer Prize for General Non-Fiction for The Dragons of Eden on the evolution of human intelligence.', 'point', 1978, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000019', 'Health', 'Myelodysplasia', 'Diagnosed with myelodysplasia (a bone marrow disease) in 1994; underwent three bone marrow transplants from his sister; died December 1996.', 'range', 1994, 1996, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000019', 'Relations & Family', 'Ann Druyan (third wife)', 'Married science writer Ann Druyan in 1981; co-wrote Cosmos and Contact; she produced the Cosmos revival after his death.', 'range', 1981, 1996, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000019', 'Relations & Family', 'Five children', 'Had five children across three marriages; his son Nick Sagan wrote for Star Trek; family remained central to his life.', 'range', 1959, 1996, '#db2777'),
  ('a0000000-0000-0000-0000-000000000019', 'Activities', 'SETI and extraterrestrial life', 'Co-founded the SETI Institute; helped design the Voyager Golden Record; was deeply invested in the search for extraterrestrial intelligence.', 'range', 1961, 1996, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000019', 'Activities', 'Cannabis advocacy', 'Wrote under the pseudonym "Mr. X" about cannabis enhancing scientific thinking; supported marijuana decriminalisation throughout his life.', 'range', 1970, 1996, '#d97706'),
  ('a0000000-0000-0000-0000-000000000019', 'Assets', 'Voyager Golden Record', 'Co-designed the Voyager Golden Record containing sounds and images of Earth; launched in 1977 and now the farthest human-made object from Earth.', 'point', 1977, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000019', 'Items', 'Cosmos turtleneck sweater', 'His casual turtleneck sweaters became an iconic image of the scientist-communicator; his style was deliberately approachable and non-academic.', 'range', 1980, 1996, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000001a', 'Place & Travel', 'London, England', 'Born in southwest London; both parents were mathematicians who worked on the Ferranti Mark 1 computer — the first commercially available computer.', 'range', 1955, 1973, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001a', 'Place & Travel', 'Oxford & Geneva (CERN)', 'Read physics at The Queen''s College Oxford; joined CERN as a software engineer in 1980 where he invented the World Wide Web.', 'range', 1973, 1994, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001a', 'Place & Travel', 'Boston, Massachusetts', 'Founded the World Wide Web Consortium (W3C) at MIT in 1994; also teaches at MIT and Oxford; splits time between US and UK.', 'range', 1994, 2026, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000001a', 'Work & Education', 'Oxford University — physics', 'Graduated from Oxford in 1976 with a first-class degree; built his first computer from an old TV set and an M6800 processor chip.', 'range', 1973, 1976, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000001a', 'Work & Education', 'CERN — software engineer', 'Freelanced at CERN 1980–84; developed Enquire, a hypertext system for tracking projects; returned to CERN in 1984 to develop it further.', 'range', 1980, 1991, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001a', 'Work & Education', 'Invention of the World Wide Web', 'In March 1989 submitted "Information Management: A Proposal" to CERN; his boss Mike Sendall wrote "vague but exciting" on it; the WWW was born.', 'point', 1989, NULL, '#059669'),
  ('a0000000-0000-0000-0000-00000000001a', 'Work & Education', 'First website and browser', 'By December 1990 had built the first web server, browser, and webpage at CERN; the first website went public on 6 August 1991.', 'range', 1990, 1991, '#047857'),
  ('a0000000-0000-0000-0000-00000000001a', 'Work & Education', 'World Wide Web Consortium (W3C)', 'Founded W3C at MIT in 1994 to develop open web standards; has remained director, ensuring the web stays royalty-free and open.', 'range', 1994, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001a', 'Work & Education', 'Solid project — web decentralisation', 'Launched Solid in 2018 to give users control of their own data; a response to surveillance capitalism and data concentration by tech giants.', 'range', 2018, 2026, '#059669'),
  ('a0000000-0000-0000-0000-00000000001a', 'Relations & Family', 'Nancy Carlson (first wife)', 'Married Nancy Carlson, an American colleague, in 1990; divorced in 1994; they had two children together.', 'range', 1990, 1994, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000001a', 'Relations & Family', 'Rosemary Leith (second wife)', 'Married internet activist Rosemary Leith in 2014; together they advocate for net neutrality and an open web.', 'range', 2014, 2026, '#db2777'),
  ('a0000000-0000-0000-0000-00000000001a', 'Activities', 'Web Foundation', 'Founded the World Wide Web Foundation in 2009 to advance the open web as a public good and a basic right.', 'range', 2009, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000001a', 'Activities', 'Olympic opening ceremony', 'Featured in the 2012 London Olympics opening ceremony, tweeting "This is for everyone" from a NeXT computer — the same kind he used to build the web.', 'point', 2012, NULL, '#d97706'),
  ('a0000000-0000-0000-0000-00000000001a', 'Assets', 'Knighthood and Turing Award', 'Knighted in 2004; received the Turing Award (computing''s Nobel Prize) in 2016; chose to give the web away for free rather than patent it.', 'point', 2004, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000001a', 'Items', 'NeXT workstation', 'Developed the first web server on a NeXT workstation at CERN; the machine has a note on it reading "This machine is a server. Do NOT power it down!"', 'range', 1990, 1991, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000001b', 'Place & Travel', 'Helsinki, Finland', 'Born in Helsinki; grew up in a media family — grandfather was a statistician who sparked his interest in computing with a Commodore VIC-20.', 'range', 1969, 1991, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001b', 'Place & Travel', 'Helsinki (University & early Linux)', 'Remained in Helsinki through his studies and early Linux development; served in the Finnish Army briefly.', 'range', 1988, 1997, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001b', 'Place & Travel', 'Silicon Valley, USA', 'Moved to California in 1997 to work for Transmeta; permanently settled in Oregon with his family; now works remotely on Linux.', 'range', 1997, 2026, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000001b', 'Work & Education', 'University of Helsinki — CS', 'Studied computer science; read Andrew Tanenbaum''s Operating Systems textbook which inspired him to write his own kernel.', 'range', 1988, 1996, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000001b', 'Work & Education', 'Linux kernel 0.01 announced', 'Posted to comp.os.minix newsgroup on 25 August 1991: "I''m doing a (free) operating system... just a hobby, won''t be big and professional like gnu."', 'point', 1991, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001b', 'Work & Education', 'Linux kernel maintainer', 'Has maintained the Linux kernel since 1991; every version of Android, most web servers, and all supercomputers run his kernel.', 'range', 1991, 2026, '#059669'),
  ('a0000000-0000-0000-0000-00000000001b', 'Work & Education', 'Git version control system', 'Created Git in 2005 in two weeks after licensing dispute with BitKeeper; Git now underlies virtually all professional software development.', 'point', 2005, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000001b', 'Work & Education', 'Linux Foundation', 'Joined the Linux Foundation as a fellow in 2012, providing an institutional home for his kernel work and ensuring his independence.', 'range', 2012, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001b', 'Health', 'Took leave for behaviour', 'Took a leave of absence in September 2018 after public criticism of his combative email style; returned with commitment to be more considerate.', 'point', 2018, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000001b', 'Relations & Family', 'Tove Monni (wife)', 'Met his wife Tove — a six-time Finnish national karate champion — when she emailed him asking if his Linux class had space; married 1997.', 'range', 1993, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000001b', 'Relations & Family', 'Three daughters', 'Has three daughters with Tove; is described as a devoted family man despite his intense work on the kernel.', 'range', 1996, 2010, '#db2777'),
  ('a0000000-0000-0000-0000-00000000001b', 'Activities', 'Scuba diving', 'Passionate scuba diver; owns a drysuit for diving in the Pacific Northwest; considers it his primary relaxation from computing.', 'range', 2000, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000001b', 'Activities', 'Notorious kernel email style', 'Famous for blunt and sometimes insulting code review emails; his direct approach has been both celebrated and criticised as a barrier to contribution.', 'range', 1991, 2018, '#d97706'),
  ('a0000000-0000-0000-0000-00000000001b', 'Assets', 'Transmeta and Linux wealth', 'Made significant money from Transmeta stock options; Linux Foundation fellowship provides a comfortable income to develop Linux full-time.', 'range', 1997, 2026, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000001b', 'Items', 'Penguin mascot "Tux"', 'Chose the penguin as the Linux mascot after being bitten by a penguin in Canberra; the Tux penguin was designed by Larry Ewing in 1996.', 'point', 1996, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000001c', 'Place & Travel', 'New York City', 'Born in Manhattan; grew up in New York; graduated from Vassar College and earned her PhD from Yale — rare for a woman in that era.', 'range', 1906, 1943, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001c', 'Place & Travel', 'Harvard & Philadelphia (Navy/computing)', 'Joined the Navy during WWII; stationed at Harvard working on the Mark I computer; later at Remington Rand in Philadelphia.', 'range', 1943, 1966, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001c', 'Place & Travel', 'Washington DC — Navy career', 'Continued Naval Reserve career; eventually recalled to active duty in 1967; rose to the rank of Rear Admiral; based in Washington DC.', 'range', 1966, 1986, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000001c', 'Work & Education', 'Vassar & Yale — mathematics PhD', 'Earned her PhD in mathematics from Yale in 1934; her dissertation was on a new type of algebraic criterion; joined the Vassar faculty.', 'range', 1924, 1943, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000001c', 'Work & Education', 'Harvard Mark I programmer', 'Joined the Bureau of Ordnance Computation Project in 1944; wrote the 561-page programming manual for the Mark I; discovered the first actual computer bug.', 'range', 1944, 1949, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001c', 'Work & Education', 'First compiler — A-0 System', 'Invented the first compiler for electronic computers in 1952; demonstrated that programs could be written in English-like syntax not binary.', 'point', 1952, NULL, '#059669'),
  ('a0000000-0000-0000-0000-00000000001c', 'Work & Education', 'COBOL development', 'Led the team that developed COBOL in 1959; the language designed for business data processing; still runs trillions of dollars of transactions daily.', 'range', 1959, 1965, '#047857'),
  ('a0000000-0000-0000-0000-00000000001c', 'Work & Education', 'Navy standardisation of languages', 'As Navy computer science chief pushed for standardisation of programming languages across military systems, shaping computing infrastructure.', 'range', 1967, 1986, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001c', 'Health', 'Retired and recalled repeatedly', 'Retired from the Navy Reserve multiple times but was recalled each time as her expertise was irreplaceable; finally retired at 80 as the oldest active officer.', 'range', 1966, 1986, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000001c', 'Relations & Family', 'Vincent Foster Hopper (husband)', 'Married professor Vincent Hopper in 1930; divorced in 1945; kept his surname; had no children.', 'range', 1930, 1945, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000001c', 'Relations & Family', 'Mentoring generations of programmers', 'Famous for giving nanosecond demonstrations (a foot of wire) to explain light-speed; inspired countless computer scientists.', 'range', 1950, 1992, '#db2777'),
  ('a0000000-0000-0000-0000-00000000001c', 'Activities', 'Lecturing and education', 'Gave thousands of talks at universities championing young people in computing; her motto was "It''s easier to ask forgiveness than permission."', 'range', 1960, 1992, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000001c', 'Activities', 'Backward-running clock', 'Hung a clock running counterclockwise in her office to challenge the assumption that there is only one way to do things.', 'range', 1970, 1992, '#d97706'),
  ('a0000000-0000-0000-0000-00000000001c', 'Assets', 'Presidential Medal of Freedom', 'Awarded the Presidential Medal of Freedom posthumously in 2016 by President Obama; the USS Hopper destroyer was named in her honour in 1997.', 'point', 1986, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000001c', 'Items', 'The first computer bug', 'In 1947 her team removed a moth from the Mark II computer relay; she taped it in the logbook with the note "First actual case of bug being found."', 'point', 1947, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000001d', 'Place & Travel', 'Würzburg & Munich, Germany', 'Born in Würzburg; family moved to Munich where father became a professor; grew up in a cultivated, academic household.', 'range', 1901, 1919, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001d', 'Place & Travel', 'Munich & Göttingen', 'Studied under Sommerfeld in Munich; spent crucial time in Göttingen working with Max Born; developed matrix mechanics there.', 'range', 1919, 1927, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001d', 'Place & Travel', 'Copenhagen & Leipzig', 'Worked with Niels Bohr in Copenhagen; appointed professor at Leipzig aged 26; the mysterious 1941 meeting with Bohr remains debated.', 'range', 1924, 1945, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000001d', 'Work & Education', 'Munich & Göttingen — studies', 'Studied theoretical physics under Sommerfeld; Sommerfeld took him to a lecture by Bohr in 1922 that changed his direction entirely.', 'range', 1919, 1924, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000001d', 'Work & Education', 'Matrix mechanics (1925)', 'On the island of Helgoland, recovering from hay fever, he created matrix mechanics — the first complete formulation of quantum mechanics.', 'point', 1925, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001d', 'Work & Education', 'Uncertainty principle (1927)', 'Formulated the uncertainty principle showing that position and momentum of a particle cannot both be precisely known simultaneously.', 'point', 1927, NULL, '#059669'),
  ('a0000000-0000-0000-0000-00000000001d', 'Work & Education', 'German nuclear weapons programme', 'Led Germany''s nuclear weapons research programme (Uranverein) during WWII; whether he deliberately slowed progress remains controversial.', 'range', 1939, 1945, '#047857'),
  ('a0000000-0000-0000-0000-00000000001d', 'Work & Education', 'Nobel Prize in Physics 1932', 'Awarded the 1932 Nobel Prize for the creation of quantum mechanics; received it in 1933 alongside Schrödinger and Dirac.', 'point', 1932, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001d', 'Health', 'Hay fever — Helgoland breakthrough', 'Retreated to the pollen-free island of Helgoland to escape hay fever; the isolation led directly to his breakthrough in matrix mechanics.', 'point', 1925, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000001d', 'Relations & Family', 'Elisabeth Schumacher (wife)', 'Married concert pianist Elisabeth Schumacher in 1937; had seven children; protected his family by remaining in Germany during WWII.', 'range', 1937, 1976, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000001d', 'Relations & Family', 'Niels Bohr — ambiguous Copenhagen meeting', 'Met privately with Bohr in occupied Copenhagen in 1941; what was discussed has never been established and caused a permanent rift.', 'point', 1941, NULL, '#db2777'),
  ('a0000000-0000-0000-0000-00000000001d', 'Activities', 'Piano playing', 'Was an accomplished pianist; played Bach and Beethoven; considered music and physics to be deeply related forms of pattern recognition.', 'range', 1910, 1976, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000001d', 'Activities', 'Post-war science rebuilding', 'After WWII worked to rebuild German physics; founded the Max Planck Institute for Physics and served as its director.', 'range', 1948, 1970, '#d97706'),
  ('a0000000-0000-0000-0000-00000000001d', 'Assets', 'Max Planck Institute directorship', 'Director of the Max Planck Institute for Physics in Göttingen then Munich; gave German physics institutional prestige after the war.', 'range', 1948, 1976, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000001d', 'Items', 'Farm (Urfeld hideout)', 'Hid his family at their farm near Urfeld in Bavaria as Allied forces closed in; famously bicycled there from Hechingen to be with them in 1945.', 'range', 1943, 1945, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000001e', 'Place & Travel', 'Vienna, Austria', 'Born in Vienna to a botanist father and a half-English mother; educated in Vienna and remained deeply Viennese in temperament throughout his life.', 'range', 1887, 1914, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001e', 'Place & Travel', 'Zürich — key years', 'Professor at ETH Zürich 1921–27; developed his wave equation during a ski holiday at a villa in Arosa over Christmas 1925.', 'range', 1921, 1927, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000001e', 'Place & Travel', 'Berlin & Dublin', 'Succeeded Planck at Berlin; fled Nazis in 1933; spent 17 years at the Dublin Institute for Advanced Studies founded for him by de Valera.', 'range', 1927, 1956, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001e', 'Work & Education', 'Vienna University — physics', 'Studied at Vienna under Friedrich Hasenöhrl; earned his PhD in 1910; served on the Italian front as an artillery officer in WWI.', 'range', 1906, 1920, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000001e', 'Work & Education', 'Schrödinger equation (1926)', 'Derived the wave equation bearing his name during a Christmas ski holiday in Arosa; the central equation of quantum mechanics for non-relativistic systems.', 'point', 1926, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001e', 'Work & Education', 'Nobel Prize in Physics 1933', 'Shared the 1933 Nobel Prize with Dirac for new forms of atomic theory; collected it in Stockholm having been sacked by the Nazis.', 'point', 1933, NULL, '#059669'),
  ('a0000000-0000-0000-0000-00000000001e', 'Work & Education', 'What Is Life? (1944)', 'His Dublin lectures published as What Is Life? influenced Watson and Crick; speculated that genes were "aperiodic crystals" storing information.', 'point', 1944, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000001e', 'Work & Education', 'Schrödinger''s cat thought experiment', 'Devised in 1935 to expose what he saw as absurd implications of the Copenhagen interpretation; became the most famous thought experiment in physics.', 'point', 1935, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001e', 'Health', 'Tuberculosis in early career', 'Suffered from tuberculosis which interrupted his career several times; recovered at sanatoriums in the mountains.', 'range', 1920, 1924, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000001e', 'Relations & Family', 'Anny Bertel (wife)', 'Married Anny Bertel in 1920; their unconventional marriage tolerated multiple affairs on both sides; they remained companions until his death.', 'range', 1920, 1961, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000001e', 'Relations & Family', 'Hildegunde March (companion)', 'Moved to Dublin with his wife and his companion Hildegunde March and her husband; had a daughter with Hildegunde; the arrangement shocked Irish society.', 'range', 1939, 1945, '#db2777'),
  ('a0000000-0000-0000-0000-00000000001e', 'Activities', 'Poetry writing', 'Published a volume of poetry in German; saw poetry and physics as complementary activities; also wrote extensively on Eastern philosophy.', 'range', 1920, 1961, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000001e', 'Activities', 'Eastern philosophy', 'Deeply influenced by the Vedanta philosophy; the concept of consciousness as unified and indivisible shaped his interpretation of quantum mechanics.', 'range', 1918, 1961, '#d97706'),
  ('a0000000-0000-0000-0000-00000000001e', 'Assets', 'Dublin Institute for Advanced Studies', 'De Valera created a special institute in Dublin specifically to attract Schrödinger; he directed its School of Theoretical Physics for 17 years.', 'range', 1939, 1956, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000001e', 'Items', 'Arosa villa notebook', 'The notebook from his Christmas 1925 ski holiday at Arosa where he derived the Schrödinger equation is preserved in Vienna; the derivation fills only a few pages.', 'point', 1925, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000001f', 'Place & Travel', 'Gaylord, Michigan', 'Born in a small Michigan town; grandfather was an inventor and farmer; showed mechanical aptitude from childhood building model planes and radios.', 'range', 1916, 1932, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001f', 'Place & Travel', 'MIT & Bell Labs', 'Studied at MIT for both BS and PhD; spent his most productive career years at Bell Labs in New Jersey where he had extraordinary freedom to work.', 'range', 1932, 1958, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000001f', 'Place & Travel', 'MIT (professorship)', 'Returned to MIT as a professor in 1958 where he remained until retirement; lived in suburban Boston with his juggling unicycles.', 'range', 1958, 2001, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000001f', 'Work & Education', 'MIT — dual degree EE and mathematics', 'Earned both a BS in electrical engineering and a BS in mathematics from Michigan in 1936; then master''s and PhD from MIT.', 'range', 1932, 1940, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000001f', 'Work & Education', 'Master''s thesis on Boolean algebra', 'His MIT master''s thesis (1937) showed that Boolean algebra could optimise telephone switching circuits — described as the most important master''s thesis of the century.', 'point', 1937, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001f', 'Work & Education', 'A Mathematical Theory of Communication (1948)', 'Published the founding paper of information theory defining entropy, the bit, and the channel capacity theorem; one of the most influential papers ever written.', 'point', 1948, NULL, '#059669'),
  ('a0000000-0000-0000-0000-00000000001f', 'Work & Education', 'Cryptography work — WWII', 'Did classified cryptography work at Bell Labs during WWII; met with Alan Turing when Turing visited Bell Labs; their conversations are unrecorded.', 'range', 1940, 1945, '#047857'),
  ('a0000000-0000-0000-0000-00000000001f', 'Work & Education', 'Artificial intelligence work', 'Wrote seminal papers on programming computers to play chess (1950) and design learning machines; helped found AI as a discipline.', 'range', 1950, 1960, '#10b981'),
  ('a0000000-0000-0000-0000-00000000001f', 'Health', 'Alzheimer''s disease', 'Developed Alzheimer''s in the 1990s; spent his final years in a care home in Medford; died in 2001 largely forgotten by the public he had transformed.', 'range', 1990, 2001, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000001f', 'Relations & Family', 'Mary Elizabeth Moore (wife)', 'Married Betty Moore in 1949; she was also a mathematician; they had three children; she survived him.', 'range', 1949, 2001, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000001f', 'Activities', 'Juggling and unicycle riding', 'Was an enthusiastic juggler and unicycle rider; built a juggling robot; would ride his unicycle down Bell Labs corridors while juggling.', 'range', 1950, 1985, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000001f', 'Activities', 'Chess-playing machine Theseus', 'Built Theseus — an electromechanical mouse that learned to navigate a maze — one of the first examples of machine learning, demonstrated in 1950.', 'point', 1950, NULL, '#d97706'),
  ('a0000000-0000-0000-0000-00000000001f', 'Assets', 'Bell Labs freedom and MIT wealth', 'Bell Labs gave him complete intellectual freedom with no administrative duties; became wealthy from the information revolution he created.', 'range', 1941, 1990, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000001f', 'Items', 'THROBAC calculator', 'Built the THROBAC (Thrifty Roman-Numeral Backward-Looking Computer) — a calculator that worked in Roman numerals — as a joke for colleagues.', 'point', 1953, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000020', 'Place & Travel', 'Lochfield Farm, Ayrshire', 'Born on a farm in rural Scotland; the fourth of seven children; grew up wandering the Scottish moors which gave him an eye for nature.', 'range', 1881, 1895, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000020', 'Place & Travel', 'London', 'Moved to London aged 14; worked as a shipping clerk; an uncle''s bequest allowed him to study medicine at St Mary''s Medical School.', 'range', 1895, 1955, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000020', 'Place & Travel', 'European travel and lectures', 'Travelled throughout Europe and North America after his Nobel Prize to receive honorary degrees and awards; a global celebrity scientist.', 'range', 1945, 1955, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000020', 'Work & Education', 'St Mary''s Medical School', 'Studied medicine at St Mary''s, Paddington; won every prize in his year; stayed at St Mary''s for his entire career.', 'range', 1901, 1908, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000020', 'Work & Education', 'WWI wound infections research', 'Served in France as a military doctor in WWI; observed how antiseptics actually killed more soldiers than the bacteria; sought a better solution.', 'range', 1914, 1918, '#10b981'),
  ('a0000000-0000-0000-0000-000000000020', 'Work & Education', 'Discovery of penicillin', 'Returned from holiday in September 1928 to find a mould (Penicillium notatum) had contaminated a petri dish and killed surrounding bacteria.', 'point', 1928, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000020', 'Work & Education', 'Nobel Prize in Physiology or Medicine', 'Shared the 1945 Nobel Prize with Florey and Chain who developed penicillin into a practical drug; Fleming became the public face of the discovery.', 'point', 1945, NULL, '#047857'),
  ('a0000000-0000-0000-0000-000000000020', 'Work & Education', 'Lysozyme discovery', 'Discovered lysozyme — a natural antibacterial enzyme in tears and mucus — in 1922; a precursor to his later penicillin work.', 'point', 1922, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000020', 'Relations & Family', 'Sarah McElroy (first wife)', 'Married Sarah McElroy in 1915; had one son Robert; Sarah died in 1949.', 'range', 1915, 1949, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000020', 'Relations & Family', 'Amalia Koutsouri-Voureka (second wife)', 'Married his Greek former student and colleague Amalia Voureka in 1953; she was 30 years younger; they had two happy years.', 'range', 1953, 1955, '#db2777'),
  ('a0000000-0000-0000-0000-000000000020', 'Activities', 'Germ paintings', 'Created paintings in his lab using bacteria of different colours on culture media; hung them in his office; entertained guests by growing colourful microbial art.', 'range', 1930, 1955, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000020', 'Activities', 'Chelsea Arts Club', 'Was a member of the Chelsea Arts Club and the Savage Club; loved attending bohemian social events; was known as a charming dinner companion.', 'range', 1920, 1955, '#d97706'),
  ('a0000000-0000-0000-0000-000000000020', 'Assets', 'Nobel Prize and honorary degrees', 'Received the Nobel Prize, a knighthood (1944), and honorary degrees from 30 universities; his discovery saved hundreds of millions of lives.', 'range', 1944, 1955, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000020', 'Items', 'Original penicillin culture', 'The original contaminated petri dish from 1928 is preserved at the British Library; Fleming gave samples of the mould to researchers worldwide.', 'point', 1928, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000021', 'Place & Travel', 'Northampton, England', 'Born in Northampton; grandfather was an amateur naturalist who inspired his scientific curiosity; studied at University College London.', 'range', 1916, 1940, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000021', 'Place & Travel', 'Cambridge — Cavendish Laboratory', 'Joined the Cavendish Laboratory at Cambridge in 1949 to do X-ray crystallography; worked alongside Watson and Rosalind Franklin''s data.', 'range', 1949, 1977, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000021', 'Place & Travel', 'Salk Institute, San Diego', 'Moved to the Salk Institute in 1977 to work on consciousness; lived in La Jolla until his death; continued working on the neural correlates of consciousness.', 'range', 1977, 2004, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000021', 'Work & Education', 'UCL physics & Admiralty research', 'Started a physics PhD at UCL; WWII interrupted his studies; worked on magnetic mines for the Admiralty; restarted science after the war in biology.', 'range', 1934, 1949, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000021', 'Work & Education', 'Cambridge PhD on protein crystallography', 'Pursued his PhD while simultaneously working on the DNA structure; his thesis on protein X-ray crystallography was submitted in 1954.', 'range', 1949, 1954, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000021', 'Work & Education', 'Double helix discovery (1953)', 'With James Watson, built the correct double-helix model of DNA in February 1953 using Franklin''s X-ray Photo 51 data; ran into the Eagle pub announcing discovery.', 'point', 1953, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000021', 'Work & Education', 'Central Dogma of molecular biology', 'Formulated the central dogma in 1957: genetic information flows from DNA to RNA to protein; the organising principle of molecular biology.', 'point', 1957, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000021', 'Work & Education', 'Nobel Prize in Physiology or Medicine 1962', 'Shared with Watson and Wilkins; Franklin had died in 1958 and the Nobel is not awarded posthumously.', 'point', 1962, NULL, '#047857'),
  ('a0000000-0000-0000-0000-000000000021', 'Health', 'Colon cancer', 'Diagnosed with colon cancer in 2001; continued working until close to his death in 2004 at the Salk Institute.', 'range', 2001, 2004, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000021', 'Relations & Family', 'Odile Speed (second wife)', 'Married artist Odile Speed in 1949; she designed the iconic double helix illustration for Watson and Crick''s 1953 Nature paper.', 'range', 1949, 2004, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000021', 'Relations & Family', 'James Watson partnership', 'Intense intellectual partnership with Watson at Cambridge; their 18-month collaboration to solve DNA structure was one of the great partnerships in science.', 'range', 1951, 1953, '#db2777'),
  ('a0000000-0000-0000-0000-000000000021', 'Activities', 'Consciousness research', 'Spent his final 27 years studying the neural basis of consciousness with neuroscientist Christof Koch; published The Astonishing Hypothesis in 1994.', 'range', 1977, 2004, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000021', 'Activities', 'Outspoken atheism', 'Was a vocal atheist and humanist; resigned from Churchill College Cambridge over a proposed chapel; signed public letters on ethics and science.', 'range', 1960, 2004, '#d97706'),
  ('a0000000-0000-0000-0000-000000000021', 'Assets', 'Salk Institute fellowship', 'The Salk Institute provided him with an exceptional environment for his later work; he held a distinguished professorship there.', 'range', 1977, 2004, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000021', 'Items', 'Photo 51', 'Rosalind Franklin''s X-ray diffraction Photo 51 shown to Watson without her knowledge was the key evidence for the double helix structure.', 'point', 1953, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000022', 'Place & Travel', 'Råshult, Sweden', 'Born in a rural vicarage; father tended a garden and imparted a love of plants; grew up surrounded by botanical specimens.', 'range', 1707, 1727, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000022', 'Place & Travel', 'Uppsala & Lapland expedition', 'Studied at Uppsala University; undertook a five-month scientific expedition through Lapland in 1732 covering 4,600 miles and recording hundreds of new species.', 'range', 1727, 1738, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000022', 'Place & Travel', 'Uppsala (career-long)', 'Returned to Uppsala as professor from 1741 until his death; transformed the university''s botanical garden into the best in Scandinavia.', 'range', 1741, 1778, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000022', 'Work & Education', 'Lund & Uppsala University', 'Studied medicine and botany; showed such promise that a professor allowed him to tutor other students in his second year.', 'range', 1727, 1735, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000022', 'Work & Education', 'Systema Naturae (1735)', 'Published at age 28 in the Netherlands; established a classification system for all living organisms; went through 12 editions in his lifetime.', 'point', 1735, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000022', 'Work & Education', 'Binomial nomenclature standardised', 'By his 1753 Species Plantarum, had fully standardised the two-name system for species; every biological organism is still named using his method.', 'point', 1753, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000022', 'Work & Education', 'Uppsala professor and director', 'Appointed professor of medicine at Uppsala in 1741; quickly switched to botany chair; his lectures drew students from across Europe.', 'range', 1741, 1778, '#047857'),
  ('a0000000-0000-0000-0000-000000000022', 'Work & Education', 'Trained the "Apostles"', 'Sent 17 former students worldwide on natural history expeditions — his "Apostles"; several died in the field collecting specimens for him.', 'range', 1745, 1775, '#10b981'),
  ('a0000000-0000-0000-0000-000000000022', 'Relations & Family', 'Sara Lisa Moraea (wife)', 'Married Sara Lisa Moraea in 1739; her dowry financed his first years of practice; they had seven children.', 'range', 1739, 1778, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000022', 'Activities', 'Lapland expedition', 'Solo five-month Lapland expedition in 1732; returned with over 100 new plant species; collected in traditional Sami clothing; reported in Flora Lapponica.', 'range', 1732, 1732, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000022', 'Activities', 'Wednesday botanical excursions', 'Held celebrated Wednesday excursions with up to 300 students into the Swedish countryside to study plants; became social events in Uppsala.', 'range', 1742, 1778, '#d97706'),
  ('a0000000-0000-0000-0000-000000000022', 'Assets', 'Nobility and Hammarby estate', 'Granted Swedish nobility in 1761 as Carl von Linné; purchased Hammarby estate outside Uppsala where his herbarium is preserved.', 'range', 1761, 1778, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000022', 'Items', 'Herbarium collections', 'His personal herbarium of over 14,000 specimens is preserved by the Linnean Society of London; it is the world''s most important botanical collection.', 'range', 1730, 1778, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000023', 'Place & Travel', 'Paris, France', 'Born into a wealthy Parisian family; father was a lawyer; mother died when he was 5; inherited a large fortune and devoted it to science.', 'range', 1743, 1794, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000023', 'Work & Education', 'Collège Mazarin — law and sciences', 'Studied law to satisfy his father but devoted himself to science; studied under Rouelle who transformed his understanding of chemistry.', 'range', 1754, 1764, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000023', 'Work & Education', 'Election to Académie des Sciences', 'Elected to the French Royal Academy of Sciences in 1768 aged just 25; the academy gave him a platform to reform chemistry.', 'point', 1768, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000023', 'Work & Education', 'Oxygen discovery and naming', 'Identified and named oxygen in 1778; proved it was essential to combustion and respiration; overturned the phlogiston theory of fire.', 'point', 1778, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000023', 'Work & Education', 'Law of conservation of mass', 'Formulated the law of conservation of mass in 1789: matter is neither created nor destroyed in chemical reactions; the foundation of quantitative chemistry.', 'point', 1789, NULL, '#047857'),
  ('a0000000-0000-0000-0000-000000000023', 'Work & Education', 'Traité élémentaire de chimie (1789)', 'Published the first modern chemistry textbook; listed 33 chemical elements; introduced systematic chemical nomenclature; defined chemistry as a quantitative science.', 'point', 1789, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000023', 'Work & Education', 'Tax farming and public service', 'Invested in the Ferme générale tax-collection company and used the profits to fund his science; also improved French gunpowder and street lighting.', 'range', 1769, 1794, '#059669'),
  ('a0000000-0000-0000-0000-000000000023', 'Health', 'Guillotined during the Terror', 'Arrested as a tax farmer in 1793; tried by Revolutionary tribunal on 8 May 1794; guillotined the same day; mathematician Lagrange said: "It took them only an instant to cut off that head, and a hundred years may not produce another like it."', 'point', 1794, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000023', 'Relations & Family', 'Marie-Anne Paulze (wife)', 'Married 13-year-old Marie-Anne Paulze in 1771; she learned English and translated chemical papers for him; drew the illustrations for his textbook.', 'range', 1771, 1794, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000023', 'Activities', 'Gunpowder Commission', 'Appointed to the Royal Gunpowder Administration; tripled French gunpowder production and improved its quality; the American Revolution benefited from his powder.', 'range', 1775, 1792, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000023', 'Activities', 'Paris street lighting project', 'Developed a competition for a new lamp to light Paris streets; ran his laboratory beneath the Paris arsenal; improved urban life directly.', 'range', 1766, 1780, '#d97706'),
  ('a0000000-0000-0000-0000-000000000023', 'Assets', 'Arsenal laboratory', 'Ran an extraordinary private laboratory at the Paris Arsenal; equipped with the finest instruments money could buy; supported collaborators.', 'range', 1776, 1794, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000023', 'Items', 'Precision balance', 'His custom precision balance — accurate to 0.0005 grams — was central to his discoveries; enabled the quantitative chemistry that transformed the science.', 'range', 1770, 1794, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000024', 'Place & Travel', 'Clermont-Ferrand, France', 'Born in central France; mother died when he was 3; his father was a mathematician who educated him at home in Paris.', 'range', 1623, 1631, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000024', 'Place & Travel', 'Paris and Rouen', 'Family moved to Paris; father moved to Rouen as tax commissioner in 1639; Pascal built his calculating machine here to help his father.', 'range', 1631, 1647, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000024', 'Place & Travel', 'Paris (later life)', 'Returned to Paris; after his 1654 religious conversion lived an increasingly ascetic life, eventually in seclusion at Port-Royal.', 'range', 1647, 1662, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000024', 'Work & Education', 'Child mathematics prodigy', 'Without being taught geometry, derived 32 propositions of Euclid independently at age 11; his father showed Descartes who was amazed.', 'range', 1631, 1640, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000024', 'Work & Education', 'Pascaline mechanical calculator', 'Built the Pascaline in 1642 to help his father calculate taxes; the first working mechanical calculator; built 50 prototypes and sold 20.', 'range', 1642, 1645, '#10b981'),
  ('a0000000-0000-0000-0000-000000000024', 'Work & Education', 'Probability theory with Fermat', 'Developed probability theory in correspondence with Fermat in 1654 on gambling problems; laid foundations for statistics and actuarial science.', 'range', 1654, 1654, '#059669'),
  ('a0000000-0000-0000-0000-000000000024', 'Work & Education', 'Atmospheric pressure experiments', 'Replicated and extended Torricelli''s barometer; sent his brother-in-law up Puy de Dôme in 1648 to prove air pressure decreases with altitude.', 'range', 1646, 1648, '#047857'),
  ('a0000000-0000-0000-0000-000000000024', 'Work & Education', 'Pensées (published posthumously)', 'His unfinished apologia for Christianity published after his death; contains Pascal''s Wager and some of the most beautiful French prose ever written.', 'range', 1657, 1662, '#10b981'),
  ('a0000000-0000-0000-0000-000000000024', 'Health', 'Chronic illness throughout life', 'Suffered from severe illnesses throughout his life; thought to have been a combination of stomach cancer, tuberculosis, and multiple sclerosis.', 'range', 1647, 1662, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000024', 'Health', 'Religious conversion', 'In November 1654 had a two-hour mystical experience he called the "night of fire"; sewed a description in his coat lining; devoted himself to religion.', 'point', 1654, NULL, '#dc2626'),
  ('a0000000-0000-0000-0000-000000000024', 'Relations & Family', 'Jacqueline Pascal (sister)', 'His sister Jacqueline became a Jansenist nun at Port-Royal; her influence contributed to his religious conversion; she died in 1661 of grief over religious persecution.', 'range', 1623, 1661, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000024', 'Activities', 'Paris omnibus system', 'Organised one of the first public transport systems — a horse-drawn carriage service in Paris in 1662; the profits went to charity.', 'point', 1662, NULL, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000024', 'Activities', 'Jansenist controversy', 'Wrote the Provincial Letters defending Jansenism against the Jesuits; the witty, polemical letters are masterpieces of French polemic.', 'range', 1656, 1657, '#d97706'),
  ('a0000000-0000-0000-0000-000000000024', 'Items', 'The Pascaline calculator', 'His mechanical calculator is preserved in several copies; the Musée des Arts et Métiers in Paris holds the largest collection of surviving examples.', 'range', 1642, 1662, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000025', 'Place & Travel', 'Leipzig, Germany', 'Born in Leipzig; father was a philosophy professor who died when Leibniz was 6; access to his father''s library allowed him to self-educate prodigiously.', 'range', 1646, 1666, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000025', 'Place & Travel', 'Paris diplomatic mission', 'Sent to Paris in 1672 on a diplomatic mission; met Huygens and Malebranche; developed calculus independently in Paris; one of the most productive periods of his life.', 'range', 1672, 1676, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000025', 'Place & Travel', 'Hanover (court service)', 'Entered service of the House of Brunswick in Hanover in 1676; served as librarian, historian, and diplomat; remained in Hanover for 40 years.', 'range', 1676, 1716, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000025', 'Work & Education', 'Leipzig & Jena universities', 'Entered Leipzig University aged 15; read Descartes, Galileo, and Bacon; moved to Jena; earned his law doctorate at Altdorf at 20.', 'range', 1661, 1672, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000025', 'Work & Education', 'Development of calculus', 'Developed calculus independently of Newton between 1673 and 1676; published his notation (∫ and d) in 1684; his notation became the standard.', 'range', 1673, 1684, '#10b981'),
  ('a0000000-0000-0000-0000-000000000025', 'Work & Education', 'Binary arithmetic', 'Developed the binary number system in 1679, motivated by Chinese hexagrams; the foundation of all digital computing three centuries later.', 'point', 1679, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000025', 'Work & Education', 'Stepped Reckoner calculator', 'Built the first mechanical calculator capable of multiplication and division in 1673; demonstrated it to the Royal Society in London.', 'range', 1672, 1694, '#047857'),
  ('a0000000-0000-0000-0000-000000000025', 'Work & Education', 'Monadology philosophy', 'Published the Monadology in 1714; argued the universe consists of simple, indivisible monads; one of the great works of metaphysics.', 'point', 1714, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000025', 'Health', 'Died isolated and forgotten', 'His patron had moved to London as George I; died alone in Hanover in 1716; his secretary was the only mourner at his funeral.', 'point', 1716, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000025', 'Relations & Family', 'Priority dispute with Newton', 'The Newton-Leibniz calculus priority dispute, orchestrated largely by Newton, damaged his reputation; historians now credit both independently.', 'range', 1699, 1716, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000025', 'Activities', 'Founding academies of science', 'Proposed and helped found the Berlin Academy of Sciences in 1700 and proposed similar institutions in Vienna and St Petersburg.', 'range', 1700, 1716, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000025', 'Activities', 'Diplomatic missions', 'Undertook major diplomatic missions across Europe; tried to persuade Louis XIV to invade Egypt instead of the Netherlands; met Spinoza.', 'range', 1672, 1690, '#d97706'),
  ('a0000000-0000-0000-0000-000000000025', 'Assets', 'Brunswick court librarian', 'Served as court librarian and historian; his vast correspondence of 15,000 letters is preserved; wrote over a million words in his lifetime.', 'range', 1676, 1716, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000025', 'Items', 'Leibniz Stepped Reckoner', 'The mechanical calculator he built featured a stepped cylinder gear (Leibniz wheel) still used in mechanical calculators until the 20th century.', 'range', 1672, 1694, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000026', 'Place & Travel', 'Weil der Stadt, Germany', 'Born prematurely in Württemberg; difficult childhood with a mercenary father who abandoned the family; nearly blinded by smallpox aged 4.', 'range', 1571, 1589, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000026', 'Place & Travel', 'Graz & Prague', 'Taught mathematics in Graz; fled Counter-Reformation; joined Tycho Brahe in Prague in 1600; inherited Brahe''s observational data on his death.', 'range', 1594, 1612, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000026', 'Place & Travel', 'Linz, Austria', 'Worked as district mathematician in Linz for 14 years; his mother was tried for witchcraft; he successfully defended her over a six-year ordeal.', 'range', 1612, 1630, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000026', 'Work & Education', 'Tübingen University', 'Studied theology at Tübingen; introduced to Copernican astronomy by professor Maestlin; diverted from ministry to mathematics.', 'range', 1589, 1594, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000026', 'Work & Education', 'First and Second Laws of Planetary Motion', 'Published Astronomia Nova in 1609; the first two laws — elliptical orbits and equal areas in equal times — overturned circular orbit theory.', 'point', 1609, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000026', 'Work & Education', 'Third Law of Planetary Motion', 'Published in Harmonices Mundi in 1619; the square of a planet''s period is proportional to the cube of its semi-major axis; Newton used it to derive gravitation.', 'point', 1619, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000026', 'Work & Education', 'Rudolphine Tables', 'Published astronomical tables based on Brahe''s observations in 1627; predicted a transit of Mercury in 1631; the most accurate tables of the era.', 'point', 1627, NULL, '#047857'),
  ('a0000000-0000-0000-0000-000000000026', 'Work & Education', 'Optics and the telescope', 'Published Astronomiae Pars Optica in 1604; described how the eye works and atmospheric refraction; designed an improved refracting telescope.', 'range', 1604, 1611, '#10b981'),
  ('a0000000-0000-0000-0000-000000000026', 'Health', 'Poor health throughout life', 'Suffered throughout his life; the smallpox that damaged his eyesight as a child was only one of many illnesses that plagued him.', 'range', 1575, 1630, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000026', 'Relations & Family', 'Mother''s witchcraft trial', 'His mother Katharina was accused of witchcraft in 1615; Kepler abandoned his own work for six years to defend her; she was eventually freed.', 'range', 1615, 1621, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000026', 'Relations & Family', 'Barbara Müller (first wife)', 'First wife died in 1611 leaving him with two surviving children; his second wife Susanna Reuttinger was chosen from an eleven-candidate list.', 'range', 1597, 1611, '#db2777'),
  ('a0000000-0000-0000-0000-000000000026', 'Activities', 'Science fiction — Somnium', 'Wrote Somnium (The Dream), describing a voyage to the Moon using demons; considered one of the first works of science fiction; published posthumously.', 'range', 1608, 1630, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000026', 'Assets', 'Imperial Mathematician appointment', 'Succeeded Tycho Brahe as Imperial Mathematician to Emperor Rudolf II; paid erratically but the title gave him prestige and protection.', 'range', 1601, 1612, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000026', 'Items', 'Tycho Brahe''s observational data', 'Inherited Brahe''s extraordinary precise naked-eye observations after his death in 1601; the data was the basis for all three planetary laws.', 'range', 1601, 1627, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000027', 'Place & Travel', 'Hynčice, Moravia (now Czech Republic)', 'Born to poor farmers; worked as a child to earn school fees; his teachers recommended him for higher education despite family poverty.', 'range', 1822, 1843, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000027', 'Place & Travel', 'Brno (Augustinian monastery)', 'Joined the Augustinian monastery of St Thomas in Brno in 1843; the monastery gave him education, security, and his famous garden.', 'range', 1843, 1884, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000027', 'Place & Travel', 'Vienna (university studies)', 'Studied at the University of Vienna 1851–53 on the monastery''s behalf; learned physics under Doppler and botany under Unger.', 'range', 1851, 1853, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000027', 'Work & Education', 'Augustinian friar and teacher', 'Ordained a priest in 1847; worked as a substitute teacher; twice failed the teacher certification exam due to anxiety but was an outstanding teacher.', 'range', 1847, 1868, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000027', 'Work & Education', 'Pea plant experiments', 'Grew 29,000 pea plants over eight years in the monastery garden; meticulously tracked seven characteristics; derived his two laws of inheritance.', 'range', 1856, 1863, '#10b981'),
  ('a0000000-0000-0000-0000-000000000027', 'Work & Education', 'Laws of inheritance published (1866)', 'Presented his findings to the Natural History Society of Brno in 1865; published in 1866; received little notice and was rediscovered only in 1900.', 'point', 1866, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000027', 'Work & Education', 'Abbot of St Thomas', 'Elected Abbot of the monastery in 1868; administrative duties consumed his time; never returned to the genetic experiments that would make him famous.', 'range', 1868, 1884, '#047857'),
  ('a0000000-0000-0000-0000-000000000027', 'Relations & Family', 'Darwin parallel (unknown)', 'Mendel owned and read Darwin''s On the Origin of Species with marginal notes; it is not known if he recognised the connection to his own work.', 'range', 1859, 1884, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000027', 'Activities', 'Meteorology', 'Was a dedicated meteorologist who kept daily records of weather and barometric pressure for years; a member of the Austrian Meteorological Society.', 'range', 1856, 1884, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000027', 'Activities', 'Bee breeding experiments', 'After his pea experiments, tried to demonstrate laws of inheritance in bees; the results were inconclusive because bee genetics is far more complex.', 'range', 1870, 1879, '#d97706'),
  ('a0000000-0000-0000-0000-000000000027', 'Assets', 'Monastery resources', 'The Augustinian monastery provided his livelihood, education, and his famous experimental garden; without it, his work would have been impossible.', 'range', 1843, 1884, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000027', 'Items', 'The pea garden', 'Mendel''s 35-metre experimental garden at the Brno monastery is now marked by a memorial; his original pea plants were the foundation of modern genetics.', 'range', 1856, 1863, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000028', 'Place & Travel', 'Edinburgh, Scotland', 'Born in Edinburgh; family had a strong tradition in speech and elocution; his mother was deaf, shaping his lifelong interest in sound.', 'range', 1847, 1870, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000028', 'Place & Travel', 'Canada & Boston', 'Family emigrated to Ontario in 1870 for health reasons; Bell moved to Boston to teach deaf students and continued his experiments there.', 'range', 1870, 1882, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000028', 'Place & Travel', 'Washington DC & Nova Scotia', 'Established headquarters in Washington DC; also built a summer home at Baddeck in Nova Scotia where he conducted aerial experiments.', 'range', 1882, 1922, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000028', 'Work & Education', 'Teaching at Boston School for the Deaf', 'Taught deaf students using his father''s Visible Speech system; met his future wife Mabel Hubbard as a deaf student.', 'range', 1872, 1876, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000028', 'Work & Education', 'Invention of the telephone (1876)', 'Received patent No. 174,465 on 7 March 1876 — described as the most valuable patent ever granted; first words transmitted: "Mr Watson, come here."', 'point', 1876, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000028', 'Work & Education', 'Bell Telephone Company founded', 'Founded the Bell Telephone Company in 1877 with Mabel''s father as investor; eventually became AT&T — the largest phone company in history.', 'range', 1877, 1900, '#059669'),
  ('a0000000-0000-0000-0000-000000000028', 'Work & Education', 'Later inventions', 'Invented the photophone (optical telephone), the audiometer, and contributed to aviation through his Aerial Experiment Association.', 'range', 1880, 1909, '#047857'),
  ('a0000000-0000-0000-0000-000000000028', 'Work & Education', 'National Geographic Society', 'Became president of the National Geographic Society in 1897 and transformed it into a mass-circulation magazine with photographs.', 'range', 1897, 1904, '#10b981'),
  ('a0000000-0000-0000-0000-000000000028', 'Health', 'Refused telephone in his study', 'Found the telephone too intrusive and refused to have one in his study; also could not sleep during daylight hours — a lifelong night owl.', 'range', 1876, 1922, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000028', 'Relations & Family', 'Mabel Hubbard (wife)', 'Married his deaf pupil Mabel Hubbard in 1877; she had been deaf since age 5; they had two daughters and a deeply loving 45-year marriage.', 'range', 1877, 1922, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000028', 'Relations & Family', 'Elisha Gray dispute', 'Both Bell and Elisha Gray filed telephone patents the same day in 1876; Bell''s application was processed first; Gray''s caveat arrived hours later.', 'point', 1876, NULL, '#db2777'),
  ('a0000000-0000-0000-0000-000000000028', 'Activities', 'Sheep breeding experiments', 'Conducted careful breeding experiments with sheep at Beinn Bhreagh to understand heredity; contributed modestly to genetic knowledge.', 'range', 1895, 1910, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000028', 'Activities', 'Aviation research', 'Developed tetrahedral kites and helped found the Aerial Experiment Association; the Silver Dart made the first powered flight in Canada in 1909.', 'range', 1893, 1910, '#d97706'),
  ('a0000000-0000-0000-0000-000000000028', 'Assets', 'Telephone patent wealth', 'The telephone patent made him extremely wealthy; he used the money to fund research into many areas including aviation and disability.', 'range', 1877, 1922, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000028', 'Items', 'First telephone', 'The original liquid-transmitter telephone used on 10 March 1876 is preserved at the Smithsonian Institution in Washington DC.', 'point', 1876, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000029', 'Place & Travel', 'Rome', 'Born into a patrician family; grew up in the Subura, Rome''s most crowded district; educated in rhetoric and Greek.', 'range', -100, -68, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000029', 'Place & Travel', 'Spain and the East', 'Served as military quaestor in Spain; captured by pirates near Rhodes and had them crucified after his ransom was paid.', 'range', -75, -60, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000029', 'Place & Travel', 'Gaul conquest campaigns', 'Commanded armies across Gaul (modern France and Belgium) for eight years; wrote detailed campaign diaries that remain military classics.', 'range', -58, -50, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000029', 'Place & Travel', 'Egypt — with Cleopatra', 'Pursued Pompey to Egypt; Pompey was murdered before his arrival; allied with Cleopatra VII and fathered a son with her.', 'range', -48, -47, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000029', 'Work & Education', 'Roman Senate and political career', 'Rose through the cursus honorum; elected consul in -59; formed the First Triumvirate with Pompey and Crassus to dominate Roman politics.', 'range', -68, -49, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000029', 'Work & Education', 'Conquest of Gaul', 'Defeated hundreds of tribes across Gaul; killed or enslaved over a million people; written up in Commentarii de Bello Gallico — his own propaganda.', 'range', -58, -50, '#10b981'),
  ('a0000000-0000-0000-0000-000000000029', 'Work & Education', 'Crossing the Rubicon — civil war', 'Crossed the Rubicon river in January -49 with his legion, triggering civil war; defeated Pompey; became dictator perpetuo.', 'point', -49, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000029', 'Work & Education', 'Reforms as dictator', 'Reformed the Roman calendar (introducing the Julian calendar), resettled the poor in colonies, and attempted to reorganise the Republic.', 'range', -47, -44, '#047857'),
  ('a0000000-0000-0000-0000-000000000029', 'Health', 'Epilepsy', 'Ancient sources report he suffered from epileptic seizures; this may have contributed to the belief he had a divine connection.', 'range', -49, -44, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000029', 'Relations & Family', 'Cleopatra VII', 'Became lovers with Cleopatra in Alexandria; she visited Rome and bore his son Caesarion; their alliance reshaped the eastern Mediterranean.', 'range', -48, -44, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000029', 'Relations & Family', 'Brutus and the conspiracy', 'Was assassinated on 15 March -44 by 23 stab wounds inflicted by a Senate conspiracy led by Brutus and Cassius; he fell at the foot of Pompey''s statue.', 'point', -44, NULL, '#db2777'),
  ('a0000000-0000-0000-0000-000000000029', 'Activities', 'Writing and oratory', 'Was considered one of Rome''s greatest orators; his Gallic Wars writing is clear, direct, and deliberately self-promoting; studied rhetoric in Rhodes.', 'range', -80, -44, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000029', 'Assets', 'Conquest wealth', 'The conquest of Gaul filled his war chest; he paid off debts and bribed his way through Roman politics; controlled enormous resources as dictator.', 'range', -58, -44, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000029', 'Items', 'Julian Calendar', 'Introduced the Julian calendar in -46 with 365 days and a leap year every four; remained the standard in most of Europe for over 1,600 years.', 'point', -46, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000002a', 'Place & Travel', 'Pella, Macedonia', 'Born in Pella; tutored by Aristotle from age 13; tamed the horse Bucephalus at 16 while his father''s court failed; Philip II called him fit to rule.', 'range', -356, -336, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002a', 'Place & Travel', 'Persian Empire campaigns', 'Crossed the Hellespont in -334; won at Granicus, Issus, and Gaugamela; crossed the entirety of the Persian Empire in less than a decade.', 'range', -334, -327, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000002a', 'Place & Travel', 'India and return', 'Crossed the Hindu Kush and invaded India; his troops mutinied at the Hyphasis River; returned through the Gedrosian desert with catastrophic losses.', 'range', -327, -323, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002a', 'Work & Education', 'Tutored by Aristotle', 'Aristotle tutored him at Mieza from -343 to -340; gave him annotated copies of Homer''s Iliad which Alexander kept under his pillow with a dagger.', 'range', -343, -336, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000002a', 'Work & Education', 'King of Macedonia at 20', 'Became king after Philip II''s assassination in -336; immediately crushed revolts in Greece and secured his power before launching east.', 'range', -336, -334, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002a', 'Work & Education', 'Conquest of Persia', 'Defeated Darius III three times; took Persepolis (the Persian capital) and burned it; declared himself King of Persia and successor to Cyrus.', 'range', -334, -330, '#059669'),
  ('a0000000-0000-0000-0000-00000000002a', 'Work & Education', 'Foundation of Alexandria and other cities', 'Founded over 20 cities named Alexandria; Egypt''s Alexandria became the greatest city of the ancient world and home of the great Library.', 'range', -332, -323, '#047857'),
  ('a0000000-0000-0000-0000-00000000002a', 'Work & Education', 'Conquest to India', 'Reached the Punjab in -326; defeated King Porus at the Battle of the Hydaspes; his easternmost campaign; troops refused to go further.', 'range', -327, -325, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002a', 'Health', 'Heavy drinking and mysterious death', 'Was a heavy drinker; died in Babylon in June -323 aged 32 after a ten-day fever; cause debated — typhoid, poisoning, or alcoholism.', 'range', -330, -323, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000002a', 'Relations & Family', 'Hephaestion (closest companion)', 'His dearest friend from boyhood; Alexander called himself Achilles to Hephaestion''s Patroclus; devastated by Hephaestion''s death in -324.', 'range', -356, -324, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000002a', 'Relations & Family', 'Roxana (wife)', 'Married Bactrian noblewoman Roxana in -327; she bore him a posthumous son Alexander IV; their marriage was both political and romantic.', 'range', -327, -323, '#db2777'),
  ('a0000000-0000-0000-0000-00000000002a', 'Activities', 'Hunting and athletics', 'Was an accomplished hunter and athlete; initiated lion hunts as royal entertainment; participated in the Olympic games tradition of Macedonia.', 'range', -350, -323, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000002a', 'Assets', 'Persian treasury', 'Captured the Persian treasuries at Persepolis, Pasargadae, and Susa containing over 180,000 talents of gold and silver — inconceivable wealth.', 'range', -330, -323, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000002a', 'Items', 'Bucephalus (war horse)', 'His black horse Bucephalus carried him through all his battles from -334 to -326; founded a city (Bucephala) where the horse died.', 'range', -340, -326, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000002b', 'Place & Travel', 'Corsica', 'Born in Ajaccio, Corsica — the island had been sold by Genoa to France just a year before his birth; never entirely felt French.', 'range', 1769, 1779, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002b', 'Place & Travel', 'France — military schools', 'Educated at the military academy at Brienne then the École Militaire in Paris; graduated an artillery officer in 1785.', 'range', 1779, 1793, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002b', 'Place & Travel', 'Egypt campaign', 'Led the Egyptian expedition of 1798–99; fought the Battle of the Pyramids; the campaign made him famous though strategically ambiguous.', 'range', 1798, 1799, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000002b', 'Place & Travel', 'Exiles — Elba and St Helena', 'Exiled to Elba in 1814; escaped and returned for the Hundred Days; exiled to remote St Helena after Waterloo where he died.', 'range', 1814, 1821, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000002b', 'Work & Education', 'Military academy and artillery', 'Mastered artillery tactics at the French military academies; his artillery innovations at Toulon in 1793 first brought him to national attention.', 'range', 1784, 1796, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000002b', 'Work & Education', 'Italian campaigns — general', 'Led French armies to stunning victories in Italy in 1796–97; signed the Treaty of Campo Formio; became the most famous general in Europe.', 'range', 1796, 1797, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002b', 'Work & Education', 'First Consul then Emperor', 'Seized power in the coup of 18 Brumaire 1799; made himself Emperor in 1804; dominated European politics until 1814.', 'range', 1799, 1814, '#059669'),
  ('a0000000-0000-0000-0000-00000000002b', 'Work & Education', 'Napoleonic Code', 'Promulgated the Code civil des Français in 1804; still the basis of civil law in France, Louisiana, Quebec, and dozens of other jurisdictions.', 'point', 1804, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000002b', 'Health', 'Probable stomach cancer', 'Suffered from stomach pain for years; arsenic may have contributed; died aged 51 on St Helena — probable cause was stomach cancer.', 'range', 1815, 1821, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000002b', 'Relations & Family', 'Joséphine de Beauharnais', 'Married Joséphine in 1796; she was 6 years older and had two children; he divorced her in 1809 after she failed to produce an heir.', 'range', 1796, 1809, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000002b', 'Relations & Family', 'Marie-Louise of Austria', 'Married Archduchess Marie-Louise in 1810 to secure Habsburg alliance; she bore him a son Napoleon II; she never visited him in exile.', 'range', 1810, 1821, '#db2777'),
  ('a0000000-0000-0000-0000-00000000002b', 'Activities', 'Chess playing', 'Was a keen chess player; played at St Helena and against automaton the Turk in 1809; deliberately made illegal moves to test the machine.', 'range', 1800, 1821, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000002b', 'Activities', 'Reading and historical study', 'Read voraciously, particularly history and military science; his library at St Helena contained over 3,000 volumes; dictated his memoirs relentlessly.', 'range', 1790, 1821, '#d97706'),
  ('a0000000-0000-0000-0000-00000000002b', 'Assets', 'Louvre art collection', 'Looted art from across Europe for the Louvre; removed over 5,000 works from conquered territories; many were returned after his defeat.', 'range', 1796, 1814, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000002b', 'Items', 'Bicorn hat', 'Wore his iconic bicorn hat sideways so he could be recognised in battle; around 20 of his hats survive in museums; one sold for €1.9 million in 2014.', 'range', 1796, 1815, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000002c', 'Place & Travel', 'Kentucky & Indiana frontier', 'Born in a log cabin in Kentucky; family moved to Indiana; mother died when he was 9; grew up in extreme poverty on the frontier.', 'range', 1809, 1830, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002c', 'Place & Travel', 'Springfield, Illinois', 'Settled in Springfield to practise law; elected to state legislature and Congress; this was his home for 24 years before the presidency.', 'range', 1837, 1861, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002c', 'Place & Travel', 'Washington DC — presidency', 'Moved to the White House in March 1861; guided the nation through its greatest crisis; assassinated at Ford''s Theatre in April 1865.', 'range', 1861, 1865, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000002c', 'Work & Education', 'Self-education and law', 'Had less than a year of formal schooling; taught himself law by reading Blackstone''s Commentaries; admitted to the bar in 1836.', 'range', 1830, 1844, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000002c', 'Work & Education', 'Illinois state legislature', 'Served four terms in the Illinois House of Representatives 1834–42; established a reputation for integrity and wit.', 'range', 1834, 1842, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002c', 'Work & Education', 'US Congress and Lincoln-Douglas debates', 'Served one term in Congress; the 1858 Lincoln-Douglas Senate debates on slavery brought him national recognition though he lost the Senate race.', 'range', 1847, 1858, '#059669'),
  ('a0000000-0000-0000-0000-00000000002c', 'Work & Education', 'President during Civil War', 'Led the Union through the Civil War; appointed Grant as general; refused to negotiate a peace that preserved slavery.', 'range', 1861, 1865, '#047857'),
  ('a0000000-0000-0000-0000-00000000002c', 'Work & Education', 'Emancipation Proclamation', 'Issued the Emancipation Proclamation on 1 January 1863, declaring all enslaved people in Confederate states to be free.', 'point', 1863, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002c', 'Health', 'Depression (the "hypo")', 'Suffered severe depression throughout his life, which he called "the hypo"; his law partner said he was the most melancholy man he ever knew.', 'range', 1835, 1865, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000002c', 'Relations & Family', 'Mary Todd (wife)', 'Married Mary Todd in 1842 after a broken engagement; she was from a wealthy Kentucky family; their marriage was stormy and loving.', 'range', 1842, 1865, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000002c', 'Relations & Family', 'Death of Willie Lincoln', 'His 11-year-old son Willie died in the White House in 1862; the death devastated both Lincoln and Mary, who never recovered.', 'point', 1862, NULL, '#db2777'),
  ('a0000000-0000-0000-0000-00000000002c', 'Relations & Family', 'Assassination at Ford''s Theatre', 'Shot by John Wilkes Booth at Ford''s Theatre on 14 April 1865; died the following morning; the first US president to be assassinated.', 'point', 1865, NULL, '#f97316'),
  ('a0000000-0000-0000-0000-00000000002c', 'Activities', 'Storytelling and humour', 'Was a gifted storyteller whose jokes and anecdotes are still quoted; used humour as a coping mechanism and political tool.', 'range', 1820, 1865, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000002c', 'Activities', 'Wrestling champion', 'Was nearly undefeated in frontier wrestling before his political career; only lost once in approximately 300 bouts; inducted into Wrestling Hall of Fame.', 'range', 1828, 1836, '#d97706'),
  ('a0000000-0000-0000-0000-00000000002c', 'Assets', 'Patent holder', 'Is the only US president to hold a patent — for a device to lift boats over shoals; filed in 1849 though the device was never manufactured.', 'point', 1849, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000002c', 'Items', 'Stovepipe hat', 'His iconic tall stovepipe hat — which he used as a filing cabinet for papers — is preserved at the Smithsonian; height made him appear even taller.', 'range', 1850, 1865, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000002d', 'Place & Travel', 'Blenheim Palace, Oxfordshire', 'Born prematurely at Blenheim Palace; father was Lord Randolph Churchill; mother Jennie Jerome was American; largely raised by his nanny Mrs Everest.', 'range', 1874, 1893, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002d', 'Place & Travel', 'India, Cuba, Sudan & South Africa', 'Served as cavalry officer in Cuba, India, Sudan (Omdurman), and South Africa; his escape from Boer captivity made him famous.', 'range', 1895, 1900, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000002d', 'Place & Travel', 'London (political career)', 'Based in London throughout his political career; lived at Chartwell in Kent which he purchased in 1922 and cherished as his home.', 'range', 1900, 1965, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002d', 'Work & Education', 'Sandhurst & early military career', 'Failed entrance to Sandhurst twice; passed on third attempt; commissioned into the 4th Queen''s Own Hussars in 1895.', 'range', 1893, 1900, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000002d', 'Work & Education', 'Member of Parliament and ministerial career', 'Elected to Parliament in 1900; served in every major Cabinet role; First Lord of the Admiralty, Home Secretary, Chancellor of the Exchequer.', 'range', 1900, 1940, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002d', 'Work & Education', 'Prime Minister during WWII', 'Became Prime Minister in May 1940 when the Phoney War ended; his wartime speeches — "We shall fight on the beaches" — defined Allied resolve.', 'range', 1940, 1945, '#059669'),
  ('a0000000-0000-0000-0000-00000000002d', 'Work & Education', 'Nobel Prize in Literature (1953)', 'Awarded the Nobel Prize in Literature for his historical works including The Second World War, a six-volume memoir of extraordinary scope.', 'point', 1953, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000002d', 'Work & Education', 'Second term as PM', 'Returned as Prime Minister in 1951 aged 77; suffered a stroke in 1953 kept secret from the public; resigned in 1955.', 'range', 1951, 1955, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002d', 'Health', 'The Black Dog — depression', 'Suffered from recurring depression he called his "Black Dog"; feared going near balconies lest he jump; the depression never broke his output.', 'range', 1910, 1965, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000002d', 'Health', 'Multiple strokes', 'Suffered a major stroke in 1953 kept from the public for months; earlier strokes in 1949 and 1952; health deteriorated markedly after 1955.', 'range', 1949, 1965, '#dc2626'),
  ('a0000000-0000-0000-0000-00000000002d', 'Relations & Family', 'Clementine Hozier (wife)', 'Married Clementine Hozier in 1908; she was his anchor and most trusted advisor; their correspondence is one of the great love letter collections.', 'range', 1908, 1965, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000002d', 'Relations & Family', 'Five children', 'Had five children; their son Randolph was a controversial journalist; daughter Sarah became an actress; Diana and Marigold died young.', 'range', 1909, 1965, '#db2777'),
  ('a0000000-0000-0000-0000-00000000002d', 'Activities', 'Painting', 'Took up painting in 1915 after the Gallipoli disaster as therapy; produced over 500 paintings; exhibited under a pseudonym; genuinely talented.', 'range', 1915, 1965, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000002d', 'Activities', 'Bricklaying and Chartwell garden', 'Built walls and cottage at Chartwell himself; a member of the Bricklayers'' Union; found physical work therapeutic alongside his writing.', 'range', 1922, 1960, '#d97706'),
  ('a0000000-0000-0000-0000-00000000002d', 'Assets', 'Chartwell estate', 'Purchased Chartwell in Kent in 1922 for £5,000; nearly bankrupted by the upkeep; a consortium of friends anonymously bought and donated it to the National Trust.', 'range', 1922, 1965, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000002d', 'Items', 'Siren suit', 'Churchill''s one-piece "siren suit" — like an adult romper — became iconic; he wore it in meetings with Roosevelt and Stalin; had dozens made.', 'range', 1939, 1955, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000002e', 'Place & Travel', 'Porbandar, Gujarat, India', 'Born in a coastal town in Gujarat to the diwan (chief minister) of the principality; mother was deeply religious and shaped his values.', 'range', 1869, 1888, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002e', 'Place & Travel', 'London — Inner Temple', 'Studied law in London 1888–91; encountered vegetarianism, the Bhagavad Gita, and Tolstoy''s writings; called to the bar and returned to India.', 'range', 1888, 1891, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000002e', 'Place & Travel', 'South Africa (21 years)', 'Went to South Africa in 1893 for a legal case; stayed 21 years; developed satyagraha (nonviolent resistance) against racial discrimination.', 'range', 1893, 1914, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002e', 'Place & Travel', 'India (independence campaign)', 'Returned to India in 1914; transformed the Indian National Congress; led campaigns across the subcontinent.', 'range', 1914, 1948, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000002e', 'Work & Education', 'Law degree in London', 'Called to the bar at the Inner Temple in 1891; returned to India but struggled as a lawyer; the South Africa opportunity transformed his life.', 'range', 1888, 1893, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000002e', 'Work & Education', 'South African civil rights campaigns', 'Led campaigns against the pass laws and discriminatory legislation; founded the Natal Indian Congress; developed satyagraha philosophy.', 'range', 1894, 1914, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002e', 'Work & Education', 'Non-cooperation movement', 'Launched the Non-Cooperation Movement in 1920; hundreds of thousands boycotted British goods, courts, and schools.', 'range', 1920, 1922, '#059669'),
  ('a0000000-0000-0000-0000-00000000002e', 'Work & Education', 'Salt March and Civil Disobedience', 'Led the 240-mile Salt March to Dandi in 1930; his followers made salt from the sea in defiance of the British salt tax; was arrested.', 'point', 1930, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000002e', 'Work & Education', 'Quit India Movement', 'Launched the Quit India campaign in 1942; was imprisoned for two years; India gained independence in 1947 though Partition horrified him.', 'range', 1942, 1944, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002e', 'Health', 'Fasting as political weapon', 'Undertook 17 major fasts in his lifetime as political protest; the fasts attracted global attention and forced political compromises.', 'range', 1913, 1948, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000002e', 'Relations & Family', 'Kasturba Gandhi (wife)', 'Married Kasturba in an arranged marriage aged 13; she initially resisted his experiments in communal living; became his devoted partner; died in 1944 in prison.', 'range', 1882, 1944, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000002e', 'Relations & Family', 'Assassination', 'Shot three times by Nathuram Godse on 30 January 1948 at a prayer meeting in Delhi; Godse was a Hindu nationalist who opposed Gandhi''s tolerance toward Muslims.', 'point', 1948, NULL, '#db2777'),
  ('a0000000-0000-0000-0000-00000000002e', 'Activities', 'Spinning cotton (charkha)', 'Spun cotton daily on his spinning wheel (charkha) as a symbol of Indian self-sufficiency; a wheel is depicted on the Indian flag.', 'range', 1920, 1948, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000002e', 'Activities', 'Experiments in simple living', 'Founded communal ashrams and lived in deliberate simplicity; experimented with diet, celibacy (brahmacharya), and alternative medicine.', 'range', 1905, 1948, '#d97706'),
  ('a0000000-0000-0000-0000-00000000002e', 'Items', 'Spinning wheel and dhoti', 'His simple dhoti and charkha spinning wheel became global symbols of resistance; his round glasses and walking stick complete the iconic image.', 'range', 1920, 1948, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000002f', 'Place & Travel', 'Mvezo, Eastern Cape, South Africa', 'Born in a small village; father was a chief; enrolled in a Methodist school; moved to Fort Beaufort after his father''s death.', 'range', 1918, 1941, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002f', 'Place & Travel', 'Johannesburg', 'Moved to Johannesburg in 1941 to escape arranged marriage; worked as a mine security guard; studied law; joined the ANC.', 'range', 1941, 1964, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000002f', 'Place & Travel', 'Robben Island (prison)', 'Imprisoned on Robben Island from 1964–1982; spent 18 years in a tiny cell; continued studying and organising politically.', 'range', 1964, 1988, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000002f', 'Work & Education', 'University of Fort Hare & Witwatersrand', 'Studied at Fort Hare; expelled for strike; completed BA by correspondence; studied law at Witwatersrand — one of the first black law students there.', 'range', 1938, 1952, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000002f', 'Work & Education', 'ANC Youth League and Defiance Campaign', 'Co-founded the ANC Youth League in 1944; organised the 1952 Defiance Campaign against apartheid laws; ANC membership rose tenfold.', 'range', 1944, 1956, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002f', 'Work & Education', 'Underground resistance and armed struggle', 'Founded Umkhonto we Sizwe (MK) the ANC armed wing in 1961 after the Sharpeville massacre; planned sabotage campaigns.', 'range', 1961, 1964, '#059669'),
  ('a0000000-0000-0000-0000-00000000002f', 'Work & Education', 'Rivonia Trial and life sentence', 'Tried at the Rivonia Trial in 1963–64; convicted of sabotage and conspiracy; sentenced to life imprisonment; made a famous "I am prepared to die" speech.', 'point', 1964, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000002f', 'Work & Education', 'President of South Africa', 'Released in 1990; negotiated end of apartheid; elected South Africa''s first black president in 1994 with 62% of the vote; served one term.', 'range', 1994, 1999, '#10b981'),
  ('a0000000-0000-0000-0000-00000000002f', 'Health', '27 years imprisonment', 'The 27 years of imprisonment, much of it in harsh conditions, took a severe physical toll; his lungs were damaged by silica dust from quarry work.', 'range', 1964, 1990, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000002f', 'Relations & Family', 'Evelyn Mase (first wife)', 'Married nurse Evelyn Mase in 1944; had four children; she became a Jehovah''s Witness and they divorced in 1958.', 'range', 1944, 1958, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000002f', 'Relations & Family', 'Winnie Madikizela (second wife)', 'Married Winnie Madikizela in 1958; she endured persecution and exile while he was imprisoned; they separated in 1992 due to her controversies.', 'range', 1958, 1996, '#db2777'),
  ('a0000000-0000-0000-0000-00000000002f', 'Relations & Family', 'Graça Machel (third wife)', 'Married former Mozambican first lady Graça Machel on his 80th birthday in 1998; she was with him until his death in 2013.', 'range', 1998, 2013, '#f97316'),
  ('a0000000-0000-0000-0000-00000000002f', 'Activities', 'Rugby World Cup 1995', 'Wore the Springbok jersey to present the Rugby World Cup to South Africa''s captain François Pienaar; a defining moment of reconciliation.', 'point', 1995, NULL, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000002f', 'Activities', 'Nobel Peace Prize', 'Shared the Nobel Peace Prize with FW de Klerk in 1993 for their peaceful dismantling of apartheid; accepted in Oslo.', 'point', 1993, NULL, '#d97706'),
  ('a0000000-0000-0000-0000-00000000002f', 'Assets', 'Qunu home', 'Maintained a home in Qunu, Eastern Cape, the village where he spent his childhood; retired there after his presidency; buried there in 2013.', 'range', 1994, 2013, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000002f', 'Items', 'Robben Island prison cell', 'His 2.1m x 2.4m cell on Robben Island is now a museum visited by millions; the number 46664 — his prison number — became his HIV/AIDS campaign name.', 'range', 1964, 1982, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000030', 'Place & Travel', 'Westmoreland County, Virginia', 'Born on a tobacco plantation; father died when he was 11; eldest half-brother Lawrence became his mentor; grew up in Virginia gentry society.', 'range', 1732, 1752, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000030', 'Place & Travel', 'Barbados (only foreign travel)', 'Made his only trip outside North America to Barbados in 1751 accompanying his brother Lawrence for health; contracted smallpox which immunised him.', 'range', 1751, 1752, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000030', 'Place & Travel', 'Mount Vernon & Valley Forge', 'Mount Vernon was his beloved home; Valley Forge was the lowest point — his Continental Army suffered terribly there in the winter of 1777–78.', 'range', 1759, 1799, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000030', 'Work & Education', 'Virginia militia and French-Indian War', 'Served as Virginia militia officer from age 22; his ambush that triggered the French and Indian War made him famous in the colonies.', 'range', 1752, 1758, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000030', 'Work & Education', 'Continental Army Commander', 'Appointed Commander of the Continental Army in June 1775; held together a ragged force against the world''s best army for eight years.', 'range', 1775, 1783, '#10b981'),
  ('a0000000-0000-0000-0000-000000000030', 'Work & Education', 'Constitutional Convention', 'Presided over the Constitutional Convention in Philadelphia in 1787; his presence gave the convention legitimacy and his influence shaped the final document.', 'point', 1787, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000030', 'Work & Education', 'First President of the United States', 'Unanimously elected first President in 1789; served two terms; established the precedent of a peaceful transfer of power by voluntarily stepping down.', 'range', 1789, 1797, '#047857'),
  ('a0000000-0000-0000-0000-000000000030', 'Work & Education', 'Farewell Address', 'His 1796 Farewell Address warned against political parties and foreign entanglements; remained one of the most cited presidential documents.', 'point', 1796, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000030', 'Health', 'Smallpox inoculation', 'Inoculated himself against smallpox after his 1751 infection; later ordered the inoculation of the Continental Army — a crucial military decision.', 'point', 1777, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000030', 'Relations & Family', 'Martha Dandridge Custis (wife)', 'Married wealthy widow Martha Custis in 1759; she joined him at Valley Forge; they had no biological children together but raised her two children.', 'range', 1759, 1799, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000030', 'Relations & Family', 'Enslaved people at Mount Vernon', 'Enslaved over 300 people at Mount Vernon; was conflicted but never freed them in life; his will freed them upon Martha''s death.', 'range', 1745, 1799, '#db2777'),
  ('a0000000-0000-0000-0000-000000000030', 'Activities', 'Farming and crop rotation', 'Was a passionate and scientifically-minded farmer who experimented with crop rotation, fertilisers, and new techniques; kept meticulous farm journals.', 'range', 1759, 1799, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000030', 'Activities', 'Surveying', 'Worked as a professional surveyor in his teenage years; his skills informed his military terrain judgment throughout the Revolution.', 'range', 1748, 1752, '#d97706'),
  ('a0000000-0000-0000-0000-000000000030', 'Assets', 'Mount Vernon plantation', 'Inherited Mount Vernon and expanded it to over 8,000 acres; ran a distillery and fishery; among the wealthiest men in colonial Virginia.', 'range', 1752, 1799, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000030', 'Items', 'Dentures', 'Suffered lifelong tooth loss; his dentures were made from ivory, animal teeth, and human teeth — not wooden, as legend claims.', 'range', 1781, 1799, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000031', 'Place & Travel', 'Hyde Park, New York', 'Born into one of New York''s most prominent families; raised at Springwood estate; educated by private tutors and travelled to Europe frequently.', 'range', 1882, 1900, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000031', 'Place & Travel', 'Warm Springs, Georgia', 'Established a polio rehabilitation centre at Warm Springs after his own diagnosis; died there in April 1945 while sitting for a portrait.', 'range', 1924, 1945, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000031', 'Work & Education', 'Harvard and Columbia Law', 'Graduated Harvard in three years; attended Columbia Law School; passed the bar without completing the degree; joined a Wall Street firm.', 'range', 1900, 1907, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000031', 'Work & Education', 'New York political career', 'Elected to New York state senate 1910; served as Assistant Secretary of the Navy 1913–20 under Woodrow Wilson; ran unsuccessfully for Vice President.', 'range', 1910, 1920, '#10b981'),
  ('a0000000-0000-0000-0000-000000000031', 'Work & Education', 'Governor of New York', 'Elected Governor of New York in 1928 despite disability; launched state relief programmes that became the template for the New Deal.', 'range', 1929, 1933, '#059669'),
  ('a0000000-0000-0000-0000-000000000031', 'Work & Education', 'President — New Deal', 'Elected 1932 in a landslide; the New Deal created Social Security, the SEC, the FDIC, and put millions back to work through public works.', 'range', 1933, 1940, '#047857'),
  ('a0000000-0000-0000-0000-000000000031', 'Work & Education', 'President — World War II', 'Led the US through WWII after Pearl Harbor; the Arsenal of Democracy, Lend-Lease, and the Normandy invasion planning all bore his direction.', 'range', 1941, 1945, '#10b981'),
  ('a0000000-0000-0000-0000-000000000031', 'Health', 'Poliomyelitis', 'Diagnosed with polio in 1921 at age 39; lost the use of his legs; wore heavy braces and used a wheelchair; the extent of his disability was hidden from the public.', 'range', 1921, 1945, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000031', 'Relations & Family', 'Eleanor Roosevelt (wife)', 'Married his cousin Eleanor in 1905; she became a transformative First Lady and UN diplomat; their marriage survived his affairs.', 'range', 1905, 1945, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000031', 'Relations & Family', 'Lucy Mercer Rutherfurd', 'Had a long love affair with his wife''s social secretary Lucy Mercer; Eleanor discovered it in 1918; Lucy was with FDR when he died.', 'range', 1916, 1945, '#db2777'),
  ('a0000000-0000-0000-0000-000000000031', 'Activities', 'Stamp collecting', 'Was a passionate and knowledgeable philatelist who collected stamps from around the world; his collection was auctioned after his death.', 'range', 1890, 1945, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000031', 'Activities', 'Fireside chats', 'Used radio to deliver 30 "fireside chat" broadcasts directly to American homes; restored public confidence during the Depression.', 'range', 1933, 1944, '#d97706'),
  ('a0000000-0000-0000-0000-000000000031', 'Assets', 'Springwood estate, Hyde Park', 'The family estate at Hyde Park, New York was his political home base; he is buried there; now a national historic site.', 'range', 1882, 1945, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000031', 'Items', 'Wheelchair and leg braces', 'His custom lightweight wheelchair — made from a desk chair — enabled mobility; heavy steel braces allowed him to stand for public appearances.', 'range', 1921, 1945, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000003c', 'Place & Travel', 'Atlanta, Georgia', 'Born in Atlanta; grandfather and father were both Baptist ministers; grew up in a middle-class African American family shielded from the worst segregation.', 'range', 1929, 1948, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003c', 'Place & Travel', 'Boston & Montgomery', 'Earned his PhD at Boston University 1951–55; moved to Montgomery, Alabama as pastor; the Montgomery bus boycott launched his career.', 'range', 1948, 1960, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003c', 'Place & Travel', 'Atlanta (SCLC base) & travels', 'Based in Atlanta for the SCLC; travelled constantly across the South and North; gave over 2,500 speeches in the final decade of his life.', 'range', 1960, 1968, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000003c', 'Work & Education', 'Morehouse, Crozer & Boston University', 'Entered Morehouse College aged 15; studied at Crozer Theological Seminary; earned his PhD in systematic theology from Boston University.', 'range', 1944, 1955, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000003c', 'Work & Education', 'Montgomery Bus Boycott', 'Led the 381-day Montgomery Bus Boycott 1955–56 after Rosa Parks'' arrest; the Supreme Court ruled segregated buses unconstitutional.', 'range', 1955, 1956, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003c', 'Work & Education', 'SCLC and Birmingham campaign', 'Founded the Southern Christian Leadership Conference in 1957; the 1963 Birmingham campaign with fire hoses and dogs shocked the nation.', 'range', 1957, 1963, '#059669'),
  ('a0000000-0000-0000-0000-00000000003c', 'Work & Education', '"I Have a Dream" speech', 'Delivered the speech to 250,000 at the March on Washington on 28 August 1963; one of the greatest speeches in American history.', 'point', 1963, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000003c', 'Work & Education', 'Nobel Peace Prize and Voting Rights Act', 'Won the Nobel Peace Prize in 1964 aged 35 — the youngest recipient; the Civil Rights Act and Voting Rights Act followed his campaigns.', 'range', 1964, 1965, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003c', 'Health', 'FBI surveillance and threats', 'Subjected to intensive FBI surveillance; J. Edgar Hoover sent him a letter urging him to commit suicide; survived numerous assassination attempts before 1968.', 'range', 1962, 1968, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000003c', 'Relations & Family', 'Coretta Scott (wife)', 'Married Coretta Scott in 1953; she was a trained concert singer who gave up her career; became a civil rights leader in her own right after his death.', 'range', 1953, 1968, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000003c', 'Relations & Family', 'Four children', 'Had four children with Coretta; was rarely home due to constant travel; called fatherhood the hardest part of his role.', 'range', 1955, 1968, '#db2777'),
  ('a0000000-0000-0000-0000-00000000003c', 'Relations & Family', 'Assassination in Memphis', 'Shot on the balcony of the Lorraine Motel in Memphis on 4 April 1968 while supporting striking sanitation workers.', 'point', 1968, NULL, '#f97316'),
  ('a0000000-0000-0000-0000-00000000003c', 'Activities', 'Nonviolent resistance philosophy', 'Synthesised Gandhi''s satyagraha with Christian theology and African American church tradition into a distinctive philosophy of nonviolent direct action.', 'range', 1955, 1968, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000003c', 'Activities', 'Anti-Vietnam War stance', 'Publicly opposed the Vietnam War from 1967; linked racial injustice and militarism; cost him mainstream support but he believed it was morally essential.', 'range', 1967, 1968, '#d97706'),
  ('a0000000-0000-0000-0000-00000000003c', 'Assets', 'Dexter Avenue Baptist Church', 'Served as pastor at Dexter Avenue Baptist Church in Montgomery; the church became a civil rights headquarters during the boycott.', 'range', 1954, 1960, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000003c', 'Items', '"Letter from Birmingham Jail"', 'Written on scraps of paper and smuggled out of jail in 1963; one of the great documents of American political philosophy, defending nonviolent resistance.', 'point', 1963, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000003d', 'Place & Travel', 'Brookline, Massachusetts', 'Born into a wealthy Irish-Catholic family; father was a SEC chairman and ambassador; grew up shuttling between Brookline, Hyannis Port, and Palm Beach.', 'range', 1917, 1940, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003d', 'Place & Travel', 'Pacific — PT-109', 'Served in the Solomon Islands; his torpedo boat PT-109 was rammed by a Japanese destroyer; he saved survivors by swimming hours through shark-infested waters.', 'range', 1943, 1944, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000003d', 'Place & Travel', 'Washington DC — Congress and Presidency', 'Served in Congress from Massachusetts; elected 35th President in 1960; the youngest elected president and the first Catholic.', 'range', 1947, 1963, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003d', 'Work & Education', 'Harvard and Stanford', 'Graduated Harvard 1940; thesis became the bestselling Why England Slept; briefly attended Stanford Business School.', 'range', 1936, 1941, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000003d', 'Work & Education', 'US Congress and Senate', 'Elected to House 1946; Senate 1952; won Pulitzer Prize for Profiles in Courage (1956) — later disputed as largely ghostwritten.', 'range', 1946, 1960, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003d', 'Work & Education', 'Cuban Missile Crisis', 'Navigated the 13-day Cuban Missile Crisis in October 1962 — the closest the world came to nuclear war; his naval blockade and back-channel diplomacy prevailed.', 'range', 1962, 1962, '#059669'),
  ('a0000000-0000-0000-0000-00000000003d', 'Work & Education', 'Space Race and Peace Corps', 'Challenged the nation to land on the Moon before 1970; established the Peace Corps; proposed the Nuclear Test Ban Treaty signed in 1963.', 'range', 1961, 1963, '#047857'),
  ('a0000000-0000-0000-0000-00000000003d', 'Health', 'Chronic pain and Addison''s disease', 'Suffered back pain from war injuries and Addison''s disease his entire adult life; took numerous medications including cortisone and amphetamines.', 'range', 1944, 1963, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000003d', 'Relations & Family', 'Jacqueline Bouvier (wife)', 'Married Jackie Bouvier in 1953; she became the most photographed woman in the world as First Lady; brought art and culture to the White House.', 'range', 1953, 1963, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000003d', 'Relations & Family', 'Multiple affairs', 'Affairs with Marilyn Monroe, Judith Exner (linked to the Mafia), and others were kept from the public during his lifetime.', 'range', 1960, 1963, '#db2777'),
  ('a0000000-0000-0000-0000-00000000003d', 'Relations & Family', 'Assassination in Dallas', 'Shot in Dallas motorcade on 22 November 1963; Lee Harvey Oswald charged; killed two days later; conspiracy theories persist.', 'point', 1963, NULL, '#f97316'),
  ('a0000000-0000-0000-0000-00000000003d', 'Activities', 'Sailing and PT boat history', 'Was a passionate sailor from childhood; his PT boat command was a formative experience; kept a sailboat at Hyannis Port.', 'range', 1930, 1963, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000003d', 'Assets', 'Kennedy family wealth', 'Born into one of America''s wealthiest families; his father''s fortune funded his political career; Kennedy donated his presidential salary to charity.', 'range', 1917, 1963, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000003d', 'Items', 'PT-109 tie clip', 'Wore a PT-109 tie clip throughout his presidency commemorating his wartime service; gave replicas as gifts to friends and staff.', 'range', 1961, 1963, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000003e', 'Place & Travel', 'Grantham, Lincolnshire', 'Born above her father''s grocery shop in Grantham; father Alfred Roberts was a Methodist lay preacher and alderman who shaped her values intensely.', 'range', 1925, 1943, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003e', 'Place & Travel', 'Oxford & London', 'Read chemistry at Somerville College Oxford; moved to London to become a barrister; married Denis Thatcher in 1951.', 'range', 1943, 1970, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003e', 'Place & Travel', 'Downing Street and world travel', 'Lived at 10 Downing Street 1979–90; travelled extensively meeting Reagan, Gorbachev, and Deng Xiaoping.', 'range', 1979, 1990, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000003e', 'Work & Education', 'Oxford chemistry and law', 'Studied chemistry under Dorothy Hodgkin; worked as a research chemist briefly; studied law and was called to the bar in 1953.', 'range', 1943, 1953, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000003e', 'Work & Education', 'Conservative MP and Minister', 'Elected MP for Finchley 1959; appointed Education Secretary 1970–74 under Heath; cut free school milk — dubbed "Thatcher the Milk Snatcher."', 'range', 1959, 1975, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003e', 'Work & Education', 'Conservative Party leader', 'Defeated Edward Heath for Conservative leadership in 1975; first woman to lead a major British party.', 'point', 1975, NULL, '#059669'),
  ('a0000000-0000-0000-0000-00000000003e', 'Work & Education', 'Prime Minister — Thatcherism', 'Prime Minister 1979–90; privatised British Telecom, BP, British Gas; defeated the miners'' strike; transformed British economic policy.', 'range', 1979, 1990, '#047857'),
  ('a0000000-0000-0000-0000-00000000003e', 'Work & Education', 'Falklands War', 'Ordered the task force to retake the Falkland Islands in 1982 after Argentina''s invasion; the victory transformed her political standing.', 'range', 1982, 1982, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003e', 'Health', 'Resignation and dementia', 'Resigned in November 1990 after Cabinet revolt over the poll tax; suffered from vascular dementia in her final decade; died April 2013.', 'range', 1990, 2013, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000003e', 'Relations & Family', 'Denis Thatcher (husband)', 'Married businessman Denis Thatcher in 1951; he was a devoted and discreet supportive spouse; twins Mark and Carol born 1953.', 'range', 1951, 2013, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000003e', 'Relations & Family', 'Brighton hotel bombing', 'The IRA bombed her Brighton hotel during the Conservative conference in 1984; she narrowly escaped and gave her conference speech as planned.', 'point', 1984, NULL, '#db2777'),
  ('a0000000-0000-0000-0000-00000000003e', 'Activities', 'Oratory and debating', 'Her voice was deliberately lowered on advice; was a formidable parliamentary debater; gave over 1,000 speeches as Prime Minister.', 'range', 1975, 1990, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000003e', 'Activities', 'Reading and self-improvement', 'Read voraciously in chemistry, economics, and philosophy; studied Hayek and Friedman; her handbag became a symbol of her dominant style.', 'range', 1950, 1990, '#d97706'),
  ('a0000000-0000-0000-0000-00000000003e', 'Assets', '10 Downing Street and Dulwich home', 'Lived at Downing Street for 11 years; retired to Dulwich; received a baronetcy as Baroness Thatcher of Kesteven.', 'range', 1979, 2013, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000003e', 'Items', 'The handbag', 'Her black leather handbag was so iconic that "handbagging" entered political vocabulary meaning to assault someone verbally; auctioned for £25,000.', 'range', 1979, 1990, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000003f', 'Place & Travel', 'Privolnoye, Stavropol, Russia', 'Born in a peasant village; both sets of grandparents were arrested in Stalin''s purges; began working on a combine harvester aged 13.', 'range', 1931, 1950, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003f', 'Place & Travel', 'Moscow (university and career)', 'Moved to Moscow State University in 1950; worked his way up through Stavropol party machinery then Moscow; moved permanently in 1978.', 'range', 1950, 2022, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003f', 'Place & Travel', 'Foreign travel — diplomatic', 'Made transformative foreign visits including to London in 1984 where Thatcher said he was someone she "could do business with"; visited Berlin in 1990.', 'range', 1984, 1991, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000003f', 'Work & Education', 'Moscow State University — law', 'Studied law at MGU; joined the Communist Party in 1952; his intellect and ambition marked him out among provincial party apparatchiks.', 'range', 1950, 1955, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000003f', 'Work & Education', 'Communist Party rise', 'Rose through the Stavropol regional party; became party first secretary for Stavropol in 1970; promoted to Moscow by Andropov in 1978.', 'range', 1955, 1985, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003f', 'Work & Education', 'General Secretary of the Communist Party', 'Became General Secretary in March 1985; the youngest man to hold the post; immediately began policy reforms.', 'point', 1985, NULL, '#059669'),
  ('a0000000-0000-0000-0000-00000000003f', 'Work & Education', 'Glasnost and Perestroika', 'Launched glasnost (openness) and perestroika (restructuring); freed political prisoners; withdrew from Afghanistan; allowed free elections in Eastern Europe.', 'range', 1986, 1991, '#047857'),
  ('a0000000-0000-0000-0000-00000000003f', 'Work & Education', 'Dissolution of the USSR', 'The policies he unleashed led to the dissolution of the Soviet Union on 25 December 1991; he resigned as Soviet president on the same day.', 'point', 1991, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003f', 'Health', 'Coup attempt 1991', 'Held under house arrest in Crimea during the August 1991 coup attempt by hardliners; the coup''s failure accelerated the USSR''s dissolution.', 'point', 1991, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000003f', 'Relations & Family', 'Raisa Titarenko (wife)', 'Married Raisa Titarenko in 1953 while both were students at MGU; she died of leukaemia in 1999; her death devastated him visibly.', 'range', 1953, 1999, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000003f', 'Relations & Family', 'Relationship with Boris Yeltsin', 'Yeltsin was Gorbachev''s rival whose popularity eclipsed his; Yeltsin''s election as Russian president in 1991 ended Gorbachev''s political relevance.', 'range', 1987, 1991, '#db2777'),
  ('a0000000-0000-0000-0000-00000000003f', 'Activities', 'Nobel Peace Prize 1990', 'Awarded the Nobel Peace Prize in 1990 for his role in ending the Cold War; unable to attend the ceremony due to political pressures.', 'point', 1990, NULL, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000003f', 'Activities', 'Gorbachev Foundation and advocacy', 'Founded the Gorbachev Foundation after 1991; advocated for nuclear disarmament and global environmental policy; ran unsuccessfully for president in 1996.', 'range', 1991, 2022, '#d97706'),
  ('a0000000-0000-0000-0000-00000000003f', 'Assets', 'Pizza Hut advertisement', 'Appeared in a Pizza Hut television advertisement in 1997 — one of the most surprising celebrity endorsements in history; earned a reported $1 million.', 'point', 1997, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000003f', 'Items', 'Birthmark (port-wine stain)', 'His prominent cranial birthmark became one of the most recognised features of any world leader; he never disguised it despite pressure to do so.', 'range', 1931, 2022, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000040', 'Place & Travel', 'Allahabad, India', 'Born into a wealthy Kashmiri Brahmin family; father Motilal was a prominent lawyer; grew up in the grand Anand Bhavan estate.', 'range', 1889, 1905, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000040', 'Place & Travel', 'England — Harrow and Cambridge', 'Attended Harrow School then Trinity College Cambridge; read natural sciences; called to the bar at Inner Temple; returned to India in 1912.', 'range', 1905, 1912, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000040', 'Place & Travel', 'Across India and Geneva', 'Travelled extensively across India meeting the rural poor; briefly attended the Geneva disarmament conference; his journeys shaped his democratic socialism.', 'range', 1920, 1947, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000040', 'Work & Education', 'Cambridge and law', 'Read natural sciences at Cambridge; switched to law; became involved in Fabian socialism; transformed from a privileged anglophile into a nationalist.', 'range', 1907, 1912, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000040', 'Work & Education', 'Indian National Congress leadership', 'Joined Gandhi''s Non-Cooperation Movement in 1920; arrested nine times totalling over 9 years in prison; became Congress president five times.', 'range', 1920, 1947, '#10b981'),
  ('a0000000-0000-0000-0000-000000000040', 'Work & Education', 'The Discovery of India', 'Wrote his masterwork The Discovery of India in prison in 1944; a meditation on Indian history and civilisation that became a founding text of Indian identity.', 'point', 1944, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000040', 'Work & Education', 'First Prime Minister of India', 'Became independent India''s first Prime Minister on 15 August 1947; served until his death in 1964 — the longest-serving Indian PM.', 'range', 1947, 1964, '#047857'),
  ('a0000000-0000-0000-0000-000000000040', 'Work & Education', 'Non-Aligned Movement', 'Co-founded the Non-Aligned Movement in 1961 with Tito and Nasser; kept India neutral between the US and USSR during the Cold War.', 'range', 1955, 1964, '#10b981'),
  ('a0000000-0000-0000-0000-000000000040', 'Health', 'Stroke and death in office', 'Suffered a stroke in January 1964; died in office in May 1964 aged 74; his death marked the end of India''s founding generation of leaders.', 'range', 1964, 1964, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000040', 'Relations & Family', 'Kamala Kaul (wife)', 'Married Kamala Kaul in 1916; she was a gentle, spiritually-minded woman who found his political life difficult; died of tuberculosis in 1936.', 'range', 1916, 1936, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000040', 'Relations & Family', 'Indira Gandhi (daughter)', 'His daughter Indira became his political heir and eventually Prime Minister; their close relationship shaped India''s democratic dynasty.', 'range', 1917, 1964, '#db2777'),
  ('a0000000-0000-0000-0000-000000000040', 'Activities', 'Nine years in prison', 'Spent over 9 years in British prisons across 18 stints; used the time to write prolifically — his prison letters to Indira became Glimpses of World History.', 'range', 1921, 1945, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000040', 'Activities', 'Five Year Plans and industrial policy', 'Pursued state-directed industrialisation through Five Year Plans; established IITs and IIMs that became foundations of Indian technological development.', 'range', 1951, 1964, '#d97706'),
  ('a0000000-0000-0000-0000-000000000040', 'Assets', 'Teen Murti Bhavan', 'Lived at Teen Murti Bhavan in New Delhi as Prime Minister; preserved as a memorial; had roses delivered to his room every day until his death.', 'range', 1947, 1964, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000040', 'Items', 'Rose in the buttonhole', 'Always wore a fresh red rose in his buttonhole; the rose became as iconic as his sherwanis; even wore one in prison.', 'range', 1920, 1964, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000041', 'Place & Travel', 'Salonika (now Thessaloniki, Greece)', 'Born Mustafa in Salonika; father was a customs officer; his mother Zübeyde was a pious Muslim who wanted him to attend religious school.', 'range', 1881, 1899, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000041', 'Place & Travel', 'Ottoman military schools', 'Studied at military schools in Salonika, Monastir, and the Ottoman War Academy in Istanbul; graduated with distinction in 1905.', 'range', 1899, 1905, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000041', 'Place & Travel', 'Gallipoli and Anatolia', 'Won fame defending Gallipoli in 1915; organised the Anatolian resistance movement from Ankara after the Ottoman defeat; built the new Turkey there.', 'range', 1915, 1938, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000041', 'Work & Education', 'Ottoman War Academy — staff officer', 'Graduated among the top officers of his class; served in Libya and the Balkans; rose to prominence at Gallipoli.', 'range', 1902, 1914, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000041', 'Work & Education', 'Gallipoli campaign victory', 'As commander at Gallipoli in 1915, organised the defence that repelled the Allied invasion; his order "I am not ordering you to attack, I am ordering you to die" became legendary.', 'range', 1915, 1916, '#10b981'),
  ('a0000000-0000-0000-0000-000000000041', 'Work & Education', 'Turkish War of Independence', 'Led the nationalist resistance after Ottoman defeat; defeated Greek, Armenian, and Allied forces; established Ankara as capital of the new Turkish state.', 'range', 1919, 1923, '#059669'),
  ('a0000000-0000-0000-0000-000000000041', 'Work & Education', 'President of Turkey and reforms', 'First President from 1923–38; abolished the caliphate, introduced the Latin alphabet, secular law, and women''s suffrage; transformed Turkey into a modern state.', 'range', 1923, 1938, '#047857'),
  ('a0000000-0000-0000-0000-000000000041', 'Work & Education', 'Latin alphabet reform', 'Personally toured Turkey in 1928 teaching the new Latin alphabet from a blackboard; literacy programmes raised the adult literacy rate dramatically.', 'range', 1928, 1935, '#10b981'),
  ('a0000000-0000-0000-0000-000000000041', 'Health', 'Cirrhosis of the liver', 'Was a heavy drinker of raki throughout his life; died of cirrhosis in November 1938 aged 57; his death was mourned as a national catastrophe.', 'range', 1930, 1938, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000041', 'Relations & Family', 'Latife Uşaki (wife)', 'Married educated and independent Latife Uşaki in 1923; divorced in 1925; she was the only woman he married; the divorce was never fully explained.', 'range', 1923, 1925, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000041', 'Activities', 'Surname law — Atatürk', 'When Turkey adopted surnames in 1934 the parliament gave him the name Atatürk meaning "Father of the Turks" — the name no other Turkish person can use.', 'point', 1934, NULL, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000041', 'Activities', 'Women''s rights reforms', 'Gave women full voting rights in 1934 — before France, Italy, or Switzerland; appointed women judges and encouraged women in professions.', 'range', 1930, 1938, '#d97706'),
  ('a0000000-0000-0000-0000-000000000041', 'Assets', 'Çankaya presidential palace', 'Built and lived at Çankaya Köşkü in Ankara; it became the official Turkish presidential residence and remains so today.', 'range', 1921, 1938, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000041', 'Items', 'European-style hat', 'His introduction of Western hats (and ban on the fez) in 1925 was a deliberate symbol of modernisation; he travelled Turkey modelling the new hat himself.', 'point', 1925, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000044', 'Place & Travel', 'Domrémy, Duchy of Bar', 'Born in the village of Domrémy in eastern France; her village was loyal to France during the Hundred Years'' War; grew up in a pious farming family.', 'range', 1412, 1428, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000044', 'Place & Travel', 'Chinon & Orléans', 'Travelled to Chinon to meet the Dauphin; received armour and troops; lifted the Siege of Orléans in nine days in May 1429.', 'range', 1429, 1429, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000044', 'Place & Travel', 'Rouen — trial and execution', 'Captured by Burgundians in 1430; sold to the English; tried and burned at the stake in Rouen on 30 May 1431; ashes thrown in the Seine.', 'range', 1430, 1431, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000044', 'Work & Education', 'Receiving visions', 'From age 13 claimed to hear the voices of Saints Michael, Catherine, and Margaret instructing her to support the Dauphin and drive out the English.', 'range', 1425, 1431, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000044', 'Work & Education', 'Relief of Orléans', 'Led the French relief of Orléans in April–May 1429; the victory ended a months-long English siege and turned the tide of the Hundred Years'' War.', 'range', 1429, 1429, '#10b981'),
  ('a0000000-0000-0000-0000-000000000044', 'Work & Education', 'Loire campaign and coronation', 'Led a series of victories along the Loire; the Dauphin was crowned Charles VII at Reims Cathedral on 17 July 1429 fulfilling her mission.', 'range', 1429, 1429, '#059669'),
  ('a0000000-0000-0000-0000-000000000044', 'Work & Education', 'Trial and posthumous retrial', 'Tried by an English-controlled ecclesiastical court and convicted of heresy in 1431; posthumous retrial in 1456 declared her innocent; canonised in 1920.', 'point', 1431, NULL, '#047857'),
  ('a0000000-0000-0000-0000-000000000044', 'Health', 'Captured at Compiègne', 'Wounded and captured at Compiègne in May 1430 while covering the retreat of her troops; the Burgundians sold her to the English for 10,000 livres.', 'point', 1430, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000044', 'Relations & Family', 'Charles VII of France', 'Her relationship with the Dauphin was complex; he benefited enormously from her victories but made no serious effort to ransom her after her capture.', 'range', 1429, 1431, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000044', 'Activities', 'Military command', 'Was given command of an army despite being a 17-year-old peasant girl; wore full armour and carried a banner (not a sword); was wounded twice.', 'range', 1429, 1430, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000044', 'Items', 'White armour', 'Received specially made full white plate armour from Charles VII; after her execution her armour was preserved as a relic in several French towns.', 'range', 1429, 1431, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000045', 'Place & Travel', 'Kensington Palace, London', 'Born at Kensington Palace; her father died when she was 8 months old; raised under strict Kensington System rules by her mother and her controller Conroy.', 'range', 1819, 1837, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000045', 'Place & Travel', 'Buckingham Palace & Windsor Castle', 'Moved to Buckingham Palace immediately on accession; Windsor Castle became her favourite residence after Albert''s death; also loved Balmoral and Osborne.', 'range', 1837, 1901, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000045', 'Place & Travel', 'India — Empress', 'Never actually visited India despite becoming Empress of India in 1876; learned Urdu from her Indian servant Abdul Karim.', 'range', 1876, 1901, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000045', 'Work & Education', 'Tutored as heir', 'Educated by her mother and tutors in languages (French, German, Italian), music, and drawing; had no knowledge she would be queen until her teens.', 'range', 1819, 1837, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000045', 'Work & Education', 'Accession at 18', 'Became queen on 20 June 1837 aged 18; her first act was to ask for an hour alone; dismissed Conroy and escaped her mother''s control.', 'point', 1837, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000045', 'Work & Education', 'Constitutional monarch', 'Reigned through nine prime ministers including Disraeli and Gladstone; wielded real influence despite the shift to constitutional monarchy.', 'range', 1837, 1901, '#059669'),
  ('a0000000-0000-0000-0000-000000000045', 'Work & Education', 'Empress of India', 'Declared Empress of India in 1876 at Disraeli''s instigation; India was central to her imperial identity; she corresponded directly with Indian princes.', 'range', 1876, 1901, '#047857'),
  ('a0000000-0000-0000-0000-000000000045', 'Health', 'Long widowhood depression', 'Devastated by Albert''s death in 1861; withdrew from public duties for over a decade; called "Mrs Brown" by the press who suspected an affair with her gillie.', 'range', 1861, 1880, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000045', 'Relations & Family', 'Prince Albert of Saxe-Coburg (husband)', 'Married her cousin Albert in 1840; theirs was a love match; he was her most trusted adviser; his death in 1861 left her devastated for the rest of her life.', 'range', 1840, 1861, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000045', 'Relations & Family', 'Nine children — grandmother of Europe', 'Had nine children with Albert; their marriages spread throughout European royal families; she was grandmother or great-grandmother to most European monarchs.', 'range', 1840, 1901, '#db2777'),
  ('a0000000-0000-0000-0000-000000000045', 'Activities', 'Keeping journals', 'Kept a detailed diary from the age of 13 until days before her death; over 122 volumes spanning 67 years; her daughter Beatrice destroyed or edited much of it.', 'range', 1832, 1901, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000045', 'Activities', 'Painting and drawing', 'Was a talented painter and illustrator; produced hundreds of watercolours; sent personal sketches as gifts; was tutored by Edwin Landseer.', 'range', 1830, 1880, '#d97706'),
  ('a0000000-0000-0000-0000-000000000045', 'Assets', 'Balmoral and Osborne estates', 'Purchased Balmoral in Scotland and Osborne House on the Isle of Wight as private royal estates; both became beloved family retreats.', 'range', 1844, 1901, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000045', 'Items', 'Widow''s weeds', 'Wore black mourning dress every day for 40 years after Albert''s death in 1861; this extended mourning became a symbol of Victorian widow culture.', 'range', 1861, 1901, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000046', 'Place & Travel', 'Saint-Germain-en-Laye', 'Born at Saint-Germain-en-Laye; his father Louis XIII died when he was 4; his mother Anne of Austria and Cardinal Mazarin ruled during his minority.', 'range', 1638, 1661, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000046', 'Place & Travel', 'Versailles', 'Built the Palace of Versailles and moved the entire French court there in 1682; Versailles became the template for European royal palaces.', 'range', 1661, 1715, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000046', 'Place & Travel', 'Military campaigns across Europe', 'Led France into numerous wars — the War of Devolution, the Franco-Dutch War, the Nine Years'' War, and the War of Spanish Succession.', 'range', 1667, 1713, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000046', 'Work & Education', 'Cardinal Mazarin''s tutoring', 'Educated by Mazarin; the Fronde rebellion during his childhood left him with a lifelong distrust of the nobility and a determination to centralise power.', 'range', 1643, 1661, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000046', 'Work & Education', 'Personal rule begins 1661', 'After Mazarin''s death in 1661 declared he would be his own first minister; "L''état, c''est moi" — the state is me — encapsulates his theory of kingship.', 'point', 1661, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000046', 'Work & Education', 'Building Versailles', 'Commissioned the expansion of Versailles in 1661; the final palace with 2,300 rooms and the Hall of Mirrors became the most imitated building in history.', 'range', 1661, 1710, '#059669'),
  ('a0000000-0000-0000-0000-000000000046', 'Work & Education', 'Revocation of Edict of Nantes', 'Revoked the Edict of Nantes in 1685, ending Protestant rights; over 200,000 Huguenots fled France, draining it of skilled craftsmen and merchants.', 'point', 1685, NULL, '#047857'),
  ('a0000000-0000-0000-0000-000000000046', 'Work & Education', 'Patronage of arts and culture', 'Established the French Academy, the Academy of Sciences, and the Comédie-Française; patronised Molière, Racine, and Lully; made Paris the cultural capital of Europe.', 'range', 1660, 1715, '#10b981'),
  ('a0000000-0000-0000-0000-000000000046', 'Health', 'Anal fistula operation', 'Suffered from an anal fistula; his surgeon performed an operation in 1686; the recovery inspired a fashion for recovery convalescence across France.', 'point', 1686, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000046', 'Relations & Family', 'Marie-Thérèse of Austria (queen)', 'Married Marie-Thérèse in 1660 as part of the Treaty of the Pyrenees; she bore him six children but he was openly unfaithful.', 'range', 1660, 1683, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000046', 'Relations & Family', 'Marquise de Maintenon (morganatic wife)', 'Had a secret morganatic marriage to Françoise d''Aubigné, Marquise de Maintenon after his queen died; she had enormous influence over his later policies.', 'range', 1683, 1715, '#db2777'),
  ('a0000000-0000-0000-0000-000000000046', 'Activities', 'Ballet dancing', 'Was an accomplished ballet dancer who performed publicly in court ballets; took the role of the Sun King Apollo at 14; named himself Le Roi Soleil.', 'range', 1651, 1670, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000046', 'Assets', 'Palace of Versailles', 'Versailles cost the equivalent of billions in today''s money; housed 10,000 courtiers; became the seat of French government until 1789.', 'range', 1682, 1715, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000046', 'Items', 'High-heeled shoes', 'Wore high-heeled shoes to appear taller — he was only 5''4"; his heels were painted with battle scenes; red-heeled shoes became a noble fashion.', 'range', 1661, 1715, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000048', 'Place & Travel', 'Dorchester County, Maryland', 'Born enslaved; real name Araminta Ross; given the name Harriet after her mother; her father Ben Ross was a skilled timber worker.', 'range', 1822, 1849, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000048', 'Place & Travel', 'Underground Railroad routes', 'Escaped north to Philadelphia in 1849; returned south 13 times over ten years conducting approximately 70 enslaved people to freedom.', 'range', 1849, 1860, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000048', 'Place & Travel', 'Auburn, New York', 'Settled in Auburn; bought a home near her parents; used it as a station on the Underground Railroad; it is now a museum.', 'range', 1859, 1913, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000048', 'Work & Education', 'Enslaved labour', 'Performed brutal field and domestic labour from childhood; at 12 was struck in the head by an iron weight thrown at another enslaved person — causing lifelong seizures.', 'range', 1828, 1849, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000048', 'Work & Education', 'Underground Railroad conductor', 'Known as "Moses" by those she led to freedom; used the North Star, the Chestnut Oak, and network of sympathisers; never lost a "passenger."', 'range', 1849, 1860, '#10b981'),
  ('a0000000-0000-0000-0000-000000000048', 'Work & Education', 'Civil War — spy and nurse', 'Served as a spy, scout, and nurse for the Union Army; in 1863 led the Combahee River Raid freeing over 700 enslaved people.', 'range', 1862, 1865, '#059669'),
  ('a0000000-0000-0000-0000-000000000048', 'Work & Education', 'Women''s suffrage activism', 'After the war campaigned for women''s suffrage alongside Susan B. Anthony; spoke at the first National Association of Colored Women meeting in 1896.', 'range', 1880, 1913, '#047857'),
  ('a0000000-0000-0000-0000-000000000048', 'Health', 'Narcoleptic seizures', 'The head injury from childhood caused sudden narcoleptic seizures throughout her life; she fell asleep unexpectedly in dangerous situations during rescues.', 'range', 1834, 1913, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000048', 'Health', 'Brain surgery', 'Underwent brain surgery at Boston''s Massachusetts General Hospital aged approximately 70 without anaesthesia to relieve pressure from her old injury.', 'point', 1898, NULL, '#dc2626'),
  ('a0000000-0000-0000-0000-000000000048', 'Relations & Family', 'John Tubman (first husband)', 'Married free Black man John Tubman in 1844; he refused to escape north with her and married another woman after her escape; she reclaimed her freedom alone.', 'range', 1844, 1849, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000048', 'Relations & Family', 'Nelson Davis (second husband)', 'Married Civil War veteran Nelson Davis in 1869; he was 22 years her junior; they adopted a baby daughter Eva.', 'range', 1869, 1888, '#db2777'),
  ('a0000000-0000-0000-0000-000000000048', 'Activities', 'Harriet Tubman Home for the Aged', 'Established a home for elderly African Americans in Auburn; donated the property to her church; it opened officially in 1908.', 'range', 1896, 1913, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000048', 'Assets', 'US $20 bill', 'In 2016 it was announced she would replace Andrew Jackson on the US $20 bill; implementation delayed but confirmed as of 2023.', 'point', 2016, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000048', 'Items', 'North Star navigation', 'Used the North Star as her primary navigation tool during night escapes; taught freedom seekers to follow the star and "follow the drinking gourd."', 'range', 1849, 1860, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000004d', 'Place & Travel', 'Rome', 'Born Gaius Octavius in Rome; his great-uncle Julius Caesar adopted him posthumously; grew up in Rome and Velitrae.', 'range', -63, -44, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000004d', 'Place & Travel', 'Greece, Egypt & East', 'Studied in Greece when Caesar was assassinated; pursued the assassins at Philippi; defeated Antony and Cleopatra in Egypt.', 'range', -44, -27, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000004d', 'Place & Travel', 'Rome (Principate)', 'Established Rome as the magnificent capital of the empire; lived simply on the Palatine Hill despite ruling the known world.', 'range', -27, 14, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000004d', 'Work & Education', 'Caesar''s heir and Second Triumvirate', 'Named Caesar''s heir; formed the Second Triumvirate with Antony and Lepidus; had Cicero executed; defeated the assassins at Philippi in -42.', 'range', -44, -36, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000004d', 'Work & Education', 'Civil war against Antony', 'Defeated Mark Antony and Cleopatra at the Battle of Actium in -31; conquered Egypt; became undisputed master of the Roman world.', 'range', -36, -27, '#10b981'),
  ('a0000000-0000-0000-0000-00000000004d', 'Work & Education', 'Principate — first Roman Emperor', 'In -27 accepted the title Augustus and the Principate; maintained republican forms while exercising absolute power; inaugurated the Pax Romana.', 'range', -27, 14, '#059669'),
  ('a0000000-0000-0000-0000-00000000004d', 'Work & Education', 'Administrative reforms', 'Created the Praetorian Guard, a professional army, a navy, a postal system, and provincial administration; transformed Rome from brick to marble.', 'range', -27, 14, '#047857'),
  ('a0000000-0000-0000-0000-00000000004d', 'Health', 'Chronic ill health', 'Was chronically ill throughout his life; nearly died several times; his doctors'' meticulous attention to his diet and lifestyle kept him alive to 76.', 'range', -40, 14, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000004d', 'Relations & Family', 'Livia Drusilla (wife)', 'Married Livia in -38 despite her being pregnant by another man; she was his devoted companion for 51 years and probably the most powerful woman in Rome.', 'range', -38, 14, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000004d', 'Relations & Family', 'Succession crisis', 'Had no son; outlived his intended heirs Marcellus, Gaius, and Lucius; eventually adopted Tiberius as his successor reluctantly.', 'range', -23, 14, '#db2777'),
  ('a0000000-0000-0000-0000-00000000004d', 'Activities', 'Literary patronage — Golden Age', 'Patronised Virgil, Horace, Ovid, and Livy; the Augustan Age was the golden age of Latin literature; Virgil''s Aeneid was his epic justification.', 'range', -27, 8, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000004d', 'Assets', 'Roman Empire treasury', 'Controlled the revenues of the entire Roman Empire; used his personal wealth to fund the army, construction projects, and grain distributions.', 'range', -27, 14, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000004d', 'Items', 'Gemma Augustea cameo', 'His image on the Gemma Augustea cameo — showing him as Jupiter — is the finest surviving Roman cameo and defines the visual image of Augustus.', 'range', -27, 14, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000004f', 'Place & Travel', 'Pannonia (modern Hungary)', 'Born in the Hunnic heartland of Pannonia; grew up in the royal family of the Hunnic Empire spanning from the Rhine to the Caspian Sea.', 'range', 406, 434, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000004f', 'Place & Travel', 'Campaigns across Europe', 'Launched raids into the Eastern Roman Empire, the Balkans, Gaul (France), and northern Italy; left a trail of devastation across the continent.', 'range', 434, 453, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000004f', 'Work & Education', 'Hostage at Roman court', 'Spent time as a royal hostage at the Roman court, learning Latin and Roman military tactics — knowledge he would later use against Rome.', 'range', 410, 420, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000004f', 'Work & Education', 'Co-ruler with Bleda', 'Ruled jointly with his brother Bleda from 434; the brothers negotiated the Treaty of Margus extracting tribute from Constantinople.', 'range', 434, 445, '#10b981'),
  ('a0000000-0000-0000-0000-00000000004f', 'Work & Education', 'Sole ruler — Bleda murdered', 'Had his brother Bleda killed in 445; ruled the Hunnic Empire alone; launched devastating invasion of the Eastern Empire in 447.', 'range', 445, 453, '#059669'),
  ('a0000000-0000-0000-0000-00000000004f', 'Work & Education', 'Invasion of Gaul and Italy', 'Invaded Gaul in 451; defeated at the Catalaunian Plains; invaded Italy in 452; sacked Milan and Aquileia; was persuaded to spare Rome by Pope Leo I.', 'range', 451, 452, '#047857'),
  ('a0000000-0000-0000-0000-00000000004f', 'Health', 'Mysterious death', 'Died on his wedding night to a new wife (Ildico) in 453; possibly of a ruptured artery or internal haemorrhage exacerbated by heavy drinking.', 'point', 453, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000004f', 'Relations & Family', 'Ildico (final wife)', 'Married Ildico as one of many wives on the night of his mysterious death; found dead with her weeping beside him; foul play was suspected but never proven.', 'point', 453, NULL, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000004f', 'Activities', 'Diplomacy and tribute extraction', 'Was a skilled diplomat who extracted enormous tributes from Constantinople; played Roman factions against each other with great cunning.', 'range', 434, 453, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000004f', 'Assets', 'Hunnic Empire', 'Ruled an empire stretching from the Rhine to the Ural River; extracted tribute equivalent to thousands of pounds of gold annually from Constantinople.', 'range', 445, 453, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000004f', 'Items', 'The "Sword of Attila"', 'Claimed to possess a sacred "Sword of Mars" that gave him divine right to rule the world; probably an ancient scimitar found by a shepherd.', 'range', 445, 453, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000050', 'Place & Travel', 'Tikrit, Iraq', 'Born in Tikrit (the same city as Saddam Hussein) to a Kurdish family; father was the governor of Baalbek; grew up in Damascus.', 'range', 1137, 1164, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000050', 'Place & Travel', 'Egypt', 'Went to Egypt with his uncle Shirkuh in 1163 to intervene in the Fatimid succession; became Vizier of Egypt in 1169; abolished the Fatimid Caliphate.', 'range', 1163, 1174, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000050', 'Place & Travel', 'Syria, Palestine & Third Crusade', 'Unified Egypt and Syria under his rule; captured Jerusalem in 1187; fought the Third Crusade against Richard I of England across the Holy Land.', 'range', 1174, 1193, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000050', 'Work & Education', 'Military service under Nur ad-Din', 'Trained as a military commander under Nur ad-Din; learned governance and strategy; his administrative abilities matched his military prowess.', 'range', 1152, 1174, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000050', 'Work & Education', 'Sultan of Egypt and Syria', 'Became Sultan of Egypt in 1174 after Nur ad-Din''s death; unified Egypt and Syria; the first Ayyubid sultan.', 'range', 1174, 1187, '#10b981'),
  ('a0000000-0000-0000-0000-000000000050', 'Work & Education', 'Battle of Hattin and Jerusalem', 'Destroyed the Crusader army at Hattin in 1187; captured Jerusalem on 2 October 1187; allowed Christian inhabitants to leave unharmed — contrasting with the 1099 Crusader massacre.', 'range', 1187, 1187, '#059669'),
  ('a0000000-0000-0000-0000-000000000050', 'Work & Education', 'Third Crusade stalemate', 'Fought Richard I of England to a stalemate in 1191–92; the Treaty of Jaffa allowed Christian pilgrims access to Jerusalem while Saladin kept the city.', 'range', 1191, 1192, '#047857'),
  ('a0000000-0000-0000-0000-000000000050', 'Health', 'Death from fever', 'Died in Damascus in March 1193 from typhoid fever aged 55–56; had given away so much in charity that his treasury held only a single gold coin.', 'point', 1193, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000050', 'Relations & Family', 'Multiple wives', 'Had multiple wives as was customary; sons al-Afdal and al-Aziz inherited his empire; he divided it among his sons and family rather than keeping it unified.', 'range', 1165, 1193, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000050', 'Activities', 'Chivalric reputation', 'Renowned across both Muslim and Christian worlds for chivalry; sent his personal physician and food to Richard I when the king fell ill during the Crusade.', 'range', 1187, 1193, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000050', 'Activities', 'Construction in Cairo', 'Built the Cairo Citadel which dominates the city skyline to this day; expanded Al-Azhar University; established hospitals and schools across Egypt.', 'range', 1176, 1193, '#d97706'),
  ('a0000000-0000-0000-0000-000000000050', 'Assets', 'Ayyubid Empire', 'At his peak ruled an empire from Egypt to Mesopotamia; but died almost penniless having given his wealth to charity and his subjects.', 'range', 1174, 1193, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000050', 'Items', 'Damascus tomb', 'His mausoleum in Damascus is a pilgrimage site; Kaiser Wilhelm II visited in 1898 and donated a marble cenotaph; a second original wooden coffin is nearby.', 'range', 1193, 1193, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000032', 'Place & Travel', 'Gori, Georgia', 'Born in a poor cobbler''s family in Gori; pockmarked from smallpox; lame from a childhood carriage accident; attended the Tiflis Theological Seminary.', 'range', 1878, 1899, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000032', 'Place & Travel', 'Siberian exile and escape', 'Arrested and exiled to Siberia seven times; escaped six times; the remote Siberian postings gave him time to study Marx and organise.', 'range', 1902, 1917, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000032', 'Place & Travel', 'Moscow — Kremlin', 'Moved to Moscow after the revolution; the Kremlin became his headquarters; rarely left Moscow except for vacations at Black Sea dachas.', 'range', 1917, 1953, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000032', 'Work & Education', 'Theological seminary — expelled', 'Entered the Orthodox seminary as a scholarship student; discovered Marxist literature; expelled for missing exams in 1899; became a full-time revolutionary.', 'range', 1894, 1899, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000032', 'Work & Education', 'Bolshevik party organiser and bank robbery', 'Organised bank robberies (expropriations) to fund the Bolshevik party; the 1907 Tiflis bank robbery netted 341,000 rubles; arrested multiple times.', 'range', 1901, 1917, '#10b981'),
  ('a0000000-0000-0000-0000-000000000032', 'Work & Education', 'Commissar and Civil War', 'As Commissar of Nationalities helped win the Civil War; his brutal methods at Tsaritsyn brought him into conflict with Trotsky.', 'range', 1917, 1922, '#059669'),
  ('a0000000-0000-0000-0000-000000000032', 'Work & Education', 'General Secretary and rise to power', 'Became General Secretary in 1922; used the position to place loyalists everywhere; outmanoeuvred Trotsky, Zinoviev, and Bukharin.', 'range', 1922, 1929, '#047857'),
  ('a0000000-0000-0000-0000-000000000032', 'Work & Education', 'Collectivisation, purges and WWII', 'Forced collectivisation killed millions in the Ukraine famine; the Great Terror purged the Red Army; then led the USSR to victory over Nazi Germany.', 'range', 1929, 1953, '#10b981'),
  ('a0000000-0000-0000-0000-000000000032', 'Health', 'Paranoia and stroke', 'Became increasingly paranoid in his final years; planning a new wave of purges; died of a cerebral haemorrhage in March 1953 after lying unattended.', 'range', 1948, 1953, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000032', 'Relations & Family', 'Nadezhda Alliluyeva (second wife)', 'Married Nadezhda Alliluyeva in 1919; she shot herself in 1932 after a public argument with Stalin; her suicide was covered up.', 'range', 1919, 1932, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000032', 'Relations & Family', 'Son Yakov and Vasily', 'His eldest son Yakov was captured by the Germans in 1941; Stalin refused a prisoner exchange; Yakov died at Sachsenhausen.', 'range', 1941, 1953, '#db2777'),
  ('a0000000-0000-0000-0000-000000000032', 'Activities', 'Cult of personality', 'Orchestrated an unprecedented cult of personality; renamed cities after himself (Stalingrad, Stalinabad); approved every newspaper and poster image of himself.', 'range', 1929, 1953, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000032', 'Assets', 'Multiple dachas', 'Had over 20 dachas (country houses) across the USSR; his Blizhnyaya dacha outside Moscow was his preferred working residence.', 'range', 1930, 1953, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000032', 'Items', 'Pipe', 'His pipe was as iconic as his moustache; he rarely smoked it in photographs but it was part of the carefully cultivated image of the calm, paternal leader.', 'range', 1920, 1953, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000033', 'Place & Travel', 'Shaoshan, Hunan Province', 'Born in a peasant farming family; his father was a prosperous grain dealer; rebelled against his authoritarian father from youth.', 'range', 1893, 1911, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000033', 'Place & Travel', 'Changsha & Beijing', 'Studied at Changsha teachers college; worked as a library assistant at Peking University where he discovered Marxism.', 'range', 1911, 1921, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000033', 'Place & Travel', 'The Long March', 'The 8,000-mile Long March retreat of 1934–35 from Jiangxi to Yan''an established his leadership of the Communist Party and became founding mythology.', 'range', 1934, 1935, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000033', 'Work & Education', 'Founding the Chinese Communist Party', 'Was one of the founding members of the CCP in 1921; led its military wing through guerrilla war against the Nationalists and Japan.', 'range', 1921, 1949, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000033', 'Work & Education', 'Founding the People''s Republic', 'Proclaimed the People''s Republic of China from the Gate of Heavenly Peace on 1 October 1949; "China has stood up."', 'point', 1949, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000033', 'Work & Education', 'Great Leap Forward', 'The Great Leap Forward 1958–62 caused the worst famine in history killing 15–55 million people; Mao refused to acknowledge the catastrophe.', 'range', 1958, 1962, '#059669'),
  ('a0000000-0000-0000-0000-000000000033', 'Work & Education', 'Cultural Revolution', 'Launched the Cultural Revolution in 1966 to purge rivals; millions suffered; temples were destroyed; intellectuals were sent to labour camps.', 'range', 1966, 1976, '#047857'),
  ('a0000000-0000-0000-0000-000000000033', 'Health', 'Declined health in final years', 'Suffered from ALS and heart disease in his final years; refused Western medicine; received foreign visitors while visibly declining.', 'range', 1973, 1976, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000033', 'Relations & Family', 'Jiang Qing (fourth wife)', 'Married actress Jiang Qing in 1938; she led the Gang of Four during the Cultural Revolution; arrested after Mao''s death and imprisoned.', 'range', 1938, 1976, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000033', 'Relations & Family', 'Nixon visit', 'Met US President Nixon in February 1972; the rapprochement between China and America shocked the world; engineered partly by Kissinger''s secret diplomacy.', 'point', 1972, NULL, '#db2777'),
  ('a0000000-0000-0000-0000-000000000033', 'Activities', 'Swimming in the Yangtze', 'Made highly publicised swims in the Yangtze River to demonstrate his health and power; the 1966 swim was timed at over 9 mph — widely exaggerated.', 'range', 1956, 1966, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000033', 'Activities', 'Poetry writing', 'Was a genuine and accomplished classical Chinese poet; his poems about revolution and landscape are taught in Chinese schools; published six collections.', 'range', 1925, 1976, '#d97706'),
  ('a0000000-0000-0000-0000-000000000033', 'Assets', 'Zhongnanhai compound', 'Lived and worked in the Zhongnanhai compound adjacent to the Forbidden City; his private swimming pool was a symbol of his privileges.', 'range', 1949, 1976, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000033', 'Items', 'Little Red Book', 'His Quotations from Chairman Mao Tse-tung (the Little Red Book) was distributed to every Chinese citizen; over 5 billion copies were printed.', 'range', 1964, 1976, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000034', 'Place & Travel', 'Greenwich Palace, London', 'Born at Greenwich to Henry VIII and Anne Boleyn; her mother was executed when she was 2; declared illegitimate then re-legitimised by Parliament.', 'range', 1533, 1558, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000034', 'Place & Travel', 'Tower of London (imprisonment)', 'Imprisoned in the Tower by her Catholic half-sister Mary I in 1554 suspected of involvement in Wyatt''s rebellion; survived by careful diplomacy.', 'range', 1554, 1558, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000034', 'Place & Travel', 'Progress tours of England', 'Conducted annual summer progresses through England staying at nobles'' homes; used them to show herself to her subjects and inspire loyalty.', 'range', 1559, 1603, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000034', 'Work & Education', 'Education under tutors', 'Given a Renaissance humanist education; learned Latin, Greek, French, Italian, Spanish; studied rhetoric, history, and philosophy; was exceptionally learned.', 'range', 1538, 1558, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000034', 'Work & Education', 'Accession and religious settlement', 'Became queen in November 1558; established the Elizabethan Religious Settlement making the Church of England the middle way between Catholicism and Puritanism.', 'range', 1558, 1563, '#10b981'),
  ('a0000000-0000-0000-0000-000000000034', 'Work & Education', 'Spanish Armada defeated', 'The defeat of the Spanish Armada in 1588 was the defining event of her reign; her Tilbury speech — "heart and stomach of a king" — is among the greatest orations in English history.', 'point', 1588, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000034', 'Work & Education', 'Elizabethan cultural golden age', 'Her reign saw Shakespeare, Marlowe, Spenser, Byrd, and Drake; the golden age of English exploration including Raleigh''s American ventures.', 'range', 1580, 1603, '#047857'),
  ('a0000000-0000-0000-0000-000000000034', 'Health', 'Smallpox and the white makeup', 'Survived a near-fatal bout of smallpox in 1562; the pockmarks were hidden under thick white ceruse lead makeup which eventually damaged her skin.', 'range', 1562, 1603, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000034', 'Relations & Family', '"The Virgin Queen"', 'Never married despite many suitors including Philip II of Spain, Archduke Charles, and her beloved Robert Dudley; her virginity became a political and mythological asset.', 'range', 1558, 1603, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000034', 'Relations & Family', 'Robert Dudley, Earl of Leicester', 'Her most intimate favourite from childhood; their relationship caused scandal; she called him her "Eyes"; his wife Amy Robsart died in suspicious circumstances.', 'range', 1559, 1588, '#db2777'),
  ('a0000000-0000-0000-0000-000000000034', 'Relations & Family', 'Execution of Mary Queen of Scots', 'Signed the warrant for her cousin Mary''s execution in 1587 after 19 years of imprisonment; claimed she did so reluctantly.', 'point', 1587, NULL, '#f97316'),
  ('a0000000-0000-0000-0000-000000000034', 'Activities', 'Music and dancing', 'Was an accomplished lutenist and virginalist; danced vigorously into her sixties; music was central to her court entertainment.', 'range', 1550, 1600, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000034', 'Assets', 'Royal palaces', 'Inherited numerous royal palaces including Greenwich, Hampton Court, and Whitehall; used them strategically to project royal magnificence.', 'range', 1558, 1603, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000034', 'Items', 'The Armada Portrait', 'The Armada Portrait painted c.1588 shows Elizabeth with her hand on a globe, the Armada visible in the background; a supreme image of imperial power.', 'point', 1588, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000035', 'Place & Travel', 'Alexandria, Egypt', 'Born in Alexandria; the Ptolemaic capital was the greatest city of the ancient world with its famous Library and Lighthouse.', 'range', -69, -47, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000035', 'Place & Travel', 'Rome (with Caesar)', 'Followed Caesar to Rome in -46; lived there until his assassination in -44; witnessed the chaos that followed and returned to Alexandria.', 'range', -46, -44, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000035', 'Place & Travel', 'Alexandria (kingdom until end)', 'Returned to Egypt after Caesar''s death; allied with Antony; ruled Egypt until their defeat at Actium; died in Alexandria in -30.', 'range', -44, -30, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000035', 'Work & Education', 'Multilingual ruler', 'The only Ptolemaic ruler who bothered to learn Egyptian and several other languages; spoke nine languages including Ethiopic, Hebrew, and Aramaic.', 'range', -55, -30, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000035', 'Work & Education', 'Queen of Egypt — co-ruler with brothers', 'Co-ruled with brother Ptolemy XIII who had her expelled; allied with Caesar to regain the throne; had her brother drowned after victory.', 'range', -51, -47, '#10b981'),
  ('a0000000-0000-0000-0000-000000000035', 'Work & Education', 'Alliance with Julius Caesar', 'Was rolled in a carpet and smuggled into Caesar''s presence in -48; became his ally and lover; he restored her to the throne.', 'range', -48, -44, '#059669'),
  ('a0000000-0000-0000-0000-000000000035', 'Work & Education', 'Alliance with Mark Antony', 'Allied with and married Mark Antony in -36; together they dreamed of an eastern empire; Antony''s Donations of Alexandria gave her eastern territories.', 'range', -41, -30, '#047857'),
  ('a0000000-0000-0000-0000-000000000035', 'Work & Education', 'Battle of Actium and death', 'Defeated at the Battle of Actium in -31 by Octavian; Antony committed suicide; Cleopatra killed herself rather than be paraded in Octavian''s triumph.', 'range', -31, -30, '#10b981'),
  ('a0000000-0000-0000-0000-000000000035', 'Health', 'Death by asp', 'Ancient sources say she died by allowing a poisonous asp to bite her breast; modern scholars debate whether it was poison or asp; she was 39.', 'point', -30, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000035', 'Relations & Family', 'Julius Caesar — Caesarion', 'Her son by Julius Caesar was Caesarion (Ptolemy XV); he was the last Ptolemaic ruler, killed by Octavian shortly after his mother''s death.', 'range', -47, -30, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000035', 'Relations & Family', 'Mark Antony — children', 'Had three children with Antony: Alexander Helios, Cleopatra Selene, and Ptolemy Philadelphus; Selene survived and became Queen of Mauretania.', 'range', -40, -30, '#db2777'),
  ('a0000000-0000-0000-0000-000000000035', 'Activities', 'Philosophy and medicine', 'Was learned in medicine, philosophy, and alchemy; the Leiden papyrus attributes medical treatises on cosmetics and perfumes to her.', 'range', -55, -30, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000035', 'Assets', 'Treasury of Egypt', 'Egypt was the wealthiest kingdom in the world; Cleopatra''s treasury funded Antony''s campaigns; Octavian seized it to fund the Roman Empire.', 'range', -51, -30, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000035', 'Items', 'Pearls dissolved in vinegar', 'Legend says she dissolved a priceless pearl earring in vinegar and drank it to win a bet with Antony about who could host the most expensive dinner.', 'point', -40, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000036', 'Place & Travel', 'Stettin, Prussia (now Poland)', 'Born as Sophie of Anhalt-Zerbst in a minor German principality; her family was of little importance until she was chosen as bride for the Russian heir.', 'range', 1729, 1744, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000036', 'Place & Travel', 'St Petersburg, Russia', 'Arrived in Russia aged 15; converted to Russian Orthodoxy; took the name Catherine; married Peter and spent 18 years enduring his erratic behaviour.', 'range', 1744, 1796, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000036', 'Place & Travel', 'Crimea and Black Sea', 'Her southern expansion reached the Black Sea; toured Crimea with Potemkin in 1787 — the origin of the "Potemkin village" legend.', 'range', 1783, 1796, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000036', 'Work & Education', 'Self-education and Enlightenment reading', 'Educated herself voraciously; corresponded with Voltaire, Diderot, and d''Alembert; invited Diderot to St Petersburg and paid for his library.', 'range', 1744, 1796, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000036', 'Work & Education', 'Coup of 1762 — Empress', 'Overthrew her husband Peter III in a coup six months after his accession; he died shortly after in suspicious circumstances; she ruled alone.', 'point', 1762, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-000000000036', 'Work & Education', 'Administrative and legal reforms', 'Established the Nakaz (Instruction) in 1767 drawing on Montesquieu; reorganised provincial government; codified Russian law.', 'range', 1762, 1796, '#059669'),
  ('a0000000-0000-0000-0000-000000000036', 'Work & Education', 'Wars and territorial expansion', 'Won two wars against the Ottomans; expanded Russia to the Black Sea; partitioned Poland three times; absorbed Crimea in 1783.', 'range', 1768, 1796, '#047857'),
  ('a0000000-0000-0000-0000-000000000036', 'Work & Education', 'Hermitage Museum founding', 'Founded the Hermitage in 1764 with a purchase of 225 Dutch and Flemish paintings; eventually one of the world''s greatest art collections.', 'range', 1764, 1796, '#10b981'),
  ('a0000000-0000-0000-0000-000000000036', 'Health', 'Stroke and death', 'Found collapsed after a stroke in her water closet on 5 November 1796; died the following day aged 67; the lurid contemporary rumours about her death are entirely false.', 'point', 1796, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000036', 'Relations & Family', 'Grigory Orlov (lover)', 'Her relationship with Grigory Orlov — one of the brothers who organised the coup — lasted 12 years; they had a son Gregory Orlov.', 'range', 1760, 1772, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000036', 'Relations & Family', 'Grigory Potemkin (great love)', 'Her relationship with statesman Potemkin may have been a secret morganatic marriage; he was her greatest political partner and possible husband.', 'range', 1774, 1791, '#db2777'),
  ('a0000000-0000-0000-0000-000000000036', 'Activities', 'Art collecting', 'Purchased 2,600 paintings during her reign including Rembrandt masterpieces; said she was eating art with "wolf-like avidity."', 'range', 1764, 1796, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000036', 'Assets', 'Winter Palace and Hermitage', 'The Winter Palace at St Petersburg was her primary residence; the adjacent Hermitage she filled with her art collection.', 'range', 1762, 1796, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000036', 'Items', 'The Imperial crown', 'The Imperial Crown of Russia made for her coronation in 1762 contained 4,936 diamonds and a 398-carat red spinel; it is preserved in the Kremlin.', 'point', 1762, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000037', 'Place & Travel', 'Delüün Boldog, Mongolia', 'Born clutching a blood clot in his fist — an omen of greatness; his father was poisoned when he was 9; he and his family were abandoned by their clan.', 'range', 1162, 1185, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000037', 'Place & Travel', 'Mongolian steppe', 'Spent his early years surviving hardship, captivity, and raiding; slowly assembled alliances and followers across the Mongolian plateau.', 'range', 1172, 1206, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000037', 'Place & Travel', 'China, Central Asia & Persia', 'Led campaigns across northern China, Central Asia, Persia, and as far as Poland; his armies covered distances no army would match for centuries.', 'range', 1206, 1227, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000037', 'Work & Education', 'Unification of Mongolian tribes', 'Proclaimed Genghis Khan ("Universal Ruler") at the kurultai of 1206 after uniting all Mongolian tribes through combination of warfare, diplomacy, and marriage.', 'point', 1206, NULL, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000037', 'Work & Education', 'Invasion of China — Jin Dynasty', 'Launched invasions of northern China in 1211; captured Zhongdu (Beijing) in 1215; incorporated Chinese siege engineers and administrators.', 'range', 1211, 1227, '#10b981'),
  ('a0000000-0000-0000-0000-000000000037', 'Work & Education', 'Conquest of Central Asia', 'The destruction of the Khwarezm Empire 1219–1221 included the massacre of cities like Samarkand and Merv; changed the demographic map of Central Asia.', 'range', 1219, 1221, '#059669'),
  ('a0000000-0000-0000-0000-000000000037', 'Work & Education', 'Yasa law code', 'Promulgated the Yasa, a code of laws forbidding theft, adultery, religious discrimination; remarkably tolerant of religions; imposed trade routes.', 'range', 1206, 1227, '#047857'),
  ('a0000000-0000-0000-0000-000000000037', 'Health', 'Unknown cause of death', 'Died in August 1227 during the campaign against the Xi Xia; cause unknown — possibly typhoid, wounds, or a fall from a horse.', 'point', 1227, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000037', 'Relations & Family', 'Börte (primary wife)', 'His first and primary wife Börte was kidnapped by the Merkits; he rescued her; their sons formed the ruling dynasty of the Mongol Empire.', 'range', 1178, 1227, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000037', 'Relations & Family', 'Secret burial site', 'Was buried in an unmarked grave in Mongolia at his request; legend says 800 people were killed to keep the location secret; it has never been found.', 'point', 1227, NULL, '#db2777'),
  ('a0000000-0000-0000-0000-000000000037', 'Activities', 'Meritocratic army', 'Organised his army by decimal units; promoted by ability not tribal origin; created the first true meritocracy in the medieval world.', 'range', 1206, 1227, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000037', 'Assets', 'Largest contiguous land empire', 'At its peak the Mongol Empire covered 24 million km²; linked the Silk Road; 8% of the world''s male population may carry his Y-chromosome today.', 'range', 1206, 1227, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000037', 'Items', 'The great bow', 'Mongol composite bows could shoot 300 metres with lethal accuracy; Genghis''s archers could shoot backwards from galloping horses at 40 km/h.', 'range', 1185, 1227, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000038', 'Place & Travel', 'Frankish heartland (modern Belgium)', 'Born probably near Liège; his father Pepin the Short made him co-king; Charlemagne was unusually tall — approximately 6''4" by medieval estimates.', 'range', 742, 768, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000038', 'Place & Travel', 'Rome — coronation', 'Travelled to Rome multiple times; Pope Leo III crowned him Holy Roman Emperor on Christmas Day 800 — reportedly without prior arrangement.', 'range', 800, 814, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000038', 'Place & Travel', 'Aachen (Aix-la-Chapelle)', 'Made Aachen his capital; built his magnificent palace and chapel there; called it the "Second Rome"; it became the coronation city for German kings.', 'range', 794, 814, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000038', 'Work & Education', 'Military campaigns', 'Fought over 50 campaigns in 47 years; conquered the Saxons in 33-year wars; defeated the Avars; extended Frankish rule across Western Europe.', 'range', 768, 814, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000038', 'Work & Education', 'Carolingian Renaissance', 'Invited scholars to Aachen to revive learning; established cathedral schools; standardised Latin script (Carolingian minuscule); promoted literacy.', 'range', 781, 814, '#10b981'),
  ('a0000000-0000-0000-0000-000000000038', 'Work & Education', 'Holy Roman Emperor', 'Crowned Emperor of the Romans on 25 December 800; unified Western Europe politically for the first time since the fall of Rome.', 'range', 800, 814, '#059669'),
  ('a0000000-0000-0000-0000-000000000038', 'Work & Education', 'Administrative reforms', 'Sent missi dominici (royal envoys) throughout the empire to report on local administration; developed a civil service; standardised weights and measures.', 'range', 789, 814, '#047857'),
  ('a0000000-0000-0000-0000-000000000038', 'Relations & Family', 'Multiple wives and concubines', 'Had four official wives and five concubines; at least 18 children; refused to let his daughters marry (to control succession) but allowed them lovers at court.', 'range', 768, 814, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000038', 'Activities', 'Learning to read as an adult', 'Bizarrely, never learned to read as a child; in his 30s took lessons from Alcuin of York; kept tablets under his pillow to practise writing.', 'range', 780, 814, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000038', 'Activities', 'Swimming', 'Was an enthusiastic and strong swimmer; the hot springs at Aachen were a primary reason he chose it as his capital.', 'range', 780, 814, '#d97706'),
  ('a0000000-0000-0000-0000-000000000038', 'Assets', 'Carolingian Empire', 'Ruled an empire covering modern France, Germany, Italy, Switzerland, Belgium, and the Netherlands; the direct ancestor of both France and Germany.', 'range', 768, 814, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000038', 'Items', 'Aachen Cathedral', 'The Palatine Chapel he built at Aachen (now Aachen Cathedral) still stands and contains his throne; it was the first structure north of the Alps to use Roman marble columns.', 'range', 796, 814, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000039', 'Place & Travel', 'Moscow', 'Born in Moscow; his father Tsar Alexis died when he was 4; spent childhood fighting for power against the Streltsy (palace guard) and his half-sister Sophia.', 'range', 1672, 1697, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000039', 'Place & Travel', 'Grand Embassy to Western Europe', 'Led the Grand Embassy of 1697–98 incognito through Holland, England, and Vienna; worked as a shipwright in Amsterdam; recruited 750 Western specialists.', 'range', 1697, 1698, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000039', 'Place & Travel', 'St Petersburg — new capital', 'Founded St Petersburg in 1703 in a swamp on the Baltic; moved the Russian capital there; called it his "window to the West"; over 30,000 workers died building it.', 'range', 1703, 1725, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000039', 'Work & Education', 'Military campaigns — Great Northern War', 'Defeated Sweden at the Battle of Poltava in 1709; turned Russia into a Baltic power; won access to Europe through the "window to the West."', 'range', 1700, 1721, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000039', 'Work & Education', 'Western reforms', 'Forced nobles to shave their beards; introduced Western dress; reformed the calendar; established the Russian Navy; created the Table of Ranks.', 'range', 1698, 1725, '#10b981'),
  ('a0000000-0000-0000-0000-000000000039', 'Work & Education', 'Emperor of All Russia', 'Proclaimed Emperor in 1721 after the Northern War victory; the title Tsar was replaced with Emperor; Russia was now a European great power.', 'point', 1721, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000039', 'Work & Education', 'Russian Academy of Sciences', 'Founded the Russian Academy of Sciences in 1724, one year before his death; it became one of Europe''s great scientific institutions.', 'point', 1724, NULL, '#047857'),
  ('a0000000-0000-0000-0000-000000000039', 'Health', 'Kidney disease', 'Suffered from kidney and bladder disease from the early 1720s; complications led to his death in February 1725 without naming a successor.', 'range', 1722, 1725, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000039', 'Relations & Family', 'Catherine I (second wife)', 'Married his former mistress, a Lithuanian peasant woman, as Catherine I in 1712; she succeeded him as Russia''s first female ruler.', 'range', 1703, 1725, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000039', 'Relations & Family', 'Alexei (son) — executed', 'Had his own son and heir Alexei tortured to death in 1718 for opposing his reforms and allegedly plotting against him.', 'point', 1718, NULL, '#db2777'),
  ('a0000000-0000-0000-0000-000000000039', 'Activities', 'Shipbuilding and carpentry', 'Was an extraordinary practical craftsman; worked as a ship''s carpenter under a false name in Zaandam; his tools survive in a Dutch museum.', 'range', 1683, 1720, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000039', 'Activities', 'Tooth extraction hobby', 'Kept a bag of the teeth he had extracted himself; practised dentistry on unwilling courtiers; the bag of teeth is preserved in St Petersburg.', 'range', 1698, 1725, '#d97706'),
  ('a0000000-0000-0000-0000-000000000039', 'Assets', 'St Petersburg palaces', 'Built the Summer Palace, the Peterhof, and the Peter and Paul Fortress; the city he built is now UNESCO-listed and one of the world''s most beautiful.', 'range', 1703, 1725, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000039', 'Items', 'The Amber Room', 'Received the Amber Room from Prussia as a diplomatic gift; installed in the Catherine Palace; stolen by the Nazis in WWII; its fate remains a mystery.', 'range', 1716, 1725, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000003a', 'Place & Travel', 'Schönhausen, Prussia', 'Born into a Junker (Prussian landowning) family; grew up on the family estate; his father was an unsophisticated farmer, his mother a formidable intellectual.', 'range', 1815, 1835, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003a', 'Place & Travel', 'Berlin, Frankfurt & St Petersburg', 'Studied law in Berlin; served as Prussian envoy to the Frankfurt Diet and as ambassador to St Petersburg and Paris.', 'range', 1835, 1862, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003a', 'Place & Travel', 'Berlin — Chancellor', 'Served as Minister-President of Prussia then Chancellor of the German Empire from Berlin; Friedrichsruh estate in Hamburg was his beloved retreat.', 'range', 1862, 1898, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000003a', 'Work & Education', 'Law and diplomacy', 'Studied law at Göttingen and Berlin; worked briefly as a magistrate; entered Prussian politics as a conservative reactionary.', 'range', 1832, 1847, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000003a', 'Work & Education', 'Prussian Minister-President', 'Appointed Prussian Prime Minister in 1862; immediately began the constitutional crisis over army funding; built up the Prussian military.', 'range', 1862, 1871, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003a', 'Work & Education', 'Wars of German Unification', 'Orchestrated wars against Denmark (1864), Austria (1866), and France (1870–71) to unite the German states under Prussian leadership.', 'range', 1864, 1871, '#059669'),
  ('a0000000-0000-0000-0000-00000000003a', 'Work & Education', 'Chancellor of the German Empire', 'Became first Chancellor of the united German Empire proclaimed at Versailles in 1871; dominated European diplomacy for 20 years.', 'range', 1871, 1890, '#047857'),
  ('a0000000-0000-0000-0000-00000000003a', 'Work & Education', 'Social insurance reforms', 'Introduced health insurance (1883), accident insurance (1884), and old-age pensions (1889) — the foundations of the modern welfare state — to undercut socialism.', 'range', 1883, 1889, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003a', 'Health', 'Dismissed by Kaiser Wilhelm II', 'Forced to resign by the young Kaiser Wilhelm II in 1890 — the famous "dropping of the pilot" cartoon; spent his final years on his estate writing memoirs.', 'point', 1890, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000003a', 'Relations & Family', 'Johanna von Puttkamer (wife)', 'Married the pious Johanna von Puttkamer in 1847; deeply in love; her devout Protestantism influenced his religious development.', 'range', 1847, 1894, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000003a', 'Activities', 'Dueling and drinking', 'As a student fought 25 duels at Göttingen; maintained a hard-drinking, hard-riding country squire lifestyle throughout his life despite poor health.', 'range', 1832, 1850, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000003a', 'Activities', 'Realpolitik diplomacy', 'Coined the concept of Realpolitik — pragmatic politics based on power rather than ideology; his foreign policy system kept Europe at peace for 20 years.', 'range', 1862, 1890, '#d97706'),
  ('a0000000-0000-0000-0000-00000000003a', 'Assets', 'Friedrichsruh estate', 'Received the Sachsenwald forest estate at Friedrichsruh as a gift from a grateful Prussian nation after the 1870 war; his home in retirement.', 'range', 1871, 1898, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000003a', 'Items', 'The pickled herring', 'Was famous for his prodigious appetite; reportedly ate a pound of pickled herring at one sitting; his excessive eating contributed to his health problems.', 'range', 1862, 1898, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000003b', 'Place & Travel', 'Simbirsk (now Ulyanovsk), Russia', 'Born into a middle-class family; his elder brother Alexander was hanged in 1887 for plotting to assassinate Tsar Alexander III — radicalising Lenin.', 'range', 1870, 1893, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003b', 'Place & Travel', 'Siberian exile', 'Arrested and exiled to Siberia for three years 1897–1900; met and married Nadezhda Krupskaya; studied Marx and wrote The Development of Capitalism in Russia.', 'range', 1897, 1900, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000003b', 'Place & Travel', 'Western Europe — exile', 'Spent years in exile in London, Geneva, and Zurich; founded the Bolshevik party; published Iskra (The Spark) newspaper from abroad.', 'range', 1900, 1917, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000003b', 'Work & Education', 'Kazan University — law', 'Entered Kazan University; expelled for participating in a student protest; eventually received his law degree externally from St Petersburg University.', 'range', 1887, 1893, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000003b', 'Work & Education', 'What Is To Be Done? (1902)', 'His 1902 pamphlet argued for a vanguard party of professional revolutionaries; the organisational blueprint for the Bolshevik party.', 'point', 1902, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003b', 'Work & Education', 'Return to Russia — sealed train', 'Travelled from Zurich to Petrograd in the famous "sealed train" arranged by Germany in April 1917; immediately proclaimed the April Theses demanding revolution.', 'point', 1917, NULL, '#059669'),
  ('a0000000-0000-0000-0000-00000000003b', 'Work & Education', 'Bolshevik Revolution — October 1917', 'Led the October Revolution that overthrew the Provisional Government; created the world''s first communist state; signed the Treaty of Brest-Litovsk.', 'point', 1917, NULL, '#047857'),
  ('a0000000-0000-0000-0000-00000000003b', 'Work & Education', 'Civil War and NEP', 'Led the Bolsheviks through the brutal Civil War 1918–22; introduced the New Economic Policy in 1921 allowing limited capitalism after the economy collapsed.', 'range', 1918, 1924, '#10b981'),
  ('a0000000-0000-0000-0000-00000000003b', 'Health', 'Assassination attempt and strokes', 'Shot twice in 1918 by Fanny Kaplan; bullets remained in his body; suffered three major strokes 1922–23; incapacitated for his final two years.', 'range', 1918, 1924, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000003b', 'Relations & Family', 'Nadezhda Krupskaya (wife)', 'Married Nadezhda Krupskaya in Siberian exile in 1898; she was his political partner and organiser; managed Bolshevik correspondence networks.', 'range', 1898, 1924, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000003b', 'Relations & Family', 'Inessa Armand', 'Had a close relationship — possibly romantic — with French-Russian revolutionary Inessa Armand; she died of cholera in 1920 and Lenin wept publicly.', 'range', 1909, 1920, '#db2777'),
  ('a0000000-0000-0000-0000-00000000003b', 'Activities', 'Chess', 'Was an enthusiastic chess player who played throughout his exile years; said chess was "the gymnasium of the mind."', 'range', 1890, 1922, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000003b', 'Assets', 'Gorki estate', 'Spent his final incapacitated years at the Gorki estate outside Moscow; it is now a museum; he died there in January 1924.', 'range', 1921, 1924, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000003b', 'Items', 'Mausoleum on Red Square', 'His embalmed body has been displayed in the Lenin Mausoleum on Red Square since 1924; over 100 million people have viewed it; debate about removal continues.', 'range', 1924, 1924, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000042', 'Place & Travel', 'Caracas, Venezuela', 'Born into one of the wealthiest Creole families in Venezuela; orphaned at age 9; educated by private tutors including Simón Rodríguez.', 'range', 1783, 1799, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000042', 'Place & Travel', 'Spain, France & Italy', 'Travelled to Europe; married Teresa del Toro; she died of yellow fever eight months later; his grief turned him toward revolution.', 'range', 1799, 1807, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000042', 'Place & Travel', 'Liberation campaigns across South America', 'Crossed the Andes in 1819 in a legendary military manoeuvre to liberate New Granada; campaigns took him from Venezuela to Peru.', 'range', 1810, 1830, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000042', 'Work & Education', 'Education and political formation', 'Studied Rousseau, Voltaire, Montesquieu, and Locke; his tutor Rodríguez took him to Rome where he vowed on the Monte Sacro to liberate Spanish America.', 'range', 1796, 1810, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000042', 'Work & Education', 'Venezuelan independence campaigns', 'Returned to Venezuela in 1810 after the Caracas uprising; led increasingly successful independence campaigns despite multiple defeats and exiles.', 'range', 1810, 1821, '#10b981'),
  ('a0000000-0000-0000-0000-000000000042', 'Work & Education', 'Battle of Boyacá — liberation of Colombia', 'Won the decisive Battle of Boyacá in August 1819; established the Republic of Gran Colombia (Colombia, Venezuela, Ecuador, Panama).', 'point', 1819, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000042', 'Work & Education', 'Liberation of Peru and Bolivia', 'Liberated Peru in 1824 at the Battle of Ayacucho; Upper Peru was named Bolivia in his honour; he drafted its constitution.', 'range', 1823, 1826, '#047857'),
  ('a0000000-0000-0000-0000-000000000042', 'Health', 'Tuberculosis', 'Suffered from tuberculosis for years; Gran Colombia disintegrated around him as he died; died destitute in Santa Marta, Colombia in 1830 aged 47.', 'range', 1826, 1830, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000042', 'Relations & Family', 'Teresa del Toro (wife)', 'Married Teresa del Toro in Madrid in 1802; she died of yellow fever in Caracas in 1803; Bolívar swore never to remarry and kept that promise.', 'range', 1802, 1803, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000042', 'Relations & Family', 'Manuela Sáenz', 'Ecuadorian revolutionary Manuela Sáenz was his companion for eight years; she saved his life during the September conspiracy; was exiled after his death.', 'range', 1822, 1830, '#db2777'),
  ('a0000000-0000-0000-0000-000000000042', 'Activities', 'Andean crossing', 'Led 2,500 soldiers and 500 women and children across the Andes at 13,000 feet in midwinter in 1819; only 1,200 survived; considered his greatest feat.', 'point', 1819, NULL, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000042', 'Assets', 'Lost fortune', 'Was one of the wealthiest men in Venezuela; spent his entire fortune on the independence campaigns; died owning almost nothing.', 'range', 1783, 1830, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000042', 'Items', 'Sword of Bolívar', 'His ceremonial sword became a symbol of South American liberation; stolen from the Quinta de Bolívar museum by the M-19 guerrilla group in 1974.', 'range', 1813, 1830, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000043', 'Place & Travel', 'Berlin, Prussia', 'Born in Berlin; his father Frederick William I was a brutal disciplinarian who despised his son''s interest in music and philosophy; tried to flee to England aged 18 and was imprisoned.', 'range', 1712, 1740, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000043', 'Place & Travel', 'Sanssouci, Potsdam', 'Built his beloved rococo palace Sanssouci ("without worries") at Potsdam in 1747; spent summers there surrounded by philosophers and musicians.', 'range', 1747, 1786, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000043', 'Place & Travel', 'Silesia and Seven Years'' War campaigns', 'Military campaigns across Silesia, Saxony, and Bohemia during the Seven Years'' War made him the greatest military commander of the 18th century.', 'range', 1740, 1763, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000043', 'Work & Education', 'Philosophical and musical education', 'Despite his father''s opposition, studied philosophy and music; became an accomplished flautist who composed 121 flute sonatas; corresponded with Voltaire.', 'range', 1726, 1740, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000043', 'Work & Education', 'Invasion of Silesia', 'Upon becoming king in 1740 immediately invaded Silesia (Habsburg territory); won it in the War of Austrian Succession; doubled Prussia''s population.', 'range', 1740, 1748, '#10b981'),
  ('a0000000-0000-0000-0000-000000000043', 'Work & Education', 'Seven Years'' War', 'Fought simultaneously against Austria, France, Russia, and Sweden; against overwhelming odds survived through brilliant tactics and luck (the "Miracle of the House of Brandenburg").', 'range', 1756, 1763, '#059669'),
  ('a0000000-0000-0000-0000-000000000043', 'Work & Education', 'Domestic reforms', 'Reformed Prussian law, promoted religious tolerance, built roads, drained swamps, and invited persecuted religious minorities to Prussia.', 'range', 1740, 1786, '#047857'),
  ('a0000000-0000-0000-0000-000000000043', 'Health', 'Childless by choice', 'Had no children; his marriage to Elisabeth Christine was a dynastic formality; he lived apart from her and spent little time with her.', 'range', 1733, 1786, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000043', 'Relations & Family', 'Elisabeth Christine of Brunswick', 'Married under his father''s compulsion; they had no children; Frederick lived separately at Sanssouci and allowed her to reside at Schönhausen palace.', 'range', 1733, 1786, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000043', 'Relations & Family', 'Voltaire at Sanssouci', 'Hosted Voltaire at Sanssouci for three years 1750–53; their relationship was intellectually intoxicating but ended acrimoniously over a plagiarism dispute.', 'range', 1750, 1753, '#db2777'),
  ('a0000000-0000-0000-0000-000000000043', 'Activities', 'Flute playing', 'Was a gifted flautist who practised several hours daily; performed at his own concerts at Sanssouci; Carl Philipp Emanuel Bach was his court musician.', 'range', 1728, 1780, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000043', 'Assets', 'Sanssouci and Prussian treasury', 'The Sanssouci palace complex at Potsdam is now a UNESCO World Heritage Site; his military victories vastly enriched the Prussian treasury.', 'range', 1747, 1786, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000043', 'Items', 'Silver flute', 'His silver Quantz flutes are preserved in German museums; he continued playing even in old age when gout made it painful to hold the instrument.', 'range', 1740, 1780, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000047', 'Place & Travel', 'Greenwich Palace, London', 'Born at Greenwich; second son of Henry VII; became heir after his elder brother Arthur died aged 15; inherited the throne at 17.', 'range', 1491, 1509, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000047', 'Place & Travel', 'Hampton Court and other palaces', 'Acquired Hampton Court from Cardinal Wolsey; owned over 50 royal houses and palaces; built Nonsuch Palace as the most extravagant in England.', 'range', 1509, 1547, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000047', 'Place & Travel', 'Field of the Cloth of Gold, France', 'Met Francis I of France at the Field of the Cloth of Gold in 1520 — a two-week spectacle of mutual display between the two most powerful rulers in Western Europe.', 'range', 1520, 1520, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000047', 'Work & Education', 'Renaissance prince education', 'Educated as a Renaissance prince; could play the lute and organ; wrote love songs and religious motets; spoke Latin, French, and Spanish fluently.', 'range', 1491, 1509, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000047', 'Work & Education', 'Break with Rome — Church of England', 'Broke with the Catholic Church in 1534 to annul his marriage to Catherine of Aragon; made himself Supreme Head of the Church of England; dissolved the monasteries.', 'range', 1527, 1540, '#10b981'),
  ('a0000000-0000-0000-0000-000000000047', 'Work & Education', 'Dissolution of the monasteries', 'Dissolved over 800 monasteries 1536–41; seized their wealth and lands; the income financed his court and military campaigns; transformed England''s landscape.', 'range', 1536, 1541, '#059669'),
  ('a0000000-0000-0000-0000-000000000047', 'Work & Education', 'Six wives', 'Married six times: Catherine of Aragon (divorced), Anne Boleyn (beheaded), Jane Seymour (died), Anne of Cleves (divorced), Catherine Howard (beheaded), Catherine Parr (survived).', 'range', 1509, 1547, '#047857'),
  ('a0000000-0000-0000-0000-000000000047', 'Health', 'Obesity and jousting injury', 'Was athletic in youth; a jousting accident in 1536 may have caused personality changes; in later years grew enormously fat with a 54-inch waist.', 'range', 1536, 1547, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000047', 'Relations & Family', 'Anne Boleyn (second wife)', 'His obsession with Anne Boleyn caused the English Reformation; she bore him Elizabeth I but was beheaded on charges of adultery and treason in 1536.', 'range', 1533, 1536, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000047', 'Relations & Family', 'Jane Seymour — Edward VI', 'His third and reportedly favourite wife Jane Seymour finally gave him a male heir (Edward VI); she died of puerperal fever 12 days after the birth.', 'range', 1536, 1537, '#db2777'),
  ('a0000000-0000-0000-0000-000000000047', 'Activities', 'Tennis and jousting', 'Was an outstanding tennis player, jouster, and horseman in his youth; his jousting armour is preserved at the Tower of London showing his early athletic build.', 'range', 1505, 1536, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000047', 'Assets', 'Monastic lands and treasures', 'The dissolution of the monasteries gave him an enormous one-off windfall; most was spent on wars and palaces; the Crown remained solvent through it.', 'range', 1536, 1547, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000047', 'Items', 'The Holbein portrait', 'Hans Holbein''s iconic 1537 portrait showing Henry wide-legged and dominant became the definitive image of Tudor kingship; influenced royal portraiture for generations.', 'point', 1537, NULL, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000049', 'Place & Travel', 'Talbot County, Maryland', 'Born into slavery; never knew his father (likely a white enslaver); separated from his mother as an infant; witnessed terrible brutality.', 'range', 1818, 1838, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000049', 'Place & Travel', 'New York & New Bedford', 'Escaped slavery in 1838 disguised as a sailor; settled in New Bedford, Massachusetts; worked as a labourer; joined the Massachusetts Anti-Slavery Society.', 'range', 1838, 1845, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000049', 'Place & Travel', 'Britain and Ireland (1845–47)', 'Toured Britain and Ireland for two years giving speeches; British supporters purchased his freedom; returned to America as a free man.', 'range', 1845, 1847, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000049', 'Work & Education', 'Self-education', 'Secretly taught himself to read using the Columbian Orator; the white wife of his enslaver started teaching him until her husband intervened.', 'range', 1828, 1838, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000049', 'Work & Education', 'Abolitionist lecturer', 'Became the most celebrated orator of the abolitionist movement; his ability to speak and write English of the highest calibre constantly surprised racist audiences.', 'range', 1841, 1865, '#10b981'),
  ('a0000000-0000-0000-0000-000000000049', 'Work & Education', 'Narrative of the Life of Frederick Douglass', 'Published his autobiography in 1845; a landmark of American literature and the most influential slave narrative ever written.', 'point', 1845, NULL, '#059669'),
  ('a0000000-0000-0000-0000-000000000049', 'Work & Education', 'The North Star newspaper', 'Founded the anti-slavery newspaper The North Star in Rochester in 1847; later renamed Frederick Douglass'' Paper; published for 16 years.', 'range', 1847, 1863, '#047857'),
  ('a0000000-0000-0000-0000-000000000049', 'Work & Education', 'Advising Lincoln and post-war roles', 'Met Lincoln three times; advocated for Black military service; after the war became Marshal of DC, Recorder of Deeds, and US Minister to Haiti.', 'range', 1863, 1895, '#10b981'),
  ('a0000000-0000-0000-0000-000000000049', 'Health', 'Escaped recapture threats', 'After his autobiography revealed his identity, his enslaver sought to recapture him; sympathisers raised $711.66 to purchase his freedom legally.', 'range', 1845, 1847, '#ef4444'),
  ('a0000000-0000-0000-0000-000000000049', 'Relations & Family', 'Anna Murray (first wife)', 'Married free Black woman Anna Murray before his escape; she helped fund his flight; they had five children; she died in 1882.', 'range', 1838, 1882, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000049', 'Relations & Family', 'Helen Pitts (second wife)', 'Married white abolitionist Helen Pitts in 1884; the interracial marriage caused outrage on both sides; he said he was an example that race was irrelevant.', 'range', 1884, 1895, '#db2777'),
  ('a0000000-0000-0000-0000-000000000049', 'Activities', '"What to the Slave Is the Fourth of July?" speech', 'His 1852 speech at Rochester remains one of the greatest examples of American oratory; confronted white audiences with the hypocrisy of celebrating freedom.', 'point', 1852, NULL, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000049', 'Assets', 'Cedar Hill estate', 'Purchased Cedar Hill in Anacostia, Washington DC in 1877; the estate is now the Frederick Douglass National Historic Site.', 'range', 1877, 1895, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000049', 'Items', 'Cane and frock coat', 'In his later years his authoritative appearance — top hat, frock coat, grey hair and beard — made him one of the most recognisable men in America.', 'range', 1870, 1895, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000004a', 'Place & Travel', 'Nghe An Province, Vietnam', 'Born Nguyen Sinh Cung; father was a Confucian scholar and anti-colonialist official; grew up with strong nationalist sentiments in central Vietnam.', 'range', 1890, 1911, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000004a', 'Place & Travel', 'Global travels — France, America, Britain', 'Worked as a cook''s assistant on ocean liners; lived in London, New York, and Paris; discovered socialism in Paris; attended the 1919 Paris Peace Conference.', 'range', 1911, 1924, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000004a', 'Place & Travel', 'Moscow, China & Vietnam', 'Trained with the Comintern in Moscow; organised Vietnamese revolutionaries in China; finally returned to Vietnam in 1941 after 30 years abroad.', 'range', 1924, 1969, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000004a', 'Work & Education', 'Paris political activism', 'Helped found the French Communist Party in 1920; submitted an appeal for Vietnamese independence at the Paris Peace Conference — ignored.', 'range', 1919, 1924, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000004a', 'Work & Education', 'Founding the Viet Minh', 'Founded the Viet Minh independence movement in 1941 to fight both the Japanese and the French; organised guerrilla resistance from jungle bases.', 'range', 1941, 1954, '#10b981'),
  ('a0000000-0000-0000-0000-00000000004a', 'Work & Education', 'Independence declaration and French war', 'Declared Vietnamese independence on 2 September 1945 quoting the American Declaration of Independence; the French returned and the war lasted until 1954.', 'range', 1945, 1954, '#059669'),
  ('a0000000-0000-0000-0000-00000000004a', 'Work & Education', 'President of North Vietnam', 'Led North Vietnam as president from 1945; the Vietnam War with the US lasted until after his death in 1969.', 'range', 1954, 1969, '#047857'),
  ('a0000000-0000-0000-0000-00000000004a', 'Health', 'Heart failure', 'Died of heart failure on 2 September 1969 — the 24th anniversary of his independence declaration; did not live to see the fall of Saigon in 1975.', 'point', 1969, NULL, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000004a', 'Relations & Family', 'Never married officially', 'Claimed to never have married; likely had a wife Tang Tuyet Minh in China in the 1920s; the relationship was officially denied after his death.', 'range', 1920, 1969, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000004a', 'Activities', 'Ascetic lifestyle', 'Famously lived as simply as possible despite being head of state; wore peasant sandals made from car tyres; lived in a modest stilt house in Hanoi.', 'range', 1945, 1969, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000004a', 'Activities', 'Poetry writing', 'Wrote poetry throughout his life; his Prison Diary written while imprisoned by the Chinese in 1942–43 is considered a Vietnamese literary masterwork.', 'range', 1940, 1969, '#d97706'),
  ('a0000000-0000-0000-0000-00000000004a', 'Assets', 'Ho Chi Minh mausoleum', 'His embalmed body is displayed in a granite mausoleum in Hanoi; Saigon was renamed Ho Chi Minh City after the 1975 reunification.', 'range', 1975, 1975, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000004a', 'Items', 'Car tyre sandals', 'His iconic sandals made from car tyres symbolised his connection to ordinary Vietnamese; became a powerful counter-symbol to Western military equipment.', 'range', 1945, 1969, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000004b', 'Place & Travel', 'Birán, Cuba', 'Born on a sugar plantation in eastern Cuba; father was a Spanish immigrant who became wealthy; grew up in rural eastern Cuba.', 'range', 1926, 1945, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000004b', 'Place & Travel', 'Havana & Mexico City', 'Studied law in Havana; led the failed Moncada attack; imprisoned; exiled to Mexico where he met Che Guevara; planned the Cuban Revolution.', 'range', 1945, 1956, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000004b', 'Place & Travel', 'Sierra Maestra mountains', 'Led guerrilla war from the Sierra Maestra mountains of eastern Cuba 1956–59; his small force grew as Batista''s regime lost support.', 'range', 1956, 1959, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000004b', 'Work & Education', 'University of Havana — law', 'Active in student politics at Havana; participated in attempted coup in Colombia 1948; graduated with a law degree in 1950.', 'range', 1945, 1950, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000004b', 'Work & Education', 'Moncada Barracks attack', 'Led attack on Moncada Barracks on 26 July 1953 with 160 men; the attack failed but the speech at his trial made him famous: "History will absolve me."', 'point', 1953, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000004b', 'Work & Education', 'Cuban Revolution', 'Entered Havana on 8 January 1959; established a communist government; nationalised American businesses; survived CIA Bay of Pigs invasion in 1961.', 'range', 1959, 1965, '#059669'),
  ('a0000000-0000-0000-0000-00000000004b', 'Work & Education', 'Cuban Missile Crisis and Cold War', 'Allowed Soviet nuclear missiles to be installed in Cuba in 1962; the subsequent crisis nearly started WWIII; Cuba remained a Soviet ally throughout the Cold War.', 'range', 1962, 1989, '#047857'),
  ('a0000000-0000-0000-0000-00000000004b', 'Health', 'Survived 638 CIA assassination attempts', 'The CIA made approximately 638 attempts on his life including exploding cigars and a poisoned diving suit; none succeeded; he died of natural causes.', 'range', 1959, 2016, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000004b', 'Relations & Family', 'Mirta Díaz-Balart (first wife)', 'Married Mirta Díaz-Balart in 1948; her brother became a prominent Castro opponent; divorced 1955; their son Fidelito became a nuclear scientist.', 'range', 1948, 1955, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000004b', 'Relations & Family', 'Dalia Soto del Valle (common-law wife)', 'Long-term partner Dalia Soto del Valle lived with him for 40 years; had five sons with her; they married formally in 2016.', 'range', 1965, 2016, '#db2777'),
  ('a0000000-0000-0000-0000-00000000004b', 'Activities', 'Marathon speeches', 'Was famous for speeches lasting 4–7 hours; once spoke for 4 hours and 29 minutes at the UN General Assembly; used speeches to hold the country together.', 'range', 1959, 2008, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000004b', 'Activities', 'Baseball and boxing', 'Was a gifted baseball pitcher who reportedly was scouted by US teams; also boxed; sports were central to his public image.', 'range', 1945, 1960, '#d97706'),
  ('a0000000-0000-0000-0000-00000000004b', 'Assets', 'Forbes estimated wealth', 'Forbes magazine once estimated his personal fortune at $900 million which he furiously denied; Cuba''s state assets were technically his to command.', 'range', 1959, 2016, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000004b', 'Items', 'Olive green military uniform', 'Wore his olive green military uniform as head of state for 50 years; only changed to a tracksuit in 2006 when ill; the uniform was his political persona.', 'range', 1959, 2008, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000004c', 'Place & Travel', 'Rosario, Argentina', 'Born to an upper-middle-class Argentine family; suffered severe asthma from age 2; his family moved frequently seeking better climates for his health.', 'range', 1928, 1948, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000004c', 'Place & Travel', 'Motorcycle journey across South America', 'His 1952 motorcycle journey through South America with Alberto Granado radicalized him; witnessing poverty and inequality transformed his worldview.', 'range', 1952, 1952, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000004c', 'Place & Travel', 'Guatemala, Mexico & Cuba', 'Witnessed the CIA-backed overthrow of Árbenz in Guatemala (1954); met Castro in Mexico; participated in the Cuban Revolution.', 'range', 1954, 1965, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000004c', 'Work & Education', 'Medical degree — Buenos Aires', 'Graduated as a doctor in 1953 despite constant travel and political activity; used his medical expertise as cover during revolutionary work.', 'range', 1948, 1953, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000004c', 'Work & Education', 'Cuban Revolution commander', 'Was one of Castro''s key commanders; led the decisive Battle of Santa Clara in December 1958 that broke the Batista regime.', 'range', 1956, 1959, '#10b981'),
  ('a0000000-0000-0000-0000-00000000004c', 'Work & Education', 'Cuban government roles', 'Served as president of the National Bank of Cuba (1959–61) and Minister of Industries; signed Cuba''s trade agreement with the USSR.', 'range', 1959, 1965, '#059669'),
  ('a0000000-0000-0000-0000-00000000004c', 'Work & Education', 'Guerrilla campaigns in Congo and Bolivia', 'Left Cuba secretly in 1965 to lead failed guerrilla campaigns in Congo then Bolivia; captured and executed without trial in La Higuera on 9 October 1967.', 'range', 1965, 1967, '#047857'),
  ('a0000000-0000-0000-0000-00000000004c', 'Health', 'Chronic asthma', 'Suffered from severe asthma throughout his life; often gasped for breath during guerrilla marches; carried bronchodilators in his field pack.', 'range', 1928, 1967, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000004c', 'Relations & Family', 'Hilda Gadea (first wife)', 'Married Peruvian economist Hilda Gadea in Guatemala; had daughter Hildita; divorced after the Cuban Revolution.', 'range', 1955, 1959, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000004c', 'Relations & Family', 'Aleida March (second wife)', 'Married Cuban revolutionary Aleida March in 1959; had four children; she remained in Cuba after he went to Africa and Bolivia.', 'range', 1959, 1967, '#db2777'),
  ('a0000000-0000-0000-0000-00000000004c', 'Activities', 'Chess', 'Was a passionate chess player who said chess trained the mind for revolution; played against Fidel Castro and Fischer-era grandmasters.', 'range', 1940, 1967, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000004c', 'Activities', 'Motorcycle Diaries journey', 'His diary of the 1952 journey was published posthumously and made into an influential 2004 film; one of the founding texts of Latin American romanticism.', 'range', 1952, 1952, '#d97706'),
  ('a0000000-0000-0000-0000-00000000004c', 'Assets', 'Iconic photograph', 'Alberto Korda''s 1960 photograph of him in a beret became the most reproduced photograph in history; he received no royalties.', 'point', 1960, NULL, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000004c', 'Items', 'Black beret', 'His black beret with red star became the global symbol of revolution; worn throughout his guerrilla campaigns; the beret he wore when captured is preserved.', 'range', 1956, 1967, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000004e', 'Place & Travel', 'Pi-Ramesses, Egypt', 'Born into the 19th Dynasty; served as a captain under his father Seti I from age 10; co-regent from age 14; built a new capital city Pi-Ramesses.', 'range', -1303, -1279, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000004e', 'Place & Travel', 'Nubia and the Levant', 'Campaigned extensively in Nubia and the Levant; fought the Hittite Empire; built temples across Nubia including Abu Simbel.', 'range', -1279, -1213, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000004e', 'Work & Education', 'Pharaoh of Egypt', 'Became pharaoh in -1279; reigned for 66 years — one of the longest reigns in Egyptian history; had over 100 children with many wives.', 'range', -1279, -1213, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000004e', 'Work & Education', 'Battle of Kadesh', 'Fought the Hittites at Kadesh (Syria) in -1274 — the largest chariot battle in history; the outcome was a stalemate but Ramesses proclaimed it a victory.', 'point', -1274, NULL, '#10b981'),
  ('a0000000-0000-0000-0000-00000000004e', 'Work & Education', 'First recorded peace treaty', 'Signed the Treaty of Kadesh with the Hittite king Hattusili III around -1259 — the oldest surviving peace treaty in history; a copy hangs in the UN.', 'point', -1259, NULL, '#059669'),
  ('a0000000-0000-0000-0000-00000000004e', 'Work & Education', 'Abu Simbel and temple building', 'Built the Abu Simbel temples in Nubia carved from solid rock, with four 20-metre statues of himself; also built the Ramesseum and extensions to Karnak.', 'range', -1264, -1244, '#047857'),
  ('a0000000-0000-0000-0000-00000000004e', 'Work & Education', 'Propaganda machine', 'Had his victories carved on temple walls across Egypt; possibly usurped monuments from previous pharaohs by having his name carved over theirs.', 'range', -1279, -1213, '#10b981'),
  ('a0000000-0000-0000-0000-00000000004e', 'Health', 'Exceptional longevity', 'Lived to approximately 90 — extraordinary for ancient Egypt; suffered from arthritis and hardened arteries; mummified in an unusually well-preserved state.', 'range', -1240, -1213, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000004e', 'Relations & Family', 'Nefertari (chief wife)', 'His chief wife Nefertari was beloved; he built her the most beautiful queen''s tomb in the Valley of the Queens; also built the smaller Abu Simbel temple for her.', 'range', -1279, -1255, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000004e', 'Relations & Family', 'Over 100 children', 'Fathered over 100 children with his many wives; outlived most of his eldest sons; was succeeded by his 13th son Merenptah.', 'range', -1275, -1213, '#db2777'),
  ('a0000000-0000-0000-0000-00000000004e', 'Activities', 'Military campaigns', 'Led campaigns to Nubia aged 10; participated in battles personally; Kadesh was perhaps the biggest chariot battle in history with 5,000 chariots.', 'range', -1289, -1213, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000004e', 'Assets', 'Egyptian Empire at peak', 'Controlled an empire from Nubia to modern Lebanon; Egypt was the wealthiest nation on earth; Ramesses controlled the gold mines of Nubia personally.', 'range', -1279, -1213, '#14b8a6'),
  ('a0000000-0000-0000-0000-00000000004e', 'Items', 'Abu Simbel temples', 'The Abu Simbel temples were carved from a Nubian cliff; in the 1960s UNESCO moved the entire complex 65 metres uphill to save it from the Aswan Dam flooding.', 'range', -1264, -1244, '#64748b');
